    /// Installs the authority-agnostic backend handle.
    ///
    /// A local authority also installs `runtime`; a paired remote authority
    /// installs only this, and every section reads the capabilities it needs
    /// from the facade instead of assuming a local runtime exists.
    pub fn set_backend(&mut self, backend: BackendFacade, cx: &mut Context<Self>) {
        self.terminal_transport = Some(Arc::new(RemoteTerminalTransport::new(
            backend.terminal().clone(),
            cx.background_executor().clone(),
        )));
        self.backend = Some(backend);
        self.error = None;
        if self.runtime.is_none() {
            self.notice = None;
        }
        self.refresh(cx);
    }

    /// Adopt the shared Agent ordering maintained by the workbench so the
    /// Agent sidebar matches the new-session selector.
    pub fn set_agent_ordering(&mut self, ordering: AgentOrdering, cx: &mut Context<Self>) {
        if self.agent_ordering != ordering {
            self.agent_ordering = ordering;
            cx.notify();
        }
    }

    /// Adopt the workbench's per-Agent built-in tool answers.
    ///
    /// `computer_ready` says whether computer use is set up on the authority
    /// this view is attached to; the cards need it because an icon that cannot
    /// flip yet has to route to the settings page instead.
    pub fn set_agent_tools(
        &mut self,
        agent_tools: vibex_core::AgentToolPreferences,
        computer_ready: bool,
        cx: &mut Context<Self>,
    ) {
        if self.agent_tools == agent_tools && self.computer_tools_ready == computer_ready {
            return;
        }
        self.agent_tools = agent_tools;
        self.computer_tools_ready = computer_ready;
        cx.notify();
    }

    /// Flip one Agent's built-in tool panel.
    ///
    /// The view updates the list it renders so the glyph changes on the same
    /// frame as the click, and reports the intent; the workbench persists it
    /// and is the one that tells the runtime.
    fn toggle_agent_tool(
        &mut self,
        agent_id: String,
        tool: vibex_core::AgentBuiltinTool,
        enabled: bool,
        cx: &mut Context<Self>,
    ) {
        self.agent_tools.set_enabled(&agent_id, tool, enabled);
        cx.emit(ManagementEvent::AgentToolToggled {
            agent_id,
            tool,
            enabled,
        });
        cx.notify();
    }

    pub fn set_runtime(&mut self, runtime: Arc<DesktopRuntime>, cx: &mut Context<Self>) {
        // A local authority serves the sign-in terminal from the in-process
        // manager; installing the runtime therefore replaces the transport a
        // preceding `set_backend` installed for a paired authority.
        self.terminal_transport = Some(Arc::new(LocalTerminalTransport::new(
            runtime.terminals().manager(),
        )));
        let runtime_changed = self
            .runtime
            .as_ref()
            .is_none_or(|current| !Arc::ptr_eq(current, &runtime));
        if runtime_changed {
            self.generation = self.generation.saturating_add(1);
            self.refresh_pending = false;
            self.refresh_stage = ManagementRefreshStage::Idle;
            self.refresh_full_after_content = false;
            self.loading = false;
            self.details_ready = false;
            self.refresh_task = None;
            self.agent_auth_generation = self.agent_auth_generation.saturating_add(1);
            self.clear_agent_auth_terminal(cx);
            self.agent_auth_scope = None;
            self.agent_auth_catalog = None;
            self.agent_auth_context = None;
            self.agent_auth_model_catalog = None;
            self.agent_auth_logout_preview = None;
            self.agent_auth_reauthentication = false;
            self.agent_auth_error = None;
            self.agent_auth_inputs.clear();
            self.agent_auth_clear_values.clear();
        }
        self.runtime = Some(runtime);
        self.error = None;
        self.notice = None;
        if runtime_changed || (self.snapshot.agents.is_empty() && !self.loading) {
            self.refresh(cx);
        }
    }

