    fn test_provider_draft(&mut self, agent_id: String, cx: &mut Context<Self>) {
        let Ok(agent_id) = AgentId::parse(agent_id) else {
            self.error = Some(
                management_error_text(
                    "Agent identity is invalid",
                    "Agent 标识无效",
                    "Agent 識別碼無效",
                )
                .into(),
            );
            cx.notify();
            return;
        };
        let base_url = self.profile_base_url.read(cx).value().trim().to_string();
        let api_key = self.profile_api_key.read(cx).value().trim().to_string();
        if base_url.is_empty() || api_key.is_empty() {
            self.error = Some(
                management_error_text(
                    "Enter a request URL and a key before testing",
                    "请先填写接口地址和 Key 再测试",
                    "請先填寫介面位址和 Key 再測試",
                )
                .into(),
            );
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        if self.mutation.is_some() {
            return;
        }
        self.mutation = Some(ManagementMutation::ProviderProbe(format!(
            "draft-test:{}",
            agent_id.as_str()
        )));
        self.error = None;
        self.notice = None;
        let configured_models = self.profile_configured_models.clone();
        let provider_options = Some(self.profile_provider_options.clone());
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            backend
                .management()
                .fetch_agent_model_provider_draft_models(
                    vibex_core::AgentModelProviderDraftFetchModelsRequest {
                        agent_id,
                        base_url,
                        api_key,
                        configured_models,
                        provider_options,
                    },
                )
                .await
                .map_err(crate::app::remote_error_into_vibex)
        });
        self.mutation_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let failed =
                management_error_text("Connection test failed", "连接测试失败", "連線測試失敗");
            let _ = entity.update(cx, |this, cx| {
                this.mutation = None;
                match outcome {
                    Ok(Ok(response)) => {
                        let latency = response
                            .diagnostics
                            .iter()
                            .find(|diagnostic| diagnostic.key == "latencyMs")
                            .map(|diagnostic| format!(" · {} ms", diagnostic.value))
                            .unwrap_or_default();
                        this.notice = Some(format!(
                            "{} · {}{latency}",
                            management_locale_text("Connection passed", "连接通过", "連線通過"),
                            management_model_count(response.models.len())
                        ));
                    }
                    Ok(Err(error)) => {
                        this.error = Some(format!("{failed}: {}: {}", error.code, error.message));
                    }
                    Err(error) => this.error = Some(format!("{failed}: {error}")),
                }
                cx.notify();
            });
        }));
    }

    fn detect_provider_apis(&mut self, agent_id: String, cx: &mut Context<Self>) {
        let Ok(agent_id) = AgentId::parse(agent_id) else {
            return;
        };
        let base_url = self.profile_base_url.read(cx).value().trim().to_string();
        let api_key = self.profile_api_key.read(cx).value().trim().to_string();
        if base_url.is_empty() || api_key.is_empty() {
            self.error = Some(
                management_error_text(
                    "Enter a request URL and a key before detecting",
                    "请先填写接口地址和 Key 再检测",
                    "請先填寫介面位址和 Key 再偵測",
                )
                .into(),
            );
            cx.notify();
            return;
        }
        let Some(backend) = self.backend.clone() else {
            return;
        };
        if self.mutation.is_some() {
            return;
        }
        self.mutation = Some(ManagementMutation::ProviderProbe(format!(
            "detect:{}",
            agent_id.as_str()
        )));
        self.error = None;
        self.notice = None;
        let provider_options = Some(self.profile_provider_options.clone());
        let entity = cx.weak_entity();
        let runner = gpui_tokio::Tokio::spawn(cx, async move {
            let candidates = [
                vibex_core::ProviderModelWireApi::OpenaiChatCompletions,
                vibex_core::ProviderModelWireApi::OpenaiResponses,
                vibex_core::ProviderModelWireApi::AnthropicMessages,
                vibex_core::ProviderModelWireApi::GoogleGenerativeAi,
            ];
            for wire_api in candidates {
                let probe = vibex_core::ProviderConfiguredModel {
                    id: "__vibex_probe__".to_string(),
                    display_name: None,
                    enabled: true,
                    wire_api: Some(wire_api),
                    capabilities: Default::default(),
                };
                let outcome = backend
                    .management()
                    .fetch_agent_model_provider_draft_models(
                        vibex_core::AgentModelProviderDraftFetchModelsRequest {
                            agent_id: agent_id.clone(),
                            base_url: base_url.clone(),
                            api_key: api_key.clone(),
                            configured_models: vec![probe],
                            provider_options: provider_options.clone(),
                        },
                    )
                    .await;
                if let Ok(response) = outcome {
                    return Ok((wire_api, response.models.len()));
                }
            }
            Err(management_error_text(
                "No supported API answered",
                "没有受支持的 API 响应",
                "沒有受支援的 API 回應",
            )
            .to_string())
        });
        self.mutation_task = Some(cx.spawn(async move |_, cx| {
            let outcome = runner.await;
            let _ = entity.update(cx, |this, cx| {
                this.mutation = None;
                match outcome {
                    Ok(Ok((wire_api, count))) => {
                        this.profile_provider_options = with_provider_option(
                            this.profile_provider_options.clone(),
                            "wireApi",
                            Some(wire_api.wire_protocol_id().to_string()),
                        );
                        this.notice = Some(format!(
                            "{} · {} · {}",
                            management_locale_text("Detected", "已检测", "已偵測"),
                            wire_api.wire_protocol_id(),
                            management_model_count(count)
                        ));
                    }
                    Ok(Err(message)) => this.error = Some(message),
                    Err(error) => {
                        this.error = Some(format!(
                            "{}: {error}",
                            management_error_text(
                                "API detection failed",
                                "API 检测失败",
                                "API 偵測失敗"
                            )
                        ));
                    }
                }
                cx.notify();
            });
        }));
    }

