    /// The picker: every Model the endpoint advertised, plus the ones the draft
    /// already configures, each with the checkbox that decides whether this
    /// Provider offers it.
    fn render_profile_candidates_pane(
        &mut self,
        bounded: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected_agent_id = self.selected_agent_id.clone().unwrap_or_default();
        let pending =
            self.mutation.is_some() || self.agent_mutations.contains_key(&selected_agent_id);
        let editing_profile_id = self.editing_profile_id.clone();
        // A saved Profile fetches from its stored address and Secret. A draft
        // has neither yet, so its fetch appears once the editor itself holds
        // what a fetch needs — a request URL and a key — and the Agent accepts a
        // caller-supplied endpoint. An Agent that pins its own endpoint owns its
        // catalogue too, and that one is only discovered after saving.
        let draft_endpoint_editable = self
            .projection_editor
            .shows(vibex_core::AgentProjectionFormControl::Endpoint)
            && self.projection_editor.fixed_endpoint().is_none()
            && self.projection_editor.credential_surface() == ProjectionCredentialSurface::ApiKey;
        let draft_available = editing_profile_id.is_none()
            && draft_endpoint_editable
            && !selected_agent_id.is_empty();
        let draft_base_url = self.profile_base_url.read(cx).value().trim().to_string();
        let draft_api_key = self.profile_api_key.read(cx).value().trim().to_string();
        let draft_ready =
            draft_available && !draft_base_url.is_empty() && !draft_api_key.is_empty();
        let fetchable = editing_profile_id.is_some() || draft_available;
        let fetching_models = match &self.mutation {
            Some(ManagementMutation::ProviderProbe(action)) => match &editing_profile_id {
                Some(profile_id) => action == &format!("models:{profile_id}"),
                None => action == &format!("draft-models:{selected_agent_id}"),
            },
            _ => false,
        };
        let filter = self
            .profile_model_search
            .read(cx)
            .value()
            .trim()
            .to_string();
        let rows = self.profile_candidate_rows();
        let total = rows.len();
        let visible = rows
            .into_iter()
            .filter(|row| profile_candidate_matches(row, &filter))
            .collect::<Vec<_>>();
        let configured = self.profile_configured_models.len();
        let selected_visible = visible.iter().filter(|row| row.is_configured()).count();
        let all_selected = !visible.is_empty() && selected_visible == visible.len();

        // The pane's caption names the list and counts what the Provider
        // actually offers, which the size of a whole catalogue does not say.
        let offered = if configured == 0 {
            management_locale_text("None offered", "尚未提供", "尚未提供").to_string()
        } else {
            management_model_count(configured)
        };
        let shows_fetch = editing_profile_id.is_some() || draft_ready;
        let fetch = shows_fetch.then(|| {
            let agent_id = selected_agent_id.clone();
            let profile_id = editing_profile_id.clone();
            let base_url = draft_base_url.clone();
            let api_key = draft_api_key.clone();
            div()
                .debug_selector(|| "provider-candidates-fetch".to_string())
                .child(
                    Button::new("provider-candidates-fetch")
                        .xsmall()
                        .outline()
                        // A refresh glyph, not the search glyph: this asks the
                        // endpoint for its list instead of filtering one.
                        .icon(Icon::default().path("icons/vibex/rotate-ccw.svg"))
                        .label(if fetching_models {
                            management_locale_text("Fetching...", "获取中...", "取得中...")
                        } else {
                            management_fetch_models_label()
                        })
                        .loading(fetching_models)
                        .disabled(pending)
                        .on_click(cx.listener(move |this, _, _, cx| match &profile_id {
                            Some(profile_id) => {
                                this.fetch_provider_models(profile_id.clone(), agent_id.clone(), cx)
                            }
                            None => this.fetch_provider_draft_models(
                                agent_id.clone(),
                                base_url.clone(),
                                api_key.clone(),
                                cx,
                            ),
                        })),
                )
                .into_any_element()
        });
        let header = profile_pane_header(
            management_locale_text("Available models", "可选模型", "可選模型"),
            Some(offered.into()),
            fetch,
            cx,
        );

        // "Select all" only means something once there is a choice to make, the
        // bulk switches need a list worth batching, and the search earns its
        // row once the list is long enough to scan.
        let shows_select_all = visible.len() > 1;
        let shows_bulk = configured > 3;
        let shows_search = total > 3;
        let mut controls = h_flex()
            .w_full()
            .min_w_0()
            .flex_none()
            .flex_wrap()
            .items_center()
            .gap_2()
            .px_3()
            .py_1p5()
            .border_b_1()
            .border_color(cx.theme().border);
        if shows_select_all {
            controls = controls.child(
                Checkbox::new("provider-candidates-select-all")
                    .small()
                    .checked(all_selected)
                    .accessibility_label(management_locale_text("Select all", "全选", "全選"))
                    .disabled(pending)
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(management_locale_text("Select all", "全选", "全選")),
                    )
                    .on_click(cx.listener(move |this, checked, window, cx| {
                        this.set_visible_profile_candidates_selected(*checked, window, cx);
                    })),
            );
        }
        if shows_bulk {
            controls = controls
                .child(
                    Button::new("provider-models-enable-all")
                        .xsmall()
                        .ghost()
                        .compact()
                        .label(management_locale_text("Enable all", "全部启用", "全部啟用"))
                        .disabled(pending)
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.set_visible_profile_models_enabled(true, cx)
                        })),
                )
                .child(
                    Button::new("provider-models-disable-all")
                        .xsmall()
                        .ghost()
                        .compact()
                        .label(management_locale_text(
                            "Disable all",
                            "全部停用",
                            "全部停用",
                        ))
                        .disabled(pending)
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.set_visible_profile_models_enabled(false, cx)
                        })),
                );
        }
        if shows_search {
            controls = controls.child(
                div()
                    .min_w_0()
                    .flex_1()
                    .child(management_search_input(&self.profile_model_search, cx)),
            );
        }

        let mut body = v_flex().w_full().gap_1().p_1p5();
        if total == 0 {
            // The empty state names the command that is actually available: a
            // saved Profile already has what a fetch needs, a draft needs the
            // two fields a fetch reads, and an Agent-owned catalogue is only
            // discovered after saving.
            let description = if !fetchable {
                management_locale_text(
                    "Save this Provider to fetch models, or add a model ID directly.",
                    "保存后可以拉取模型，也可以直接添加模型 ID。",
                    "儲存後可以擷取模型，也可以直接新增模型 ID。",
                )
            } else if editing_profile_id.is_some() || draft_ready {
                management_locale_text(
                    "Fetch the endpoint's list, or add a model ID directly.",
                    "可以拉取模型，也可以直接添加模型 ID。",
                    "可以擷取模型，也可以直接新增模型 ID。",
                )
            } else {
                management_locale_text(
                    "Enter an API key and request URL to fetch models, or add a model ID directly.",
                    "填写 API Key 与请求地址后即可拉取模型，也可以直接添加模型 ID。",
                    "填寫 API Key 與請求位址後即可擷取模型，也可以直接新增模型 ID。",
                )
            };
            body = body.child(bare_empty_state(
                management_locale_text("No models fetched", "尚未获取模型", "尚未取得模型"),
                description,
                cx,
            ));
        } else if visible.is_empty() {
            body = body.child(
                EmptyState::new()
                    .flex_none()
                    .gap_2()
                    .p_4()
                    .header(
                        EmptyHeader::new().description(EmptyDescription::new().text_xs().child(
                            management_locale_text(
                                "No model matches this search.",
                                "没有匹配该搜索的模型。",
                                "沒有符合這個搜尋的模型。",
                            ),
                        )),
                    )
                    .content(
                        EmptyContent::new().child(
                            Button::new("provider-candidates-clear-search")
                                .xsmall()
                                .ghost()
                                .compact()
                                .label(management_locale_text(
                                    "Clear search",
                                    "清除搜索",
                                    "清除搜尋",
                                ))
                                .on_click(cx.listener(|this, _, window, cx| {
                                    this.profile_model_search
                                        .update(cx, |state, cx| state.set_value("", window, cx));
                                    cx.notify();
                                })),
                        ),
                    ),
            );
        } else {
            for row in &visible {
                body = body.child(self.render_profile_candidate_row(row, pending, cx));
            }
        }

        let list = if bounded {
            body.min_h_0()
                .flex_1()
                .overflow_y_scrollbar()
                .scroll_gutter()
        } else {
            body.max_h(px(MANAGEMENT_PROFILE_PANE_MAX_HEIGHT))
                .overflow_y_scrollbar()
                .scroll_gutter()
        };

        // A hand-typed Model is a row the catalogue did not offer, so the field
        // that creates it belongs to the list it joins — and it sits in the
        // pane's own foot rather than floating under a list of any length.
        let add_row = h_flex()
            .w_full()
            .min_w_0()
            .flex_none()
            .items_end()
            .gap_2()
            .px_3()
            .py_2()
            .bg(management_surface_wash(cx, MANAGEMENT_PANEL_STRIP_WASH))
            .border_t_1()
            .border_color(cx.theme().border)
            .child(div().min_w_0().flex_1().child(management_input_field(
                management_locale_text("Custom model", "自定义模型", "自訂模型"),
                &self.profile_model_draft,
                false,
                cx,
            )))
            .child(
                Button::new("provider-model-add")
                    .small()
                    .secondary()
                    .icon(IconName::Plus)
                    .label(management_add_label())
                    .disabled(pending)
                    .on_click(
                        cx.listener(|this, _, window, cx| this.add_profile_model(window, cx)),
                    ),
            );

        // A preset's caveats say what its own data cannot: which models the
        // vendor's list leaves out and why. They sit directly above the list
        // because they change the way it should be read, and a model the preset
        // knows about but the endpoint never returns would otherwise look like
        // a bug in the fetch.
        let mut caveats = v_flex().w_full().gap_1p5().px_3().py_2();
        let mut shows_caveats = false;
        if let Some(preset) = self.provider_preset_draft.as_ref() {
            for caveat in &preset.caveats {
                shows_caveats = true;
                caveats = caveats.child(
                    h_flex()
                        .w_full()
                        .min_w_0()
                        .items_start()
                        .gap_1p5()
                        .rounded(px(4.0))
                        .border_1()
                        .border_color(cx.theme().info)
                        .p_2()
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().info)
                                .child(provider_preset_caveat_text(*caveat)),
                        ),
                );
            }
        }

        let mut body_column = v_flex().min_w_0().min_h_0().flex_1();
        if shows_caveats {
            body_column = body_column.child(caveats);
        }
        body_column = body_column.child(list);
        if shows_select_all || shows_bulk || shows_search {
            body_column = v_flex()
                .min_w_0()
                .min_h_0()
                .flex_1()
                .child(controls)
                .child(body_column);
        }

        profile_pane_shell(
            "provider-candidates-pane",
            bounded,
            header,
            body_column.into_any_element(),
            Some(add_row.into_any_element()),
            cx,
        )
    }

    /// One picker row: the checkbox that decides whether the Provider offers
    /// the Model, the body that opens its settings, and the delete command that
    /// takes it back out of the draft.
    ///
    /// A click anywhere on the strip offers the Model and opens its settings,
    /// instead of asking for a second click in the settings pane. It never
    /// releases one: only the checkbox unchecks, so a stray click on a Model
    /// already added cannot drop its declaration. The settings pane follows
    /// every click, because the row it names is the one the click just offered
    /// or opened.
    fn render_profile_candidate_row(
        &self,
        row: &ProfileCandidateRow,
        pending: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let configured = row.is_configured();
        let opened = self.profile_model_selection.as_deref() == Some(row.id.as_str());
        // The id leads the second line only when the first one shows a friendly
        // name; otherwise the id is already the row's identity.
        let mut meta = Vec::new();
        if row.display_name.is_some() {
            meta.push(row.id.clone());
        }
        if let Some(wire_api) = row.wire_api {
            meta.push(provider_wire_api_label(wire_api).to_string());
        }
        if let Some(limits) = profile_model_limits_label(&row.capabilities) {
            meta.push(limits);
        }
        let meta = meta.join(" · ");
        let title = row.display_name.clone().unwrap_or_else(|| row.id.clone());
        let toggled = row.clone();
        let clicked = row.clone();
        let deleted_id = row.id.clone();
        let row_id = row.id.clone();
        let debug_id = row.id.clone();
        h_flex()
            .id(SharedString::from(format!(
                "provider-candidate-row-{row_id}"
            )))
            .w_full()
            .min_w_0()
            .items_center()
            .gap_2()
            .rounded(px(4.0))
            // The leading edge is reserved at rest so the row does not shift
            // when it becomes the one the settings pane is showing.
            .border_l_2()
            .pl_1p5()
            .pr_2()
            .py_1p5()
            .debug_selector(move || format!("provider-candidate-row-{debug_id}"))
            // The wash and the leading edge mark which Model the settings pane
            // is showing; whether the Provider offers it is the checkbox's own
            // answer, and hover is only a pointer cue.
            .border_color(if opened {
                cx.theme().primary.opacity(0.75)
            } else {
                cx.theme().transparent
            })
            .when(opened, |row| {
                row.bg(cx
                    .theme()
                    .primary
                    .opacity(MANAGEMENT_PANEL_ROW_SELECTED_WASH))
            })
            .when(!opened, |row| {
                row.hover(|row| {
                    row.bg(management_surface_wash(cx, MANAGEMENT_PANEL_ROW_HOVER_WASH))
                })
            })
            .cursor_pointer()
            .on_click(cx.listener(move |this, _, window, cx| {
                this.open_profile_candidate_row(&clicked, window, cx);
            }))
            .child(
                // The checkbox answers the same question the row does, and it
                // is the one control that can release a Model: the click it
                // takes is the click the row must not read as a removal.
                div()
                    .id(SharedString::from(format!(
                        "provider-candidate-check-{}",
                        row.id
                    )))
                    .debug_selector({
                        let check_id = row_id.clone();
                        move || format!("provider-candidate-check-{check_id}")
                    })
                    .on_click(|_, _, cx| cx.stop_propagation())
                    .child(
                        Checkbox::new(SharedString::from(format!("provider-candidate-{}", row.id)))
                            .small()
                            .checked(configured)
                            .accessibility_label(SharedString::from(title.clone()))
                            .disabled(pending)
                            .on_click(cx.listener(move |this, checked, window, cx| {
                                this.select_profile_candidate(&toggled, *checked, window, cx);
                            })),
                    ),
            )
            .child(
                div().min_w_0().flex_1().child(
                    v_flex()
                        .min_w_0()
                        .w_full()
                        .gap_0p5()
                        .child(
                            div()
                                .truncate()
                                .text_sm()
                                .font_medium()
                                // An unoffered Model is a name in the
                                // catalogue, not a name in use: it stays
                                // legible but visibly secondary until it is
                                // checked, which is what makes a long
                                // catalogue scannable.
                                .text_color(if configured {
                                    cx.theme().foreground
                                } else {
                                    cx.theme().foreground.opacity(0.75)
                                })
                                .child(title),
                        )
                        .when(!meta.is_empty(), |row| {
                            row.child(
                                div()
                                    .truncate()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(meta),
                            )
                        }),
                ),
            )
            .when(row.is_declared(), |row| {
                row.child(
                    // The delete command is on the row it deletes, so the Model
                    // it removes is the Model the pointer is on, and the trash
                    // keeps its own intention instead of also opening settings.
                    div()
                        .id(SharedString::from(format!(
                            "provider-candidate-delete-wrap-{}",
                            row_id
                        )))
                        .on_click(|_, _, cx| cx.stop_propagation())
                        .child(
                            Button::new(SharedString::from(format!(
                                "provider-candidate-delete-{}",
                                row_id
                            )))
                            .xsmall()
                            .ghost()
                            .compact()
                            .danger()
                            .icon(Icon::default().path("icons/vibex/trash-2.svg"))
                            .tooltip(management_locale_text(
                                "Delete this model",
                                "删除该模型",
                                "刪除該模型",
                            ))
                            .disabled(pending)
                            .on_click(cx.listener(
                                move |this, _, window, cx| {
                                    this.delete_profile_model(deleted_id.clone(), window, cx)
                                },
                            )),
                        ),
                )
            })
            .into_any_element()
    }

    /// The settings pane: the editable fields of the Model the picker has
    /// selected, or the command that adds it when the Provider does not offer
    /// it yet.
    fn render_profile_settings_pane(
        &mut self,
        bounded: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let selected_agent_id = self.selected_agent_id.clone().unwrap_or_default();
        let pending =
            self.mutation.is_some() || self.agent_mutations.contains_key(&selected_agent_id);
        let agent_owns_catalog = AgentId::parse(selected_agent_id)
            .is_ok_and(|agent_id| vibex_core::agent_owns_model_catalog(&agent_id));
        // An Agent that owns its catalogue accepts only the ids it advertises,
        // so its Model field is a closed choice list rather than a free-text
        // id. The picker's rows are that list, because a fetch fills them.
        let catalog_choices = if agent_owns_catalog {
            self.profile_candidate_rows()
                .into_iter()
                .map(|row| (row.id, row.wire_api))
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let editor_context = ProfileModelEditorContext {
            agent_owns_catalog,
            catalog_choices,
            wire_api_choices: self.projection_editor.wire_api_choices(),
            shows_wire_api: self
                .projection_editor
                .shows(vibex_core::AgentProjectionFormControl::WireProtocol),
            pending,
        };
        let selection = self.profile_model_selection.clone();
        let selected_index = self.selected_profile_model_index();
        let selected_title = selection.as_deref().map(|id| {
            self.profile_configured_models
                .iter()
                .find(|model| model.id == id)
                .and_then(|model| model.display_name.clone())
                .unwrap_or_else(|| id.to_string())
        });

        let header = profile_pane_header(
            management_locale_text("Model settings", "模型设置", "模型設定"),
            selected_title.clone().map(SharedString::from),
            None,
            cx,
        );

        let body = match selected_index {
            Some(index) => self.render_profile_model_editor(index, &editor_context, cx),
            None => match selected_title {
                Some(title) => v_flex()
                    .w_full()
                    .items_center()
                    .gap_2()
                    .p_4()
                    .child(div().text_sm().font_medium().child(title))
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(management_locale_text(
                                "This Provider does not offer this model yet.",
                                "该供应商尚未提供这个模型。",
                                "該供應商尚未提供這個模型。",
                            )),
                    )
                    .child(
                        Button::new("provider-model-add-selected")
                            .small()
                            .secondary()
                            .icon(IconName::Plus)
                            .label(management_locale_text(
                                "Add this model",
                                "添加该模型",
                                "新增該模型",
                            ))
                            .disabled(pending)
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.add_selected_profile_model(window, cx)
                            })),
                    )
                    .into_any_element(),
                None => bare_empty_state(
                    management_locale_text("No model selected", "未选择模型", "未選擇模型"),
                    management_locale_text(
                        "Pick a model on the left to edit its settings.",
                        "在左侧点选模型，这里会显示它的设置。",
                        "在左側點選模型，這裡會顯示它的設定。",
                    ),
                    cx,
                ),
            },
        };

        // The settings scroll on their own beside the picker, and grow with the
        // stacked layout, where the body already scrolls. The trailing padding
        // keeps the last control clear of the panel's own edge instead of being
        // cut by it.
        let body = if bounded {
            v_flex()
                .debug_selector(|| "profile-settings-body".to_string())
                .w_full()
                .min_h_0()
                .flex_1()
                .overflow_y_scrollbar()
                .scroll_gutter()
                .child(body)
                .into_any_element()
        } else {
            body
        };

        profile_pane_shell("provider-chosen-pane", bounded, header, body, None, cx)
    }

    /// The editor for one Model, rendered under its own row.
    ///
    /// Every control writes into the draft immediately, so there is no Apply
    /// step to forget and the dialog's single Save carries the whole editor.
    fn render_profile_model_editor(
        &mut self,
        index: usize,
        context: &ProfileModelEditorContext,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let ProfileModelEditorContext {
            agent_owns_catalog,
            catalog_choices,
            wire_api_choices,
            shows_wire_api,
            pending,
        } = context;
        let (agent_owns_catalog, shows_wire_api, pending) =
            (*agent_owns_catalog, *shows_wire_api, *pending);
        let field_error = |field: ProfileModelEditField| {
            self.profile_model_edit_error
                .as_ref()
                .filter(|(current, _)| *current == field)
                .map(|(_, message)| message.clone())
        };
        let id_error = field_error(ProfileModelEditField::Id);
        let reasoning_error = field_error(ProfileModelEditField::Reasoning);
        let limits_error = field_error(ProfileModelEditField::Limits);
        let reasoning_disabled = self.profile_model_edit_reasoning_disabled;
        let enabled = self
            .profile_configured_models
            .get(index)
            .is_none_or(|model| model.enabled);

        // The editor is the settings pane's whole body, so it is a column of
        // that panel rather than a card inside it: the panel already supplies
        // the boundary, and a second one here would nest two boxes.
        let mut editor = v_flex()
            .debug_selector(|| "profile-model-editor".to_string())
            .w_full()
            .min_w_0()
            .gap_4()
            .p_3()
            // Offering the Model is a setting of the Model, so it lives with
            // the rest of them instead of on a list row of its own. It leads
            // the panel because it decides whether any of the rest is read.
            .child(
                h_flex()
                    .debug_selector(|| "profile-model-enable-row".to_string())
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .justify_between()
                    .gap_3()
                    .pb_3()
                    .border_b_1()
                    .border_color(cx.theme().border)
                    .child(
                        v_flex()
                            .min_w_0()
                            .gap_0p5()
                            .child(div().text_sm().font_medium().child(management_locale_text(
                                "Offer this model",
                                "启用该模型",
                                "啟用該模型",
                            )))
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(management_locale_text(
                                        "A disabled model keeps its settings but is not offered to the Agent.",
                                        "停用后仍保留配置，但不会提供给 Agent。",
                                        "停用後仍保留設定，但不會提供給 Agent。",
                                    )),
                            ),
                    )
                    .child(
                        Switch::new(SharedString::from(format!(
                            "provider-model-enabled-{index}"
                        )))
                        .small()
                        .checked(enabled)
                        .disabled(pending)
                        .tooltip(management_enabled_label(enabled))
                        .on_click(cx.listener(move |this, checked, _, cx| {
                            this.toggle_profile_model(index, *checked, cx)
                        })),
                    ),
            );

        if agent_owns_catalog {
            let mut choices = v_flex().w_full().gap_2();
            choices = choices.child(management_choice_group_label(
                management_locale_text(
                    "Model (from the installed Agent)",
                    "模型（来自已安装的 Agent）",
                    "模型（來自已安裝的 Agent）",
                ),
                cx,
            ));
            if catalog_choices.is_empty() {
                choices = choices.child(management_field_hint(
                    management_locale_text(
                        "Fetch models to load the catalogue this Agent advertises.",
                        "请先拉取模型，以载入该 Agent 自带的模型目录。",
                        "請先擷取模型，以載入該 Agent 自帶的模型目錄。",
                    ),
                    cx,
                ));
            } else {
                let mut options = h_flex().w_full().flex_wrap().gap_1p5();
                for (model_id, model_wire_api) in catalog_choices.iter().cloned() {
                    let selected = self.profile_model_edit_id.read(cx).value().trim() == model_id;
                    let label = model_wire_api.map_or_else(
                        || model_id.clone(),
                        |wire_api| format!("{model_id} · {}", provider_wire_api_label(wire_api)),
                    );
                    let click_id = model_id.clone();
                    options = options.child(management_option_chip(
                        SharedString::from(format!("provider-model-catalog-{index}-{model_id}")),
                        SharedString::from(label),
                        selected,
                        pending,
                        None,
                        cx.listener(move |this, _, window, cx| {
                            this.set_profile_model_id_from_catalog(
                                index,
                                click_id.clone(),
                                model_wire_api,
                                window,
                                cx,
                            )
                        }),
                        cx,
                    ));
                }
                choices = choices.child(options);
            }
            editor = editor.child(choices);
        } else {
            editor = editor.child(management_input_field_with_error(
                management_locale_text("Model ID", "模型 ID", "模型 ID"),
                &self.profile_model_edit_id,
                false,
                id_error.as_deref(),
                cx,
            ));
        }
        editor = editor.child(management_input_field(
            management_locale_text("Display name", "显示名称", "顯示名稱"),
            &self.profile_model_edit_name,
            false,
            cx,
        ));

        if shows_wire_api {
            let mut wire_controls = h_flex().w_full().flex_wrap().gap_1p5();
            let candidates = std::iter::once(None)
                .chain(wire_api_choices.iter().copied().map(Some))
                .collect::<Vec<_>>();
            for candidate in candidates {
                let integration = candidate.and_then(|wire_api| {
                    self.projection_editor.wire_api_integration_kind(wire_api)
                });
                let selected = self.profile_model_edit_wire_api == candidate;
                let label = candidate.map_or_else(
                    || management_locale_text("Inherit", "继承", "繼承").to_string(),
                    |wire_api| {
                        let support = integration.map_or_else(
                            || management_locale_text("Unsupported", "不支持", "不支援"),
                            provider_interface_integration_label,
                        );
                        format!("{} · {support}", provider_wire_api_label(wire_api))
                    },
                );
                let unsupported = candidate.is_some() && integration.is_none();
                wire_controls = wire_controls.child(management_option_chip(
                    SharedString::from(format!("provider-model-wire-{index}-{candidate:?}")),
                    SharedString::from(label),
                    selected,
                    pending || unsupported,
                    // Only the blocked chip has something extra to say; the
                    // rest are named by their own labels.
                    unsupported.then(|| {
                        SharedString::from(management_locale_text(
                            "This Agent cannot call this interface",
                            "这个 Agent 还无法调用该接口",
                            "這個 Agent 還無法呼叫該介面",
                        ))
                    }),
                    cx.listener(move |this, _, _, cx| {
                        this.set_profile_model_wire_api(index, candidate, cx)
                    }),
                    cx,
                ));
            }
            editor = editor.child(
                v_flex()
                    .w_full()
                    .gap_1p5()
                    .child(management_choice_group_label(
                        management_locale_text(
                            "Model API protocol",
                            "模型接口协议",
                            "模型介面協定",
                        ),
                        cx,
                    ))
                    .child(wire_controls),
            );
        }

        // Reasoning is two decisions, so it is two controls: whether the Model
        // reasons at all, and which level table its endpoint accepts.
        let mut reasoning = h_flex().w_full().flex_wrap().gap_1p5();
        for (key, label, disabled) in [
            (
                "default",
                management_locale_text(
                    "Follow Agent default",
                    "跟随 Agent 默认",
                    "跟隨 Agent 預設",
                ),
                false,
            ),
            (
                "none",
                management_locale_text("Non-reasoning", "不支持推理", "不支援推理"),
                true,
            ),
        ] {
            let selected = reasoning_disabled == disabled;
            reasoning = reasoning.child(management_option_chip(
                SharedString::from(format!("provider-model-reasoning-{index}-{key}")),
                SharedString::from(label),
                selected,
                pending,
                None,
                cx.listener(move |this, _, window, cx| {
                    this.set_profile_model_reasoning_draft(index, disabled, window, cx)
                }),
                cx,
            ));
        }
        editor = editor.child(
            v_flex()
                .w_full()
                .gap_1p5()
                .child(management_choice_group_label(
                    management_locale_text("Reasoning", "推理能力", "推理能力"),
                    cx,
                ))
                .child(reasoning),
        );

        if !reasoning_disabled {
            // The levels are a set the user clicks together, and the field
            // below stays the place a wire spelling is written, so the chips and
            // the field are two views of one declaration rather than two
            // answers to the same question.
            let declared =
                reasoning_level_entries(&self.profile_model_edit_efforts.read(cx).value());
            let mut levels = h_flex().w_full().flex_wrap().gap_1p5();
            for level in vibex_core::ProviderReasoningEffortLevel::ALL {
                let selected = declared.iter().any(|entry| entry.level() == Some(level));
                let name = level.as_str();
                levels = levels.child(management_option_chip(
                    SharedString::from(format!("provider-model-efforts-level-{index}-{name}")),
                    SharedString::from(name),
                    selected,
                    pending,
                    Some(SharedString::from(if selected {
                        management_locale_text("Remove this level", "取消该档位", "取消該檔位")
                    } else {
                        management_locale_text("Declare this level", "声明该档位", "宣告該檔位")
                    })),
                    cx.listener(move |this, _, window, cx| {
                        this.toggle_profile_model_reasoning_level(index, level, window, cx)
                    }),
                    cx,
                ));
            }
            editor = editor.child(
                v_flex()
                    .w_full()
                    .gap_1p5()
                    .child(management_choice_group_label(
                        management_locale_text("Thinking levels", "思考档位", "思考檔位"),
                        cx,
                    ))
                    .child(levels)
                    .child(management_input_field_with_error(
                        management_locale_text("Declared levels", "档位列表", "檔位清單"),
                        &self.profile_model_edit_efforts,
                        false,
                        reasoning_error.as_deref(),
                        cx,
                    ))
                    .child(management_field_hint(
                        management_locale_text(
                            "Click a level to declare it and click it again to take it back. The field takes any other spelling: levels separated by commas, or level=wire when the endpoint spells one differently. Empty follows the Agent default.",
                            "点击档位即可声明，再次点击取消。也可以在输入框自定义：多个档位用逗号分隔，端点拼写不同时写成 档位=实际值。留空沿用 Agent 默认。",
                            "點擊檔位即可宣告，再次點擊取消。也可以在輸入框自訂：多個檔位用逗號分隔，端點拼寫不同時寫成 檔位=實際值。留空沿用 Agent 預設。",
                        ),
                        cx,
                    )),
            );
        }

        let capability_rows = self.render_profile_model_capabilities(index, pending, cx);
        editor = editor.child(profile_editor_section(
            management_locale_text("Advanced", "高级", "進階"),
            None,
            v_flex()
                .w_full()
                .gap_2p5()
                .children(capability_rows)
                .child(management_token_field(
                    management_locale_text(
                        "Context window (tokens)",
                        "上下文窗口（Token）",
                        "上下文視窗（Token）",
                    ),
                    &self.profile_model_edit_context_tokens,
                    limits_error.as_deref(),
                    &MANAGEMENT_CONTEXT_TOKEN_PRESETS,
                    format!("provider-model-context-preset-{index}"),
                    pending,
                    cx,
                ))
                .child(management_token_field(
                    management_locale_text(
                        "Max output tokens",
                        "最大输出 Token",
                        "最大輸出 Token",
                    ),
                    &self.profile_model_edit_output_tokens,
                    None,
                    &MANAGEMENT_OUTPUT_TOKEN_PRESETS,
                    format!("provider-model-output-preset-{index}"),
                    pending,
                    cx,
                ))
                .children(self.render_capability_suggestions(index, cx))
                .child(management_field_hint(
                    management_locale_text(
                        "Click a value to declare it and click it again to clear it, or type any other count. Empty keeps the Agent's own default; only Agents that read a declared limit are affected.",
                        "点击常用值即可填入，再次点击清除，也可以输入其他数值。留空沿用 Agent 默认；只有会读取该设置的 Agent 受影响。",
                        "點擊常用值即可填入，再次點擊清除，也可以輸入其他數值。留空沿用 Agent 預設；只有會讀取該設定的 Agent 受影響。",
                    ),
                    cx,
                ))
                .into_any_element(),
            cx,
        ));

        editor.into_any_element()
    }

    /// The capability fields the Agent can read, as three-state choices.
    ///
    /// The catalogue only suggests these; a Provider with no catalogue entry
    /// still has to be able to declare them, so the control is here rather than
    /// only inside the suggestion list.
    fn render_profile_model_capabilities(
        &mut self,
        index: usize,
        pending: bool,
        cx: &mut Context<Self>,
    ) -> Vec<AnyElement> {
        let Some(model) = self.profile_configured_models.get(index) else {
            return Vec::new();
        };
        let capabilities = model.capabilities.clone();
        let fields = [
            (
                "imageInput",
                management_locale_text("Image input", "图片输入", "圖片輸入"),
                capabilities.image_input,
            ),
            (
                "pdfInput",
                management_locale_text("PDF input", "PDF 输入", "PDF 輸入"),
                capabilities.pdf_input,
            ),
            (
                "temperature",
                management_locale_text("Honours temperature", "支持温度参数", "支援溫度參數"),
                capabilities.temperature,
            ),
        ];
        let mut rows = Vec::with_capacity(fields.len());
        for (field, label, value) in fields {
            let mut choices = h_flex().w_full().flex_wrap().gap_1p5();
            for (choice, choice_label) in [
                (
                    None,
                    management_locale_text(
                        "Follow Agent default",
                        "跟随 Agent 默认",
                        "跟隨 Agent 預設",
                    ),
                ),
                (
                    Some(true),
                    management_locale_text("Supported", "支持", "支援"),
                ),
                (
                    Some(false),
                    management_locale_text("Unsupported", "不支持", "不支援"),
                ),
            ] {
                let selected = value == choice;
                choices = choices.child(management_option_chip(
                    SharedString::from(format!(
                        "provider-model-capability-{index}-{field}-{}",
                        match choice {
                            None => "inherit",
                            Some(true) => "yes",
                            Some(false) => "no",
                        }
                    )),
                    SharedString::from(choice_label),
                    selected,
                    pending,
                    None,
                    cx.listener(move |this, _, _, cx| {
                        this.set_profile_model_capability(index, field, choice, cx)
                    }),
                    cx,
                ));
            }
            rows.push(
                v_flex()
                    .w_full()
                    .gap_1p5()
                    .child(management_choice_group_label(label, cx))
                    .child(choices)
                    .into_any_element(),
            );
        }
        rows
    }

    fn set_profile_model_capability(
        &mut self,
        index: usize,
        field: &'static str,
        value: Option<bool>,
        cx: &mut Context<Self>,
    ) {
        let Some(model) = self.profile_configured_models.get_mut(index) else {
            return;
        };
        match field {
            "imageInput" => model.capabilities.image_input = value,
            "pdfInput" => model.capabilities.pdf_input = value,
            "temperature" => model.capabilities.temperature = value,
            _ => return,
        }
        model
            .capabilities
            .set_source(field, vibex_core::ModelCapabilitySource::Declared);
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    /// The catalogue's suggestions, one row per field with its own adopt
    /// control.
    ///
    /// Nothing here applies by itself: a suggestion is a value the user may
    /// take, and a field they already declared is shown with a way back to
    /// their own value rather than being overwritten.
    fn render_capability_suggestions(
        &mut self,
        index: usize,
        cx: &mut Context<Self>,
    ) -> Vec<AnyElement> {
        let Some(suggestion) = self.model_capability_suggestion.clone() else {
            return Vec::new();
        };
        let approximate = suggestion.approximate;
        let mut rows = Vec::new();
        if !suggestion.fields.is_empty() {
            rows.push(
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_end()
                    .child(
                        Button::new("provider-model-adopt-all")
                            .xsmall()
                            .outline()
                            .label(management_locale_text(
                                "Apply all suggestions",
                                "采用全部建议",
                                "採用全部建議",
                            ))
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.adopt_all_capability_fields(window, cx)
                            })),
                    )
                    .into_any_element(),
            );
        }
        for field in suggestion.fields {
            let label = match field.field.as_str() {
                "contextTokens" => {
                    management_locale_text("Context window", "上下文窗口", "上下文視窗")
                }
                "outputTokens" => management_locale_text("Max output", "最大输出", "最大輸出"),
                "reasoning" => management_locale_text("Reasoning", "推理", "推理"),
                "imageInput" => management_locale_text("Images", "图片输入", "圖片輸入"),
                "pdfInput" => management_locale_text("PDF", "PDF 输入", "PDF 輸入"),
                "temperature" => management_locale_text("Temperature", "温度参数", "溫度參數"),
                _ => continue,
            };
            let field_key = field.field.clone();
            let suggested = field.value.clone();
            rows.push(
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .child(
                        div()
                            .min_w_0()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(format!(
                                "{} · {} {}{}",
                                label,
                                management_locale_text("suggested", "目录建议", "目錄建議"),
                                suggested,
                                if approximate {
                                    management_locale_text(
                                        " (approximate)",
                                        "（近似匹配）",
                                        "（近似比對）",
                                    )
                                } else {
                                    ""
                                }
                            )),
                    )
                    .child(
                        Button::new(SharedString::from(format!(
                            "provider-model-adopt-{index}-{field_key}"
                        )))
                        .xsmall()
                        .ghost()
                        .label(if approximate {
                            management_locale_text(
                                "Apply (approximate)",
                                "采用（近似匹配）",
                                "採用（近似比對）",
                            )
                        } else {
                            management_locale_text("Apply", "采用", "採用")
                        })
                        .on_click(cx.listener(
                            move |this, _, window, cx| {
                                this.adopt_capability_field(field_key.clone(), window, cx)
                            },
                        )),
                    )
                    .into_any_element(),
            );
        }
        // A source label, so an adopted value is never mistaken for a hand-typed
        // one later.
        if !rows.is_empty()
            && self
                .profile_configured_models
                .get(index)
                .is_some_and(|model| model.capabilities.adopted_from_catalog().next().is_some())
        {
            rows.push(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(management_locale_text(
                        "Some values came from the catalogue.",
                        "部分数值来自模型目录。",
                        "部分數值來自模型目錄。",
                    ))
                    .into_any_element(),
            );
        }
        rows
    }

    /// Adopts every suggested field in one gesture.
    ///
    /// The per-field controls remain for the case where only one value is
    /// trusted; this is the same adoption repeated, not a different path.
    fn adopt_all_capability_fields(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        let Some(suggestion) = self.model_capability_suggestion.clone() else {
            return;
        };
        for field in suggestion.fields {
            self.adopt_capability_field(field.field, window, cx);
        }
    }

    /// Adopts one suggested field into the Model being edited.
    ///
    /// The value is written into the same field the user would type into, and
    /// its provenance is recorded so a projection can tell it from a
    /// declaration. Clearing the field afterwards returns it to `Declared`.
    fn adopt_capability_field(
        &mut self,
        field: String,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(suggestion) = self.model_capability_suggestion.clone() else {
            return;
        };
        let Some(index) = self.selected_profile_model_index() else {
            return;
        };
        let Some(model) = self.profile_configured_models.get_mut(index) else {
            return;
        };
        // An explicit adoption is the user's decision on a field, so it may
        // replace a previously adopted value; it never silently replaces a
        // value the user typed, because the control is only offered while the
        // field is empty.
        // The declaration owns the mapping from a suggested field to itself, so
        // the editor does not grow a second copy of it.
        let mut capabilities = model.capabilities.clone();
        if !suggestion.adopt(&mut capabilities, &field) {
            return;
        }
        model.capabilities = capabilities;
        // The visible fields follow the declaration they now hold.
        match field.as_str() {
            "contextTokens" => {
                if let Some(value) = model.capabilities.context_tokens {
                    self.profile_model_edit_context_tokens
                        .update(cx, |state, cx| {
                            state.set_value(value.to_string(), window, cx)
                        });
                }
            }
            "outputTokens" => {
                if let Some(value) = model.capabilities.output_tokens {
                    self.profile_model_edit_output_tokens
                        .update(cx, |state, cx| {
                            state.set_value(value.to_string(), window, cx)
                        });
                }
            }
            _ => {}
        }
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    /// Checks or unchecks every picker row the current search shows.
    ///
    /// "All" means the rows on screen: a filtered select-all leaves hidden
    /// matches alone, and a filtered clear does not release Models the filter
    /// is hiding.
    fn set_visible_profile_candidates_selected(
        &mut self,
        selected: bool,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let filter = self
            .profile_model_search
            .read(cx)
            .value()
            .trim()
            .to_string();
        let rows = self
            .profile_candidate_rows()
            .into_iter()
            .filter(|row| profile_candidate_matches(row, &filter))
            .collect::<Vec<_>>();
        // A bulk answer can move the Model the settings pane is showing in or
        // out of the draft, and the pane's fields are that Model's settings.
        let selection_affected = self
            .profile_model_selection
            .as_deref()
            .is_some_and(|selection| rows.iter().any(|row| row.id == selection));
        let mut changed = false;
        for row in rows {
            changed |= if selected {
                self.choose_profile_model(row.id.clone(), Some(row.as_configured_model()))
            } else {
                match self
                    .profile_configured_models
                    .iter()
                    .position(|model| model.id == row.id)
                {
                    Some(index) => self.detach_profile_model_at(index),
                    None => false,
                }
            };
        }
        if changed {
            self.navigation.mark_dirty(ManagementSection::Agents, true);
            if selection_affected {
                self.sync_profile_model_editor(window, cx);
            }
            cx.notify();
        }
    }

    fn set_visible_profile_models_enabled(&mut self, enabled: bool, cx: &mut Context<Self>) {
        // The picker is the only list, so "visible" means the rows it is
        // showing that the Provider already offers.
        let filter = self
            .profile_model_search
            .read(cx)
            .value()
            .trim()
            .to_string();
        let ids = self
            .profile_candidate_rows()
            .into_iter()
            .filter(|row| row.is_configured())
            .filter(|row| profile_candidate_matches(row, &filter))
            .map(|row| row.id)
            .collect::<Vec<_>>();
        let mut changed = false;
        for model in self.profile_configured_models.iter_mut() {
            if ids.contains(&model.id) && model.enabled != enabled {
                model.enabled = enabled;
                changed = true;
            }
        }
        if changed {
            self.navigation.mark_dirty(ManagementSection::Agents, true);
            cx.notify();
        }
    }

    fn render_projection_credential_control(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let surface = self.projection_editor.credential_surface();
        // A local service authenticates nothing, so its Key field is not shown
        // at all: an empty box labelled "API Key" on Ollama reads as a
        // requirement the user has failed rather than one that does not exist.
        if surface == ProjectionCredentialSurface::ApiKey
            && self
                .provider_preset_draft
                .as_ref()
                .is_some_and(|preset| preset.no_key)
        {
            return management_field_hint(
                management_locale_text(
                    "This service runs locally and needs no API key.",
                    "本地服务，不需要 API Key。",
                    "本機服務，不需要 API Key。",
                ),
                cx,
            );
        }
        let auth_state = self
            .projection_editor
            .capability
            .as_ref()
            .map(|capability| capability.auth_state);
        if surface == ProjectionCredentialSurface::ApiKey {
            let configured = self.profile_secret_configured;
            let clearing = self.profile_secret_clear;
            // The stored-key state is a word beside the label, not a filled
            // badge: two colored tags on one field spend the dialog's whole
            // emphasis budget on the least important fact in it.
            let state = if clearing {
                Some((
                    management_locale_text("Will be cleared", "保存后清除", "儲存後清除"),
                    cx.theme().warning,
                ))
            } else if configured {
                Some((
                    management_locale_text("Saved", "已保存", "已儲存"),
                    cx.theme().success,
                ))
            } else {
                None
            };
            let mut header =
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .child(
                        h_flex()
                            .min_w_0()
                            .items_center()
                            .gap_1p5()
                            .child(
                                div()
                                    .text_xs()
                                    .font_medium()
                                    .text_color(cx.theme().muted_foreground)
                                    .child("API Key"),
                            )
                            .children(state.map(|(label, color)| {
                                div().text_xs().text_color(color).child(label)
                            })),
                    );
            if let Some(state) =
                auth_state.filter(|state| projection_auth_state_needs_attention(*state))
            {
                header = header.child(projection_auth_state_badge(state, cx));
            }
            // Clearing is a command about the stored key, so it lives with the
            // field's own label instead of at the far end of its help text.
            if configured {
                header = header.child(
                    Button::new("provider-secret-clear")
                        .xsmall()
                        .ghost()
                        .compact()
                        .label(if clearing {
                            management_locale_text("Keep stored key", "保留密钥", "保留密鑰")
                        } else {
                            management_locale_text("Clear", "清除", "清除")
                        })
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.profile_secret_clear = !this.profile_secret_clear;
                            // Clearing is an intent of its own; dropping it again
                            // leaves the stored Secret exactly as it was. The
                            // field follows the intent so it never shows a key
                            // the save is about to delete.
                            let clear = this.profile_secret_clear;
                            let restored = (!clear)
                                .then(|| this.profile_secret_loaded.clone())
                                .flatten()
                                .unwrap_or_default();
                            this.profile_api_key.update(cx, |state, cx| {
                                state.set_masked(true, window, cx);
                                state.set_value(restored, window, cx);
                            });
                            this.projection_editor.set_secret_intent(clear, clear);
                            this.navigation.mark_dirty(ManagementSection::Agents, true);
                            cx.notify();
                        })),
                );
            }
            // A stored key the read brought back is shown masked, and the eye
            // reveals it; a key the read could not bring back keeps the older
            // answer, where blank is "keep it". Typing replaces either way, and
            // clearing is a command.
            let hint = if clearing {
                management_locale_text(
                    "Saving clears the stored key.",
                    "保存后会清除已保存的密钥。",
                    "儲存後會清除已儲存的密鑰。",
                )
            } else if configured && self.profile_secret_loaded.is_some() {
                management_locale_text(
                    "A key is stored, hidden behind asterisks. Use the eye to reveal it, or type a new value to replace it.",
                    "已保存密钥，默认用星号隐藏显示，点击右侧眼睛可显示明文；输入新值即可替换。",
                    "已儲存密鑰，預設以星號隱藏顯示，點擊右側眼睛可顯示明文；輸入新值即可取代。",
                )
            } else if configured {
                management_locale_text(
                    "A key is stored. Leave this empty to keep it, or type a new value to replace it.",
                    "已保存密钥。留空保持不变，输入新值即可替换。",
                    "已儲存密鑰。留空保持不變，輸入新值即可取代。",
                )
            } else {
                management_locale_text(
                    "No key is stored yet.",
                    "还没有保存密钥。",
                    "還沒有儲存密鑰。",
                )
            };
            return v_flex()
                .w_full()
                .gap_1p5()
                .child(header)
                .child(
                    Input::new(&self.profile_api_key)
                        .small()
                        .w_full()
                        .mask_toggle(),
                )
                .child(management_field_hint(hint, cx))
                .into_any_element();
        }

        let (title, detail, icon) = match surface {
            ProjectionCredentialSurface::OAuth => (
                "OAuth",
                management_locale_text(
                    "Agent or host authentication status",
                    "Agent 或主机认证状态",
                    "Agent 或主機驗證狀態",
                ),
                IconName::User,
            ),
            ProjectionCredentialSurface::Cloud => (
                management_locale_text("Cloud credential", "云凭证", "雲端憑證"),
                management_locale_text(
                    "Cloud profile and credential references",
                    "云端配置与凭证引用",
                    "雲端設定與憑證引用",
                ),
                IconName::Globe,
            ),
            ProjectionCredentialSurface::AgentManaged => (
                management_locale_text("Agent account", "Agent 账户", "Agent 帳戶"),
                management_locale_text(
                    "Authentication is managed by the Agent",
                    "认证由 Agent 管理",
                    "驗證由 Agent 管理",
                ),
                IconName::Bot,
            ),
            ProjectionCredentialSurface::Local => (
                management_locale_text("Local runtime", "本地运行时", "本機執行階段"),
                management_locale_text(
                    "No remote credential is projected",
                    "不会投影远程凭证",
                    "不會投影遠端憑證",
                ),
                IconName::HardDrive,
            ),
            ProjectionCredentialSurface::ServiceMarketplace => (
                management_locale_text("Service marketplace", "服务市场", "服務市集"),
                management_locale_text(
                    "Authentication is owned by the service",
                    "认证由服务管理",
                    "驗證由服務管理",
                ),
                IconName::Network,
            ),
            ProjectionCredentialSurface::Unsupported => (
                management_locale_text("Automatic credential", "自动凭证", "自動憑證"),
                management_locale_text(
                    "Unsupported or unverified for this compatible runtime",
                    "当前兼容运行时不支持或尚未验证",
                    "目前相容執行階段不支援或尚未驗證",
                ),
                IconName::Info,
            ),
            ProjectionCredentialSurface::ApiKey => unreachable!(),
        };
        v_flex()
            .w_full()
            .gap_1p5()
            .child(
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .child(
                        h_flex()
                            .min_w_0()
                            .items_center()
                            .gap_1p5()
                            .child(
                                div()
                                    .flex_none()
                                    .size(px(22.0))
                                    .flex()
                                    .items_center()
                                    .justify_center()
                                    .rounded_full()
                                    .bg(cx.theme().muted.opacity(0.35))
                                    .child(
                                        Icon::new(icon)
                                            .size_3()
                                            .text_color(cx.theme().muted_foreground),
                                    ),
                            )
                            .child(div().text_sm().font_medium().child(title)),
                    )
                    .children(auth_state.map(|state| projection_auth_state_badge(state, cx))),
            )
            .child(
                div()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(detail),
            )
            .into_any_element()
    }

    fn render_profile_editor_dialog(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        if !self.profile_editor_open {
            return div().size_full().into_any_element();
        }
        let selected_agent_id = self.selected_agent_id.clone().unwrap_or_default();
        let pending =
            self.mutation.is_some() || self.agent_mutations.contains_key(&selected_agent_id);
        let updating = self.editing_profile_id.is_some();
        // Creating a Provider starts from "which existing one, or a new one?".
        // The step owns the body because there is nothing to save yet; the only
        // action that ends it is Cancel.
        if !updating && self.provider_preset_picker {
            return v_flex()
                .size_full()
                .min_h_0()
                .child(self.render_provider_picker_step(window, cx))
                .child(
                    h_flex()
                        .w_full()
                        .flex_none()
                        .items_center()
                        .justify_end()
                        .gap_2()
                        .border_t_1()
                        .border_color(cx.theme().border)
                        .pt_3()
                        .child(
                            Button::new("provider-picker-close")
                                .small()
                                .ghost()
                                .label(management_locale_text("Cancel", "取消", "取消"))
                                .on_click(cx.listener(|this, _, window, cx| {
                                    this.close_profile_editor(window, cx)
                                })),
                        ),
                )
                .into_any_element();
        }
        // A shared Provider is not one Agent's configuration, and the dialog has
        // to say so: the same form otherwise reads as "for the Agent I had
        // selected", which is the shape this path exists to stop producing.
        let shared_scope_note = self.provider_editor_shared.then(|| {
            div()
                .w_full()
                .min_w_0()
                .rounded(px(6.0))
                .border_1()
                .border_color(cx.theme().info)
                .px_2()
                .py_1p5()
                .text_xs()
                .text_color(cx.theme().info)
                .child(management_locale_text(
                    "This Provider is shared: any Agent can use it, and each one keeps its own protocol. Nothing is tied to a single Agent.",
                    "该供应商是共享的：任何 Agent 都能使用，各自保留自己的协议。它不绑定到某一个 Agent。",
                    "該供應商是共用的：任何 Agent 都能使用，各自保留自己的協定。它不綁定到某一個 Agent。",
                ))
                .into_any_element()
        });
        let saving = matches!(
            self.mutation,
            Some(ManagementMutation::ProfileCreate) | Some(ManagementMutation::ProfileUpdate(_))
        );
        let testing = self.editing_profile_id.as_deref().is_some_and(|profile_id| {
            matches!(&self.mutation, Some(ManagementMutation::ProviderProbe(action)) if action == profile_id)
        });
        let draft_testing = self.editing_profile_id.is_none()
            && matches!(
                &self.mutation,
                Some(ManagementMutation::ProviderProbe(action))
                    if action.starts_with("draft-test:")
            );
        let detecting_apis = self.editing_profile_id.is_none()
            && matches!(
                &self.mutation,
                Some(ManagementMutation::ProviderProbe(action))
                    if action.starts_with("detect:")
            );
        // A probe is not a reason to trap the user in the dialog: it can take a
        // while, and closing only discards the draft.
        let cancel_disabled =
            pending && !matches!(self.mutation, Some(ManagementMutation::ProviderProbe(_)));
        let shows_model = self
            .projection_editor
            .shows(vibex_core::AgentProjectionFormControl::Model);
        // Two panes need room for two readable columns; below that the picker
        // and its settings stack instead of being squeezed side by side.
        let wide = f32::from(window.viewport_size().width) >= MANAGEMENT_PROFILE_PANES_MIN_WIDTH;
        // The identity and the connection are what make a catalogue reachable,
        // so they stay one compact band above the picker rather than competing
        // with it for the dialog's height.
        let form_band = if wide {
            h_flex()
                .w_full()
                .min_w_0()
                .items_start()
                .gap_4()
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .child(self.render_profile_identity_section(cx)),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .child(self.render_profile_connection_section(cx)),
                )
                .into_any_element()
        } else {
            v_flex()
                .w_full()
                .gap_3()
                .child(self.render_profile_identity_section(cx))
                .child(self.render_profile_connection_section(cx))
                .into_any_element()
        };

        let mut body = v_flex().w_full().min_h_0().flex_1();
        if let Some(note) = shared_scope_note {
            body = body.child(div().w_full().flex_none().pb_2().child(note));
        }
        if wide {
            // The band is bounded so an expanded protocol override cannot eat
            // the height the two panes need, and it scrolls on its own if it
            // does. The overflow is the plain one: the scrollbar wrapper sizes
            // itself to the parent, which would pin the band to its maximum and
            // leave the panes short of room they should have.
            body = body.child(
                div()
                    .id("provider-form-band")
                    .debug_selector(|| "provider-form-band".to_string())
                    .w_full()
                    .flex_none()
                    .min_h_0()
                    .max_h(px(MANAGEMENT_PROFILE_FORM_BAND_MAX_HEIGHT))
                    .overflow_y_scroll()
                    .pr_1()
                    .child(form_band),
            );
            if shows_model {
                // Choosing a Model and configuring it are one task, so the
                // catalogue and the chosen settings share the remaining height
                // and scroll independently. The padding keeps the two panels
                // off the form above them and off the dialog's own action bar,
                // so three rules never stack into one line.
                body = body.child(
                    h_flex()
                        .w_full()
                        .flex_1()
                        .min_h_0()
                        .items_stretch()
                        .gap_3()
                        .pt_4()
                        .pb_4()
                        .child(self.render_profile_candidates_pane(true, cx))
                        .child(self.render_profile_settings_pane(true, cx)),
                );
            }
        } else {
            let mut stacked = v_flex().w_full().gap_3().pt_4().pb_4().child(form_band);
            if shows_model {
                stacked = stacked
                    .child(self.render_profile_candidates_pane(false, cx))
                    .child(self.render_profile_settings_pane(false, cx));
            }
            body = body.child(
                div()
                    .min_h_0()
                    .flex_1()
                    .overflow_y_scrollbar()
                    .scroll_gutter()
                    .child(stacked),
            );
        }

        v_flex()
            .size_full()
            .min_h_0()
            .child(body)
            .child(
                h_flex()
                    .w_full()
                    .flex_none()
                    .items_center()
                    .justify_end()
                    .gap_2()
                    .border_t_1()
                    .border_color(cx.theme().border)
                    .pt_3()
                    // Every command that ends the dialog's work sits together on
                    // the trailing edge: probe, abandon, commit.
                    .when_some(self.editing_profile_id.clone(), |row, profile_id| {
                        let agent_id = selected_agent_id.clone();
                        row.child(
                            Button::new("provider-profile-test")
                                .small()
                                .outline()
                                .icon(IconName::Network)
                                .label(if testing {
                                    management_locale_text("Testing...", "测试中...", "測試中...")
                                } else {
                                    management_locale_text(
                                        "Test connection",
                                        "测试连接",
                                        "測試連線",
                                    )
                                })
                                .loading(testing)
                                .disabled(pending)
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.test_provider_profile(
                                        profile_id.clone(),
                                        agent_id.clone(),
                                        cx,
                                    )
                                })),
                        )
                    })
                    .when(self.editing_profile_id.is_none(), |row| {
                        row.child(
                            Button::new("provider-profile-test-draft")
                                .small()
                                .outline()
                                .icon(IconName::Network)
                                .label(if draft_testing {
                                    management_locale_text("Testing...", "测试中...", "測試中...")
                                } else {
                                    management_locale_text(
                                        "Test connection",
                                        "测试连接",
                                        "測試連線",
                                    )
                                })
                                .loading(draft_testing)
                                .disabled(pending)
                                .on_click(cx.listener(|this, _, _, cx| {
                                    let agent_id =
                                        this.selected_agent_id.clone().unwrap_or_default();
                                    this.test_provider_draft(agent_id, cx)
                                })),
                        )
                        .child(
                            Button::new("provider-profile-detect-apis")
                                .small()
                                .ghost()
                                .label(if detecting_apis {
                                    management_locale_text("Detecting...", "检测中...", "偵測中...")
                                } else {
                                    management_locale_text("Detect APIs", "检测 API", "偵測 API")
                                })
                                .loading(detecting_apis)
                                .disabled(pending)
                                .on_click(cx.listener(|this, _, _, cx| {
                                    let agent_id =
                                        this.selected_agent_id.clone().unwrap_or_default();
                                    this.detect_provider_apis(agent_id, cx)
                                })),
                        )
                    })
                    .child(
                        Button::new("provider-profile-close")
                            .small()
                            .ghost()
                            .label(management_locale_text("Cancel", "取消", "取消"))
                            .disabled(cancel_disabled)
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.close_profile_editor(window, cx)
                            })),
                    )
                    .child(
                        Button::new("provider-profile-save")
                            .small()
                            .primary()
                            .label(if updating {
                                management_locale_text("Save changes", "保存修改", "儲存修改")
                            } else {
                                management_locale_text("Add and verify", "添加并验证", "新增並驗證")
                            })
                            .loading(saving)
                            .disabled(pending)
                            .on_click(cx.listener(|this, _, _, cx| this.save_profile(cx))),
                    ),
            )
            .into_any_element()
    }

    /// Identity: name, note, and website. Name gets the primary emphasis.
    /// The first step of adding a Provider to an Agent.
    ///
    /// Two things belong on this step and neither can be inferred from the
    /// other. A Provider the user already configured globally is the common
    /// case — they want this Agent to use it, not a second copy of it — so the
    /// list of existing records comes first and is searchable. Creating one is
    /// the fallback, and it keeps the preset library behind it.
    fn render_provider_picker_step(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let pending = self.mutation.is_some();
        let query = self.provider_preset_query.read(cx).value().to_string();
        let normalized = query.trim().to_lowercase();
        // A shared Provider appears once here however many Agents bind it. It
        // is hidden only when *this* Agent already launches through it, because
        // choosing it again would be a no-op dressed up as an action.
        let already_bound = self
            .selected_agent_id
            .as_deref()
            .and_then(|agent_id| vibex_core::AgentId::parse(agent_id.to_string()).ok())
            .map(|agent_id| agent_bound_profile_ids(&agent_id, &self.provider_bindings))
            .unwrap_or_default();
        let mut existing = self
            .providers
            .iter()
            .filter(|profile| profile.status == vibex_core::ModelProviderProfileStatus::Enabled)
            .filter(|profile| !profile.metadata.only_through_route_groups)
            .filter(|profile| {
                profile
                    .legacy_provider_profile_id
                    .as_ref()
                    .is_none_or(|legacy| !already_bound.contains(legacy.as_str()))
            })
            .filter(|profile| {
                if normalized.is_empty() {
                    return true;
                }
                profile.display_name.to_lowercase().contains(&normalized)
                    || profile
                        .vendor_hint
                        .as_deref()
                        .is_some_and(|vendor| vendor.to_lowercase().contains(&normalized))
                    || profile
                        .endpoints
                        .iter()
                        .any(|endpoint| endpoint.url.to_lowercase().contains(&normalized))
            })
            .cloned()
            .collect::<Vec<_>>();
        existing.sort_by(|left, right| {
            left.display_name
                .to_lowercase()
                .cmp(&right.display_name.to_lowercase())
        });

        let mut rows = v_flex().w_full().gap_1();
        for profile in &existing {
            let profile_id = profile.id.clone();
            let model_count = profile
                .configured_models
                .iter()
                .filter(|m| m.enabled)
                .count();
            let detail = format!(
                "{} · {}",
                profile
                    .vendor_hint
                    .clone()
                    .or_else(|| {
                        profile
                            .endpoints
                            .iter()
                            .map(|endpoint| endpoint.url.clone())
                            .next()
                    })
                    .unwrap_or_else(|| management_locale_text("Local", "本地", "本機").to_string()),
                management_model_count(model_count)
            );
            rows = rows.child(
                h_flex()
                    .id(SharedString::from(format!(
                        "management-provider-existing-{}",
                        profile.id.as_str()
                    )))
                    .w_full()
                    .items_center()
                    .gap_3()
                    .px_3()
                    .py_2()
                    .rounded(px(6.0))
                    .when(!pending, |this| {
                        this.cursor_pointer()
                            .hover(|style| style.bg(cx.theme().muted.opacity(0.4)))
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.use_existing_provider(profile_id.clone(), cx)
                            }))
                    })
                    .child(management_profile_glyph(
                        vibex_core::ProviderKind::Acp,
                        &profile.display_name,
                        false,
                        cx,
                    ))
                    .child(
                        v_flex()
                            .min_w_0()
                            .flex_1()
                            .gap_0p5()
                            .child(
                                div()
                                    .min_w_0()
                                    .truncate()
                                    .text_sm()
                                    .font_medium()
                                    .child(profile.display_name.clone()),
                            )
                            .child(
                                div()
                                    .min_w_0()
                                    .truncate()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(detail),
                            ),
                    )
                    .child(
                        Tag::color(ColorName::Neutral)
                            .xsmall()
                            .child(management_locale_text("Use", "使用", "使用")),
                    ),
            );
        }
        if existing.is_empty() {
            rows = rows.child(
                div()
                    .w_full()
                    .px_3()
                    .py_2()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(if normalized.is_empty() {
                        management_locale_text(
                            "No Provider is configured yet. Create one below.",
                            "还没有配置任何供应商，可在下方创建。",
                            "還沒有設定任何供應商，可在下方建立。",
                        )
                    } else {
                        management_locale_text(
                            "No configured Provider matches this search.",
                            "没有已配置的供应商匹配这个搜索。",
                            "沒有已設定的供應商符合這個搜尋。",
                        )
                    }),
            );
        }

        // Route groups are the other half of "what model source will this Agent
        // use", so they belong on the same chooser as Providers rather than
        // behind a separate button: a reference to a global group and a new one
        // are both answers to the same question.
        let already_referenced = self
            .agent_model_route_bindings
            .iter()
            .filter(|binding| {
                binding.deleted_at_ms.is_none()
                    && Some(binding.agent_id.as_str()) == self.selected_agent_id.as_deref()
            })
            .map(|binding| binding.model_route_id.clone())
            .collect::<Vec<_>>();
        let mut available_groups =
            shared_route_group_rows(&self.model_routes, &self.agent_model_route_bindings)
                .into_iter()
                .filter(|row| !already_referenced.contains(&row.route.id))
                .filter(|row| row.route.status == vibex_core::RouteStatus::Enabled)
                .filter(|row| {
                    normalized.is_empty()
                        || row.route.display_name.to_lowercase().contains(&normalized)
                        || row
                            .route
                            .agent_model()
                            .is_some_and(|model| model.to_lowercase().contains(&normalized))
                        || row
                            .route
                            .enabled_members()
                            .filter_map(|member| {
                                self.providers
                                    .iter()
                                    .find(|profile| profile.id == member.model_provider_profile_id)
                                    .map(|profile| profile.display_name.to_lowercase())
                            })
                            .any(|name| name.contains(&normalized))
                })
                .collect::<Vec<_>>();
        available_groups.sort_by(|left, right| {
            left.route
                .display_name
                .to_lowercase()
                .cmp(&right.route.display_name.to_lowercase())
        });
        let mut group_rows = v_flex().w_full().gap_1();
        if !available_groups.is_empty() {
            group_rows = group_rows.child(
                div()
                    .px_2()
                    .pt_2()
                    .text_xs()
                    .font_medium()
                    .text_color(cx.theme().muted_foreground)
                    .child(management_locale_text(
                        "Use a route group",
                        "使用路由组",
                        "使用路由組",
                    )),
            );
            for row in available_groups {
                let route_id = row.route.id.clone();
                let summary = management_route_group_member_summary(&row.route, &self.providers);
                group_rows = group_rows.child(
                    h_flex()
                        .id(SharedString::from(format!(
                            "management-provider-existing-group-{}",
                            route_id.as_str()
                        )))
                        .w_full()
                        .items_center()
                        .gap_3()
                        .px_3()
                        .py_2()
                        .rounded(px(6.0))
                        .when(!pending, |this| {
                            this.cursor_pointer()
                                .hover(|style| style.bg(cx.theme().muted.opacity(0.4)))
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    this.use_existing_route_group(route_id.clone(), cx)
                                }))
                        })
                        .child(
                            Icon::default()
                                .path("icons/vibex/git-branch.svg")
                                .size(px(16.0)),
                        )
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap_0p5()
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_sm()
                                        .font_medium()
                                        .child(row.route.display_name.clone()),
                                )
                                .child(
                                    div()
                                        .min_w_0()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(summary),
                                ),
                        )
                        .child(
                            Tag::color(ColorName::Neutral)
                                .xsmall()
                                .child(management_locale_text("Use", "使用", "使用")),
                        ),
                );
            }
        }
        // Creating one is next to referencing one, because composing a group is
        // the other answer to the same question. The new group is global like
        // every other, and this Agent gets a reference to it.
        group_rows = group_rows.child(
            h_flex()
                .id("management-provider-new-group")
                .w_full()
                .items_center()
                .gap_3()
                .px_3()
                .py_2()
                .rounded(px(6.0))
                .when(!pending, |this| {
                    this.cursor_pointer()
                        .hover(|style| style.bg(cx.theme().muted.opacity(0.4)))
                        .on_click(cx.listener(|this, _, window, cx| {
                            this.create_route_group_from_agent(window, cx)
                        }))
                })
                .child(
                    Icon::new(IconName::Plus)
                        .size(px(14.0))
                        .text_color(cx.theme().muted_foreground),
                )
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_0p5()
                        .child(div().text_sm().font_medium().child(management_locale_text(
                            "New route group",
                            "新建路由组",
                            "新增路由組",
                        )))
                        .child(
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(management_locale_text(
                                    "Combine Providers into one model source",
                                    "把多个供应商组合成一个模型来源",
                                    "把多個供應商組合成一個模型來源",
                                )),
                        ),
                )
                .child(
                    Tag::color(ColorName::Neutral)
                        .xsmall()
                        .child(management_locale_text("New", "新建", "新增")),
                ),
        );

        let mut category_chips = h_flex().w_full().flex_wrap().gap_1();
        for category in ProviderPresetCategory::ALL {
            let selected = self.provider_source_categories.contains(&category);
            category_chips = category_chips.child(
                Button::new(SharedString::from(format!(
                    "management-provider-source-category-{:?}",
                    category
                )))
                .xsmall()
                .when(selected, |button| button.primary())
                .when(!selected, |button| button.ghost())
                .label(category.label())
                .on_click(cx.listener(move |this, _, _, cx| {
                    if this.provider_source_categories.contains(&category) {
                        if this.provider_source_categories.len() > 1 {
                            this.provider_source_categories.remove(&category);
                        }
                    } else {
                        this.provider_source_categories.insert(category);
                    }
                    cx.notify();
                })),
            );
        }
        let mut scope_row = h_flex().w_full().items_center().flex_wrap().gap_2();
        if self.selected_agent_id.is_some() {
            scope_row = scope_row
                .child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(management_locale_text("Scope", "范围", "範圍")),
                )
                .child(
                    Button::new("management-provider-source-scope-agent")
                        .xsmall()
                        .when(!self.provider_editor_shared, |button| button.primary())
                        .when(self.provider_editor_shared, |button| button.ghost())
                        .label(management_locale_text(
                            "Only this Agent",
                            "仅此 Agent",
                            "僅此 Agent",
                        ))
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.provider_editor_shared = false;
                            cx.notify();
                        })),
                )
                .child(
                    Button::new("management-provider-source-scope-shared")
                        .xsmall()
                        .when(self.provider_editor_shared, |button| button.primary())
                        .when(!self.provider_editor_shared, |button| button.ghost())
                        .label(management_locale_text(
                            "Share with Agents",
                            "共享给多个 Agent",
                            "共用給多個 Agent",
                        ))
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.provider_editor_shared = true;
                            cx.notify();
                        })),
                );
        }
        let recent_presets = self
            .provider_recent_presets
            .iter()
            .filter_map(|id| vibex_core::provider_preset(id))
            .collect::<Vec<_>>();
        let mut recent_row = h_flex().w_full().flex_wrap().gap_1();
        if !recent_presets.is_empty() {
            recent_row = recent_row.child(
                div()
                    .w_full()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(management_locale_text("Recent", "最近使用", "最近使用")),
            );
            for preset in recent_presets {
                let preset_id = preset.id.clone();
                recent_row = recent_row.child(
                    Button::new(SharedString::from(format!(
                        "management-provider-recent-{}",
                        preset.id
                    )))
                    .xsmall()
                    .ghost()
                    .icon(Icon::default().path(
                        provider_preset_icon_path(&preset).unwrap_or("icons/vibex/database.svg"),
                    ))
                    .label(preset.display_name)
                    .on_click(cx.listener(move |this, _, window, cx| {
                        this.choose_provider_preset(&preset_id, window, cx)
                    })),
                );
            }
        }
        let preset_tiles = provider_preset_tiles(
            vibex_core::provider_presets(),
            &query,
            &self.provider_source_categories,
        );
        let mut tile_grid = h_flex().w_full().flex_wrap().gap_2();
        for preset in &preset_tiles {
            let preset_id = preset.id.clone();
            let badge = if preset.plan_note.is_some() {
                Some(management_locale_text("Plan", "套餐", "套餐"))
            } else if !preset.regions.is_empty() {
                Some(management_locale_text("Region", "地区", "地區"))
            } else if preset.no_key {
                Some(management_locale_text("Local", "本机", "本機"))
            } else if preset.catalog_id.is_some() {
                Some(management_locale_text("Official", "官方", "官方"))
            } else {
                None
            };
            let detail = if preset.no_key {
                management_locale_text("No key needed", "无需 Key", "無需 Key").to_string()
            } else {
                preset
                    .catalog_id
                    .clone()
                    .or_else(|| {
                        preset
                            .endpoints
                            .values()
                            .next()
                            .map(|url| provider_preset_host(url))
                    })
                    .unwrap_or_else(|| management_locale_text("Preset", "预设", "預設").to_string())
            };
            tile_grid =
                tile_grid.child(
                    v_flex()
                        .id(SharedString::from(format!(
                            "management-provider-preset-{}",
                            preset.id
                        )))
                        .w(px(172.0))
                        .min_h(px(88.0))
                        .gap_1p5()
                        .rounded(px(8.0))
                        .border_1()
                        .border_color(cx.theme().border)
                        .p_2()
                        .when(!pending, |this| {
                            this.cursor_pointer()
                                .hover(|style| style.bg(cx.theme().muted.opacity(0.35)))
                                .on_click(cx.listener(move |this, _, window, cx| {
                                    this.choose_provider_preset(&preset_id, window, cx)
                                }))
                        })
                        .child(
                            h_flex()
                                .w_full()
                                .items_center()
                                .gap_2()
                                .child(provider_preset_logo(preset, cx))
                                .child(
                                    div()
                                        .min_w_0()
                                        .flex_1()
                                        .truncate()
                                        .text_sm()
                                        .font_medium()
                                        .child(preset.display_name.clone()),
                                ),
                        )
                        .child(
                            h_flex()
                                .w_full()
                                .items_center()
                                .gap_1()
                                .child(
                                    div()
                                        .min_w_0()
                                        .flex_1()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(detail),
                                )
                                .children(badge.map(|badge| {
                                    Tag::color(ColorName::Neutral).xsmall().child(badge)
                                })),
                        ),
                );
        }
        let _ = window;

        v_flex()
            .w_full()
            .min_h_0()
            .flex_1()
            .gap_2()
            .child(management_field_label(management_locale_text(
                "Use a Provider",
                "使用供应商",
                "使用供應商",
            )))
            .child(recent_row)
            .child(scope_row)
            .child(category_chips)
            .child(management_search_input(&self.provider_preset_query, cx))
            .child(
                div()
                    .id("provider-picker-list")
                    .w_full()
                    .min_h_0()
                    .flex_1()
                    .overflow_y_scrollbar()
                    .scroll_gutter()
                    .pb_2()
                    .child(
                        v_flex()
                            .w_full()
                            .gap_1()
                            .child(
                                div()
                                    .px_2()
                                    .text_xs()
                                    .font_medium()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(management_locale_text(
                                        "Already configured",
                                        "已配置的供应商",
                                        "已設定的供應商",
                                    )),
                            )
                            .child(rows)
                            .child(group_rows)
                            .child(
                                div()
                                    .px_2()
                                    .pt_2()
                                    .text_xs()
                                    .font_medium()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(management_locale_text(
                                        "Sources",
                                        "供应商来源",
                                        "供應商來源",
                                    )),
                            )
                            .child(tile_grid)
                            .when(preset_tiles.is_empty(), |list| {
                                list.child(compact_empty_state(
                                    management_locale_text(
                                        "No matching sources",
                                        "没有匹配的来源",
                                        "沒有符合的來源",
                                    ),
                                    management_locale_text(
                                        "Try another name, host, or category.",
                                        "换一个名称、地址或类别试试。",
                                        "換一個名稱、位址或類別試試。",
                                    ),
                                    cx,
                                ))
                            }),
                    ),
            )
            .children(self.selected_agent_id.clone().and_then(|agent_id| {
                vibex_core::AgentId::parse(agent_id.clone())
                    .ok()
                    .filter(vibex_core::supports_native_provider_import)
                    .map(|_| {
                        Button::new("management-provider-source-import")
                            .xsmall()
                            .ghost()
                            .icon(Icon::default().path("icons/vibex/import.svg"))
                            .label(management_locale_text(
                                "Import configuration",
                                "导入配置",
                                "匯入設定",
                            ))
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.preview_native_import(false, Some(agent_id.clone()), cx);
                                let _ = window;
                            }))
                    })
            }))
            .children(self.native_import_preview.as_ref().map(|preview| {
                let importable = preview
                    .items
                    .iter()
                    .filter(|item| native_import_status_is_eligible(item.status))
                    .count();
                let agent_id = self.selected_agent_id.clone().unwrap_or_default();
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .rounded(px(6.0))
                    .border_1()
                    .border_color(cx.theme().border)
                    .px_2()
                    .py_1p5()
                    .child(div().min_w_0().text_xs().child(format!(
                        "{} · {} {}",
                        management_locale_text("Import preview", "导入预览", "匯入預覽",),
                        importable,
                        management_locale_text("importable", "可导入", "可匯入")
                    )))
                    .child(
                        Button::new("management-provider-import-apply")
                            .xsmall()
                            .primary()
                            .label(management_locale_text("Import all", "全部导入", "全部匯入"))
                            .disabled(pending || importable == 0)
                            .on_click(cx.listener(move |this, _, window, cx| {
                                this.close_profile_editor(window, cx);
                                this.preview_native_import(true, Some(agent_id.clone()), cx);
                            })),
                    )
                    .into_any_element()
            }))
            .child(
                // The manual path never disappears: a preset library that
                // covered every Provider would still be a wall, not a shortcut.
                h_flex()
                    .id("management-provider-preset-custom")
                    .w_full()
                    .items_center()
                    .gap_3()
                    .border_t_1()
                    .border_color(cx.theme().border)
                    .pt_2()
                    .when(!pending, |this| {
                        this.cursor_pointer()
                            .hover(|style| style.bg(cx.theme().muted.opacity(0.4)))
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.choose_custom_provider(window, cx)
                            }))
                    })
                    .child(
                        Icon::new(IconName::Plus)
                            .size(px(14.0))
                            .text_color(cx.theme().muted_foreground),
                    )
                    .child(
                        v_flex()
                            .min_w_0()
                            .gap_0p5()
                            .child(div().text_sm().font_medium().child(management_locale_text(
                                "Custom provider",
                                "自定义供应商",
                                "自訂供應商",
                            )))
                            .child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(management_locale_text(
                                        "Start from an empty form",
                                        "从零开始配置",
                                        "從零開始設定",
                                    )),
                            ),
                    ),
            )
            .into_any_element()
    }

    /// Gives this Agent an existing shared Provider.
    ///
    /// The write is a bind, not a copy: the Provider stays one record, and this
    /// Agent becomes another of its users. That is what the global page means
    /// by "use for this Agent", reached from the Agent instead.
    fn use_existing_provider(
        &mut self,
        provider_id: vibex_core::ModelProviderProfileId,
        cx: &mut Context<Self>,
    ) {
        let Some(agent_id) = self.selected_agent_id.clone() else {
            return;
        };
        let Ok(agent_id) = vibex_core::AgentId::parse(agent_id) else {
            return;
        };
        let profile_id = self
            .providers
            .iter()
            .find(|profile| profile.id == provider_id)
            .and_then(|profile| profile.legacy_provider_profile_id.clone())
            .unwrap_or_else(vibex_core::ProviderProfileId::new);
        self.provider_preset_picker = false;
        self.profile_editor_open = false;
        self.bind_provider_to_agent(agent_id, profile_id, Some(provider_id), cx);
    }

    /// Gives this Agent a reference to an existing global route group.
    ///
    /// Like a shared Provider, the group stays one record: this only adds a
    /// binding. The picker closes because the chooser's question has been
    /// answered, and the refresh redraws the card with the new reference.
    fn use_existing_route_group(
        &mut self,
        route_id: vibex_core::ModelRouteId,
        cx: &mut Context<Self>,
    ) {
        let Some(agent_id) = self
            .selected_agent_id
            .clone()
            .and_then(|agent_id| vibex_core::AgentId::parse(agent_id).ok())
        else {
            return;
        };
        self.provider_preset_picker = false;
        self.profile_editor_open = false;
        self.bind_route_group(agent_id, route_id, cx);
    }

    /// Opens the route-group editor from an Agent's chooser.
    ///
    /// The Agent is remembered on the draft, so the save binds it as well as
    /// storing the global record. The Provider dialog is closed and the group
    /// dialog is opened on the next frame: closing the active dialog and
    /// opening another in the same update leaves the window without an overlay
    /// to show, because the close is what tears the first one down.
    fn create_route_group_from_agent(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.provider_preset_picker = false;
        self.close_profile_editor(window, cx);
        // `defer_in` hands the callback `&mut Self`; it has already leased the
        // entity for the call. A second `update` on the same entity nests a
        // lease and panics with "cannot update ManagementCenter while it is
        // already being updated", which is what this path used to do.
        cx.defer_in(window, move |center, window, cx| {
            center.open_route_group_editor(true, window, cx);
        });
        cx.notify();
    }

    /// Enters the form with one preset applied.
    fn choose_provider_preset(
        &mut self,
        preset_id: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.remember_provider_preset(preset_id);
        self.apply_provider_preset(preset_id, window, cx);
        self.provider_preset_picker = false;
        cx.notify();
    }

    /// Enters the form with nothing applied.
    ///
    /// A preset the user looked at and left behind is discarded here, so
    /// "start from an empty form" cannot inherit the addresses of the choice
    /// that was just abandoned.
    fn choose_custom_provider(&mut self, window: &mut Window, cx: &mut Context<Self>) {
        self.open_profile_creator(window, cx);
        self.provider_preset_picker = false;
        cx.notify();
    }

    /// Fills the draft from a built-in preset.
    ///
    /// The protocol is written explicitly into `provider_options["wireApi"]`
    /// rather than left to be inferred. The editor otherwise falls back to
    /// "the first protocol that has a URL", which silently re-labels an
    /// Anthropic preset as Chat Completions the next time the dialog opens.
    fn apply_provider_preset(
        &mut self,
        preset_id: &str,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(preset) = vibex_core::provider_preset(preset_id) else {
            return;
        };
        self.provider_preset_draft = Some(preset.clone());
        // A fresh preset starts at its own default addresses, not at whichever
        // region the previous draft had selected.
        self.provider_preset_region = None;
        self.profile_name.update(cx, |state, cx| {
            state.set_value(preset.display_name.clone(), window, cx)
        });
        if let Some(website) = preset.website.as_deref() {
            self.profile_website_url.update(cx, |state, cx| {
                state.set_value(website.to_string(), window, cx)
            });
        }
        self.apply_preset_endpoints(&preset, window, cx);
        // The preset's models are added as declared entries, which is what a
        // manual add produces too: their capabilities stay empty rather than
        // being guessed from the id.
        self.profile_configured_models = preset
            .models
            .iter()
            .map(|model| vibex_core::ProviderConfiguredModel {
                id: model.clone(),
                display_name: None,
                enabled: true,
                wire_api: preset.default_wire_api(),
                capabilities: Default::default(),
            })
            .collect();
        self.profile_available_models = self.profile_configured_models.clone();
        self.profile_model_selection = self
            .profile_configured_models
            .first()
            .map(|model| model.id.clone());
        if let Some(hint) = preset.key_hint.as_deref() {
            // The hint is a placeholder, not a value: it tells the user what
            // the vendor's keys look like without typing anything.
            self.profile_api_key.update(cx, |state, cx| {
                state.set_placeholder(SharedString::from(hint.to_string()), window, cx)
            });
        }
        self.notice = Some(format!(
            "{}: {}",
            preset.display_name,
            preset
                .endpoint_hint
                .clone()
                .unwrap_or_else(|| management_locale_text(
                    "preset applied",
                    "已应用预设",
                    "已套用預設",
                )
                .to_string())
        ));
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    /// Writes a preset's addresses into the draft, protocol by protocol.
    ///
    /// The default protocol's address also fills the single request-URL field,
    /// because that is the one a user reads; the per-protocol options carry the
    /// rest so the projection reads back exactly what the preset declares.
    fn apply_preset_endpoints(
        &mut self,
        preset: &vibex_core::ProviderPreset,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let mut options = self.profile_provider_options.clone();
        if let Some(wire_api) = preset.default_wire_api() {
            options = with_provider_option(
                options,
                "wireApi",
                Some(wire_api.wire_protocol_id().to_string()),
            );
            self.profile_model_edit_wire_api = Some(wire_api);
        }
        for (protocol, url) in &preset.endpoints {
            if let Some(wire_api) =
                vibex_core::ProviderModelWireApi::from_wire_protocol_id(protocol)
            {
                options = with_provider_option(
                    options,
                    &wire_api.protocol_base_url_option_key(),
                    Some(url.clone()),
                );
            }
        }
        if let Some(url) = preset
            .default_wire_api()
            .and_then(|wire_api| preset.endpoint_for(wire_api))
        {
            self.profile_base_url
                .update(cx, |state, cx| state.set_value(url.to_string(), window, cx));
        }
        self.profile_provider_options = options;
        self.rebuild_profile_protocol_base_urls(window, cx);
    }

    /// Switches the draft to one of the preset's regional endpoints.
    ///
    /// A region is only a different set of addresses for the same Provider, so
    /// nothing outside the endpoint fields moves: the name, the models and the
    /// key hint stay what the preset said.
    fn apply_provider_preset_region(
        &mut self,
        region_id: Option<String>,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) {
        let Some(preset) = self.provider_preset_draft.clone() else {
            return;
        };
        // Resolve against the base preset, never against the already-regional
        // one: otherwise switching A → B would keep A's addresses for every
        // protocol B does not override.
        let regional = preset.with_region(region_id.as_deref());
        self.apply_preset_endpoints(&regional, window, cx);
        self.provider_preset_region = region_id.clone();
        let label = match region_id.as_deref() {
            Some(region_id) => preset
                .regions
                .iter()
                .find(|region| region.id == region_id)
                .map(|region| region.display_name.clone())
                .unwrap_or_else(|| region_id.to_string()),
            None => management_locale_text("Default", "默认", "預設").to_string(),
        };
        self.notice = Some(format!("{}: {label}", preset.display_name));
        self.navigation.mark_dirty(ManagementSection::Agents, true);
        cx.notify();
    }

    fn render_profile_identity_section(&mut self, cx: &mut Context<Self>) -> AnyElement {
        // A preset is a starting point, not a mode: it only appears while a new
        // Provider is being created, and editing an existing one never rewrites
        // what it already holds.
        let preset_row = (self.editing_profile_id.is_none()).then(|| {
            let pending = self.mutation.is_some();
            // The chosen preset is named here, because this is the only place
            // that says what the filled fields came from. The choice itself
            // lives on the picker step, one press away.
            let label = match self.provider_preset_draft.as_ref() {
                Some(preset) => format!(
                    "{} · {}",
                    management_locale_text("Start from a preset", "从预设开始", "從預設開始"),
                    preset.display_name
                ),
                None => management_locale_text(
                    "No preset: every field is manual",
                    "未使用预设：全部手动填写",
                    "未使用預設：全部手動填寫",
                )
                .to_string(),
            };
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .justify_between()
                .gap_2()
                .child(
                    div()
                        .min_w_0()
                        .truncate()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(label),
                )
                .child(
                    Button::new("management-provider-preset-change")
                        .xsmall()
                        .ghost()
                        .label(management_locale_text(
                            "Change preset",
                            "更换预设",
                            "更換預設",
                        ))
                        .disabled(pending)
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.provider_preset_picker = true;
                            cx.notify();
                        })),
                )
                .into_any_element()
        });
        let preset = self.provider_preset_draft.clone();
        // "This came from the preset" is recomputed from the value on every
        // frame rather than recorded when the preset was applied, so typing a
        // different value removes the marker by itself and restoring the
        // preset's value brings it back.
        let name_filled = preset
            .as_ref()
            .is_some_and(|preset| preset.display_name == self.profile_name.read(cx).value().trim());
        let website_filled = preset
            .as_ref()
            .and_then(|preset| preset.website.as_deref())
            .is_some_and(|website| website == self.profile_website_url.read(cx).value().trim());
        profile_editor_section(
            management_locale_text("Basics", "基本信息", "基本資訊"),
            None,
            v_flex()
                .w_full()
                .gap_2p5()
                .children(preset_row)
                .child(management_input_field_marked(
                    management_locale_text("Provider name", "供应商名称", "供應商名稱"),
                    provider_preset_filled_marker(name_filled),
                    &self.profile_name,
                    false,
                    self.profile_name_error.as_deref(),
                    cx,
                ))
                .child(management_input_field(
                    management_locale_text("Note", "备注", "備註"),
                    &self.profile_note,
                    false,
                    cx,
                ))
                .child(management_input_field_marked(
                    management_locale_text("Website URL", "官网链接", "官網連結"),
                    provider_preset_filled_marker(website_filled),
                    &self.profile_website_url,
                    false,
                    None,
                    cx,
                ))
                .into_any_element(),
            cx,
        )
    }

    /// Connection: credential surface, base URL, and per-protocol overrides.
    /// The overrides stay collapsed because most Providers only ever set one
    /// address.
    fn render_profile_connection_section(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let shows_endpoint = self
            .projection_editor
            .shows(vibex_core::AgentProjectionFormControl::Endpoint);
        // An Agent-owned endpoint cannot be projected from the profile, so the
        // field is locked to the value the Agent actually calls and the
        // per-protocol overrides disappear with it.
        let fixed_endpoint = self.projection_editor.fixed_endpoint().map(str::to_string);
        let credential_control = self.render_projection_credential_control(cx);
        let preset = self.provider_preset_draft.clone();
        // A region only swaps addresses, so the preset with the chosen region
        // already applied is what every endpoint comparison below reads.
        let regional_preset = preset
            .as_ref()
            .map(|preset| preset.with_region(self.provider_preset_region.as_deref()));
        let mut connection_content = v_flex().w_full().gap_2p5().child(credential_control);
        // A preset that sends the user to a page to create a key says so beside
        // the field. This is the one Link in the dialog: its target is an
        // external page, while every actual command is a Button.
        if let Some(preset) = preset.as_ref()
            && let Some(url) = preset.keys_url.as_deref()
        {
            connection_content = connection_content.child(
                h_flex()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .gap_2()
                    .child(management_field_label(management_locale_text(
                        "Get a key",
                        "获取 Key",
                        "取得 Key",
                    )))
                    .child(
                        gpui_component::link::Link::new(SharedString::from(format!(
                            "provider-preset-keys-{}",
                            preset.id
                        )))
                        .href(url.to_string())
                        .child(management_locale_text(
                            "Open the vendor's key page",
                            "打开厂商的 Key 页面",
                            "開啟廠商的 Key 頁面",
                        )),
                    ),
            );
        }
        // A vendor with several sites (a domestic and an international one, or
        // two regions) is one preset with several endpoint sets, not several
        // entries in the preset list: the difference is an address, and the
        // picker shows that as a choice beside the address it changes.
        if let Some(preset) = preset.as_ref()
            && !preset.regions.is_empty()
        {
            let mut choices = vec![(
                None,
                management_locale_text("Default", "默认", "預設").to_string(),
            )];
            choices.extend(
                preset
                    .regions
                    .iter()
                    .map(|region| (Some(region.id.clone()), region.display_name.clone())),
            );
            let current_label = choices
                .iter()
                .find(|(id, _)| id == &self.provider_preset_region)
                .map(|(_, label)| label.clone())
                .unwrap_or_else(|| management_locale_text("Default", "默认", "預設").to_string());
            let center = cx.weak_entity();
            connection_content = connection_content.child(
                h_flex()
                    .w_full()
                    .items_center()
                    .justify_between()
                    .gap_2()
                    .child(management_field_label(management_locale_text(
                        "Region", "区域", "區域",
                    )))
                    .child(
                        Button::new("provider-preset-region")
                            .xsmall()
                            .outline()
                            .label(current_label)
                            .dropdown_menu(move |menu, _, _| {
                                let mut menu = menu;
                                for (region_id, label) in &choices {
                                    let region_id = region_id.clone();
                                    let center = center.clone();
                                    menu = menu.item(PopupMenuItem::new(label.clone()).on_click(
                                        move |_, window, cx| {
                                            let region_id = region_id.clone();
                                            let _ = center.update(cx, |this, cx| {
                                                this.apply_provider_preset_region(
                                                    region_id, window, cx,
                                                )
                                            });
                                        },
                                    ));
                                }
                                menu
                            }),
                    ),
            );
        }
        if shows_endpoint {
            let endpoint_label = management_locale_text(
                "Default API request URL",
                "默认 API 请求地址",
                "預設 API 請求位址",
            );
            connection_content = connection_content.child(match &fixed_endpoint {
                Some(endpoint) => management_locked_field(
                    endpoint_label,
                    endpoint.clone(),
                    management_locale_text(
                        "The Cline Agent cannot change its base URL yet: it always calls api.openai.com.",
                        "Cline 这个 Agent 暂时无法修改 baseUrl",
                        "Cline 這個 Agent 暫時無法修改 baseUrl",
                    ),
                    cx,
                ),
                None => {
                    let filled = regional_preset.as_ref().is_some_and(|preset| {
                        preset
                            .default_wire_api()
                            .and_then(|wire_api| preset.endpoint_for(wire_api))
                            .is_some_and(|endpoint| {
                                endpoint == self.profile_base_url.read(cx).value().trim()
                            })
                    });
                    management_input_field_marked(
                        endpoint_label,
                        provider_preset_filled_marker(filled),
                        &self.profile_base_url,
                        false,
                        None,
                        cx,
                    )
                }
            });
        }
        if shows_endpoint && fixed_endpoint.is_none() && !self.profile_protocol_base_urls.is_empty()
        {
            let open = self.profile_protocol_advanced_open;
            let overrides = self.pending_protocol_overrides();
            let mut fields = v_flex().w_full().gap_2p5();
            for (wire_api, input) in &self.profile_protocol_base_urls {
                fields = fields.child(management_input_field(
                    provider_protocol_url_override_label(*wire_api),
                    input,
                    false,
                    cx,
                ));
            }
            connection_content = connection_content.child(
                Collapsible::new()
                    .w_full()
                    .open(open)
                    .child(profile_editor_disclosure(
                        PROFILE_PROTOCOL_DISCLOSURE_ID,
                        management_locale_text(
                            "Set an address per protocol",
                            "按协议分别设置地址",
                            "按協定分別設定位址",
                        )
                        .into(),
                        open,
                        (overrides > 0).then(|| {
                            management_status_badge(protocol_override_count(overrides), cx)
                        }),
                        cx,
                    ))
                    .content(fields),
            );
        }
        // Only the Agents whose projected config owns a header map read the
        // rows; every other Agent would store them without a request ever
        // carrying one.
        if self.projection_editor.supports_request_headers() {
            connection_content = connection_content.child(self.render_profile_headers_section(cx));
        }
        profile_editor_section(
            management_locale_text("Connection & credentials", "连接与凭证", "連線與憑證"),
            None,
            connection_content.into_any_element(),
            cx,
        )
    }

    /// Request headers: user-authored rows plus built-in dynamic variables.
    ///
    /// The rows stay behind a disclosure like the protocol overrides, because
    /// most Providers never add one; the count badge makes an already
    /// configured Profile visible at a glance.
    fn render_profile_headers_section(&mut self, cx: &mut Context<Self>) -> AnyElement {
        let open = self.profile_headers_open;
        let count = self.profile_headers.len();
        let common_center = cx.weak_entity();
        let mut content = v_flex().w_full().min_w_0().gap_2().child(
            h_flex()
                .w_full()
                .min_w_0()
                .flex_wrap()
                .items_center()
                .gap_2()
                .child(
                    Button::new("provider-headers-add-common")
                        .xsmall()
                        .outline()
                        .icon(IconName::Plus)
                        .label(management_locale_text(
                            "Add common header",
                            "添加常用请求头",
                            "新增常用請求標頭",
                        ))
                        .dropdown_menu(move |menu, _, _| {
                            let mut menu = menu;
                            for (name, variable) in provider_common_headers() {
                                let label = match variable {
                                    Some(variable) => format!(
                                        "{name} · {}",
                                        provider_header_variable_label(variable)
                                    ),
                                    None => name.to_string(),
                                };
                                let center = common_center.clone();
                                menu = menu.item(PopupMenuItem::new(label).on_click(
                                    move |_, window, cx| {
                                        let _ = center.update(cx, |this, cx| {
                                            this.add_profile_header_row(
                                                name.to_string(),
                                                variable,
                                                window,
                                                cx,
                                            )
                                        });
                                    },
                                ));
                            }
                            menu
                        }),
                )
                .child(
                    Button::new("provider-headers-import-toggle")
                        .xsmall()
                        .outline()
                        .label(if self.profile_headers_import_open {
                            management_locale_text("Cancel import", "取消导入", "取消匯入")
                        } else {
                            management_locale_text("Import JSON", "导入 JSON", "匯入 JSON")
                        })
                        .on_click(cx.listener(|this, _, _, cx| {
                            this.profile_headers_import_open = !this.profile_headers_import_open;
                            this.profile_headers_error = None;
                            cx.notify();
                        })),
                )
                .child(
                    Button::new("provider-headers-copy")
                        .xsmall()
                        .outline()
                        .icon(IconName::Copy)
                        .label(management_locale_text(
                            "Copy headers JSON",
                            "复制请求头 JSON",
                            "複製請求標頭 JSON",
                        ))
                        .on_click(cx.listener(|this, _, _, cx| {
                            let json = this
                                .profile_header_entries(cx)
                                .map(|entries| serialize_profile_header_override(&entries))
                                .unwrap_or_else(|_| {
                                    serialize_profile_header_override(
                                        &this.draft_header_entries(cx),
                                    )
                                });
                            cx.write_to_clipboard(gpui::ClipboardItem::new_string(json));
                        })),
                ),
        );
        if !open {
            return Collapsible::new()
                .w_full()
                .open(false)
                .child(profile_editor_disclosure(
                    PROFILE_HEADERS_DISCLOSURE_ID,
                    management_locale_text("Request headers", "请求头", "請求標頭").into(),
                    false,
                    (count > 0).then(|| management_status_badge(format!("{count}"), cx)),
                    cx,
                ))
                .into_any_element();
        }
        if self.profile_headers_import_open {
            content = content.child(
                v_flex()
                    .w_full()
                    .gap_2()
                    .child(
                        Textarea::new(&self.profile_headers_import)
                            .small()
                            .w_full()
                            .h(px(88.0)),
                    )
                    .child(
                        Button::new("provider-headers-import-apply")
                            .xsmall()
                            .primary()
                            .label(management_locale_text(
                                "Apply JSON",
                                "应用 JSON",
                                "套用 JSON",
                            ))
                            .on_click(cx.listener(|this, _, window, cx| {
                                this.apply_profile_headers_import(window, cx);
                            })),
                    ),
            );
        }
        for index in 0..self.profile_headers.len() {
            content = content.child(self.render_profile_header_row(index, cx));
        }
        content = content.child(
            Button::new("provider-headers-add")
                .xsmall()
                .outline()
                .icon(IconName::Plus)
                .label(management_locale_text(
                    "Add header",
                    "添加请求头",
                    "新增請求標頭",
                ))
                .on_click(cx.listener(|this, _, window, cx| {
                    this.add_profile_header_row(String::new(), None, window, cx);
                })),
        );
        content = content.children(
            self.profile_headers_error
                .clone()
                .map(|message| management_field_error(message, cx)),
        );
        Collapsible::new()
            .w_full()
            .open(true)
            .child(profile_editor_disclosure(
                PROFILE_HEADERS_DISCLOSURE_ID,
                management_locale_text("Request headers", "请求头", "請求標頭").into(),
                true,
                (count > 0).then(|| management_status_badge(format!("{count}"), cx)),
                cx,
            ))
            .content(content)
            .into_any_element()
    }

    /// One header row: name, value (literal or variable), variable picker, and
    /// a remove action.
    fn render_profile_header_row(&mut self, index: usize, cx: &mut Context<Self>) -> AnyElement {
        let Some(draft) = self.profile_headers.get(index) else {
            return div().into_any_element();
        };
        let name_input = draft.name.clone();
        let value_input = draft.value.clone();
        let variable = draft.variable;
        let center = cx.weak_entity();
        let mut row = h_flex()
            .w_full()
            .min_w_0()
            .items_center()
            .gap_2()
            .child(
                div()
                    .min_w_0()
                    .flex_1()
                    .child(Input::new(&name_input).small().w_full()),
            )
            .child(match variable {
                Some(variable) => div()
                    .min_w_0()
                    .flex_1()
                    .h(px(26.0))
                    .flex()
                    .items_center()
                    .rounded(px(6.0))
                    .bg(cx.theme().muted.opacity(0.35))
                    .px_2()
                    .text_xs()
                    .text_color(cx.theme().muted_foreground)
                    .child(format!(
                        "{{{{{}}}}}",
                        provider_header_variable_label(variable)
                    ))
                    .into_any_element(),
                None => div()
                    .min_w_0()
                    .flex_1()
                    .child(Input::new(&value_input).small().w_full())
                    .into_any_element(),
            });
        row = row.child(
            Button::new(SharedString::from(format!(
                "provider-header-{index}-variable"
            )))
            .xsmall()
            .outline()
            .label(match variable {
                Some(variable) => provider_header_variable_label(variable),
                None => management_locale_text("Value", "值", "值"),
            })
            .dropdown_menu(move |menu, _, _| {
                let mut menu = menu.item(
                    PopupMenuItem::new(management_locale_text("Literal value", "固定值", "固定值"))
                        .checked(variable.is_none())
                        .on_click({
                            let center = center.clone();
                            move |_, _, cx| {
                                let _ = center.update(cx, |this, cx| {
                                    this.set_profile_header_variable(index, None, cx)
                                });
                            }
                        }),
                );
                for candidate in vibex_core::ModelProviderHeaderVariable::ALL {
                    let center = center.clone();
                    menu = menu.item(
                        PopupMenuItem::new(provider_header_variable_label(candidate))
                            .checked(variable == Some(candidate))
                            .on_click(move |_, _, cx| {
                                let _ = center.update(cx, |this, cx| {
                                    this.set_profile_header_variable(index, Some(candidate), cx)
                                });
                            }),
                    );
                }
                menu
            }),
        );
        row = row.child(
            Button::new(SharedString::from(format!(
                "provider-header-{index}-remove"
            )))
            .xsmall()
            .ghost()
            .icon(IconName::Close)
            .tooltip(management_locale_text(
                "Remove header",
                "删除请求头",
                "刪除請求標頭",
            ))
            .on_click(cx.listener(move |this, _, _, cx| {
                this.remove_profile_header(index, cx);
            })),
        );
        row.into_any_element()
    }

    /// The rows as the override would store them, ignoring validation, for the
    /// copy-JSON action.
    fn draft_header_entries(
        &self,
        cx: &Context<Self>,
    ) -> Vec<(String, ProfileHeaderOverrideValue)> {
        self.profile_headers
            .iter()
            .filter_map(|draft| {
                let name = draft.name.read(cx).value().trim().to_string();
                if name.is_empty() {
                    return None;
                }
                let value = match draft.variable {
                    Some(variable) => ProfileHeaderOverrideValue::Variable(variable),
                    None => ProfileHeaderOverrideValue::Literal(
                        draft.value.read(cx).value().trim().to_string(),
                    ),
                };
                Some((name, value))
            })
            .collect()
    }

    fn open_agent_auth_link(&mut self, url: String, cx: &mut Context<Self>) {
        match validate_external_open_url(&url)
            .and_then(|validated| crate::platform::open_external_url(&validated.url))
        {
            Ok(()) => {}
            Err(error) => {
                self.agent_auth_error = Some(format!("{}: {}", error.code, error.message));
                cx.notify();
            }
        }
    }

    /// The Agent's route graph: every way this Agent can reach a model, on one
    /// page.
    ///
    /// The middle column is the whole point. A Provider list says what exists;
    /// this says what *this* Agent may use, in the order it would try them, and
    /// what state each source is in right now. The gateway is one node because
    /// there is one listener, and its routes are listed beneath it — drawing a
    /// node per route would suggest they could be started independently.
    fn render_agent_authentication(
        &mut self,
        window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        self.ensure_agent_auth_inputs(window, cx);
        self.ensure_agent_auth_terminal_surface(window, cx);
        let selected_agent_id = self.selected_agent_id.clone();
        let active_auth_operation = selected_agent_id
            .as_deref()
            .and_then(|agent_id| self.agent_auth_operations.get(agent_id))
            .cloned();
        let selected_agent_pending = selected_agent_id
            .as_deref()
            .is_some_and(|agent_id| self.agent_mutations.contains_key(agent_id));
        let pending = self.mutation.is_some()
            || selected_agent_pending
            || self.agent_auth_terminal_state == Some(AgentAuthTerminalState::Running);
        // Agent account authentication rides the backend contract, so a paired
        // runtime serves it too; only the scope is a local selection.
        let auth_available = self.backend.is_some() && self.current_agent_auth_scope().is_some();
        let catalog = self.agent_auth_catalog.clone();
        let context = self.agent_auth_context.clone();
        let status = if !auth_available {
            management_locale_text("Agent disabled", "Agent 已停用", "Agent 已停用")
        } else if active_auth_operation
            .as_ref()
            .is_some_and(|operation| operation.phase == AgentAuthOperationPhase::Cancelling)
        {
            management_locale_text("Stopping sign-in", "正在终止登录", "正在終止登入")
        } else if active_auth_operation.is_some() {
            management_locale_text("Signing in", "正在登录", "正在登入")
        } else {
            match context.as_ref().map(|context| context.status) {
                Some(AgentAuthContextStatus::Authenticated) => {
                    management_locale_text("Signed in", "已登录", "已登入")
                }
                Some(AgentAuthContextStatus::AuthenticationRequired) => {
                    management_locale_text("Sign-in required", "需要登录", "需要登入")
                }
                Some(AgentAuthContextStatus::Verifying) => {
                    management_locale_text("Verifying", "正在验证", "正在驗證")
                }
                Some(AgentAuthContextStatus::Unavailable) => {
                    management_locale_text("Temporarily unavailable", "暂不可用", "暫不可用")
                }
                Some(AgentAuthContextStatus::Unverified) => {
                    management_locale_text("Not verified", "尚未验证", "尚未驗證")
                }
                None if self.agent_auth_loading => {
                    management_locale_text("Discovering", "正在发现", "正在探索")
                }
                None => management_locale_text("Unavailable", "暂不可用", "暫不可用"),
            }
        };
        let native_authenticated = context
            .as_ref()
            .is_some_and(|context| context.status == AgentAuthContextStatus::Authenticated);
        let authenticated_method_id = context
            .as_ref()
            .and_then(|context| context.authenticated_via_method.clone());
        let supports_logout = catalog
            .as_ref()
            .is_some_and(|catalog| catalog.supports_logout)
            && native_authenticated;
        let supports_reauthentication = native_authenticated
            && catalog
                .as_ref()
                .is_some_and(agent_auth_catalog_supports_reauthentication);
        // An Agent that advertises sign-in methods but none the client can
        // drive keeps its credentials outside Vibex. Say so plainly instead of
        // rendering buttons that cannot change anything.
        let externally_managed_credentials = catalog
            .as_ref()
            .is_some_and(agent_auth_catalog_is_externally_managed);
        let reauthenticating = supports_reauthentication && self.agent_auth_reauthentication;
        let logout_loading = selected_agent_id.as_deref().is_some_and(|agent_id| {
            matches!(
                self.agent_mutations.get(agent_id),
                Some(ManagementMutation::AgentAuth { action, .. })
                    if action == "logout" || action == "logout-preview"
            )
        });
        let verify_loading = selected_agent_id.as_deref().is_some_and(|agent_id| {
            matches!(
                self.agent_mutations.get(agent_id),
                Some(ManagementMutation::AgentAuth { action, .. }) if action == "verify"
            )
        });
        let models_loading = selected_agent_id.as_deref().is_some_and(|agent_id| {
            matches!(
                self.agent_mutations.get(agent_id),
                Some(ManagementMutation::AgentAuth { action, .. }) if action == "refresh-models"
            )
        });
        let mut content = v_flex().w_full().min_w_0().gap_3().child(
            h_flex()
                .w_full()
                .min_w_0()
                .flex_wrap()
                .items_center()
                .justify_between()
                .gap_2()
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_1()
                        .child(management_status_badge(status.to_string(), cx))
                        .child(
                            div()
                                .truncate()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(management_locale_text(
                                    "Agent-native account · shared with the external Agent CLI",
                                    "Agent 原生账号 · 与外部 Agent CLI 共用",
                                    "Agent 原生帳號 · 與外部 Agent CLI 共用",
                                )),
                        )
                        .when_some(
                            context
                                .as_ref()
                                .and_then(|context| context.account_hint.clone()),
                            |header, hint| {
                                header.child(
                                    div()
                                        .truncate()
                                        .text_xs()
                                        .text_color(cx.theme().muted_foreground)
                                        .child(hint),
                                )
                            },
                        ),
                )
                .child(
                    h_flex()
                        .flex_none()
                        .gap_2()
                        .child(management_detail_icon_action(
                            Button::new("agent-auth-refresh")
                                .small()
                                .outline()
                                .icon(Icon::default().path("icons/vibex/rotate-ccw.svg"))
                                .loading(self.agent_auth_loading)
                                .disabled(pending || self.agent_auth_loading || !auth_available)
                                .on_click(
                                    cx.listener(|this, _, _, cx| this.load_agent_auth(true, cx)),
                                ),
                            management_locale_text(
                                "Refresh methods",
                                "刷新认证方式",
                                "重新整理驗證方式",
                            ),
                        ))
                        .when(context.is_some() && !native_authenticated, |actions| {
                            actions.child(management_detail_icon_action(
                                Button::new("agent-auth-verify")
                                    .small()
                                    .outline()
                                    .icon(Icon::default().path("icons/vibex/file-key.svg"))
                                    .loading(verify_loading)
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.verify_agent_auth_context(cx)
                                    })),
                                management_locale_text("Verify account", "验证账号", "驗證帳號"),
                            ))
                        })
                        .when(native_authenticated, |actions| {
                            actions.child(management_detail_icon_action(
                                Button::new("agent-auth-refresh-models")
                                    .small()
                                    .outline()
                                    .icon(Icon::default().path("icons/vibex/brain.svg"))
                                    .loading(models_loading)
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.refresh_agent_auth_models(cx)
                                    })),
                                management_locale_text(
                                    "Refresh models",
                                    "刷新模型",
                                    "重新整理模型",
                                ),
                            ))
                        })
                        .when(supports_reauthentication && !reauthenticating, |actions| {
                            actions.child(management_detail_icon_action(
                                Button::new("agent-auth-reauthenticate")
                                    .small()
                                    .outline()
                                    .icon(Icon::default().path("icons/vibex/pencil.svg"))
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.begin_agent_reauthentication(cx)
                                    })),
                                management_locale_text("Re-authenticate", "重新认证", "重新驗證"),
                            ))
                        })
                        .when(reauthenticating, |actions| {
                            actions.child(management_detail_icon_action(
                                Button::new("agent-auth-reauthenticate-cancel")
                                    .small()
                                    .outline()
                                    .icon(IconName::Close)
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.cancel_agent_reauthentication(cx)
                                    })),
                                management_locale_text(
                                    "Cancel re-authentication",
                                    "取消重新认证",
                                    "取消重新驗證",
                                ),
                            ))
                        })
                        .when(supports_logout, |actions| {
                            actions.child(management_detail_icon_action(
                                Button::new("agent-auth-logout")
                                    .small()
                                    .danger()
                                    .icon(IconName::ExternalLink)
                                    .loading(logout_loading)
                                    .disabled(pending)
                                    .on_click(cx.listener(|this, _, _, cx| this.logout_agent(cx))),
                                management_locale_text("Sign out", "退出登录", "登出"),
                            ))
                        }),
                ),
        );
        if reauthenticating {
            content = content.child(
                h_flex()
                    .w_full()
                    .items_start()
                    .gap_2()
                    .rounded(px(6.0))
                    .border_1()
                    .border_color(cx.theme().warning.opacity(0.45))
                    .bg(cx.theme().warning.opacity(0.08))
                    .p_3()
                    .child(
                        Icon::new(IconName::TriangleAlert)
                            .size(px(16.0))
                            .text_color(cx.theme().warning),
                    )
                    .child(
                        div()
                            .min_w_0()
                            .text_sm()
                            .child(management_locale_text(
                                "Choose a method to update the shared Agent credentials. Agent processes using the previous credentials will stop.",
                                "选择一种方式来更新共享的 Agent 凭证。使用旧凭证的 Agent 进程将停止。",
                                "選擇一種方式來更新共用的 Agent 憑證。使用舊憑證的 Agent 處理程序將停止。",
                            )),
                    ),
            );
        }
        if let Some(preview) = self.agent_auth_logout_preview.clone() {
            let affected_count = preview.affected_session_ids.len();
            content = content.child(
                v_flex()
                    .w_full()
                    .gap_2()
                    .p_3()
                    .rounded(px(6.0))
                    .border_1()
                    .border_color(cx.theme().danger.opacity(0.45))
                    .bg(cx.theme().danger.opacity(0.08))
                    .child(div().text_sm().font_medium().child(format!(
                        "{}: {affected_count}",
                        management_locale_text(
                            "Signing out also affects the external CLI and Vibex sessions",
                            "退出也会影响外部 CLI 与 Vibex 会话",
                            "登出也會影響外部 CLI 與 Vibex 工作階段",
                        )
                    )))
                    .child(
                        h_flex()
                            .justify_end()
                            .gap_2()
                            .child(
                                Button::new("agent-auth-logout-cancel")
                                    .small()
                                    .outline()
                                    .label(management_locale_text("Cancel", "取消", "取消"))
                                    .disabled(logout_loading)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.cancel_agent_auth_context_logout(cx)
                                    })),
                            )
                            .child(
                                Button::new("agent-auth-logout-confirm")
                                    .small()
                                    .danger()
                                    .label(management_locale_text(
                                        "Confirm sign out",
                                        "确认退出",
                                        "確認登出",
                                    ))
                                    .loading(logout_loading)
                                    .disabled(logout_loading)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.confirm_agent_auth_context_logout(cx)
                                    })),
                            ),
                    ),
            );
        }

        if let Some(model_catalog) = self.agent_auth_model_catalog.as_ref() {
            content = content.child(status_line(
                format!(
                    "{}: {}",
                    management_locale_text(
                        "Models available to this account",
                        "此账号可用模型",
                        "此帳號可用模型",
                    ),
                    model_catalog.models.len()
                ),
                false,
                cx,
            ));
        }

        if !auth_available {
            content = content.child(status_line(
                management_locale_text(
                    "Enable this Agent to access its sign-in methods",
                    "启用此 Agent 后可使用其登录方式",
                    "啟用此 Agent 後可使用其登入方式",
                )
                .to_string(),
                false,
                cx,
            ));
        } else if self.agent_auth_loading && catalog.is_none() {
            content = content.child(status_line(
                management_locale_text(
                    "Reading authentication methods reported by the Agent...",
                    "正在读取 Agent 上报的认证方式...",
                    "正在讀取 Agent 回報的驗證方式...",
                )
                .to_string(),
                false,
                cx,
            ));
        }
        let authenticated_method_is_visible =
            authenticated_method_id.as_deref().is_some_and(|id| {
                catalog.as_ref().is_some_and(|catalog| {
                    catalog.methods.iter().any(|method| {
                        method.id == id
                            && method.effect != AgentAuthMethodEffect::RequiresProviderProfile
                            && method.kind != AgentAuthMethodKind::Environment
                    })
                })
            });
        if native_authenticated && !authenticated_method_is_visible {
            content = content.child(
                h_flex()
                    .w_full()
                    .items_center()
                    .gap_2()
                    .rounded(px(6.0))
                    .border_1()
                    .border_color(cx.theme().success.opacity(0.55))
                    .bg(cx.theme().success.opacity(0.08))
                    .px_3()
                    .py_2()
                    .child(
                        Icon::new(IconName::CircleCheck)
                            .size(px(16.0))
                            .text_color(cx.theme().success),
                    )
                    .child(
                        div()
                            .text_sm()
                            .font_medium()
                            .text_color(cx.theme().success)
                            .child(if supports_logout {
                                management_locale_text(
                                    "Native credentials are signed in; sign out or re-authenticate to change them",
                                    "原生凭证已登录；可退出登录或重新认证来更改凭证",
                                    "原生憑證已登入；可登出或重新驗證來變更憑證",
                                )
                            } else {
                                management_locale_text(
                                    "Native credentials are signed in; re-authenticate to update them",
                                    "原生凭证已登录；可通过重新认证来更新凭证",
                                    "原生憑證已登入；可透過重新驗證來更新憑證",
                                )
                            }),
                    ),
            );
        }
        if let Some(catalog) = catalog {
            // `catalog.methods` is destructured below; the drivability rule
            // needs two more fields of the catalog than the method list carries —
            // the logout capability and the Agent id, because an Agent-kind
            // method is only actionable for the Agents whose pinned build really
            // opens a sign-in.
            let catalog_supports_logout = catalog.supports_logout;
            let catalog_agent_id = catalog.agent_id.clone();
            let methods = catalog
                .methods
                .into_iter()
                .filter(agent_auth_method_is_visible)
                .collect::<Vec<_>>();
            if methods.is_empty() {
                content = content.child(compact_empty_state(
                    management_locale_text(
                        "No Agent account sign-in method reported",
                        "Agent 未上报账户登录方式",
                        "Agent 未回報帳戶登入方式",
                    ),
                    management_locale_text(
                        "Use Verify account to reuse an existing external CLI sign-in.",
                        "可验证并复用外部 CLI 中已有的登录状态。",
                        "可驗證並重用外部 CLI 中既有的登入狀態。",
                    ),
                    cx,
                ));
            }
            if externally_managed_credentials {
                content = content.child(
                    h_flex()
                        .w_full()
                        .items_start()
                        .gap_2()
                        .rounded(px(6.0))
                        .border_1()
                        .border_color(cx.theme().border.opacity(0.75))
                        .bg(cx.theme().muted.opacity(0.20))
                        .p_3()
                        .child(
                            Icon::new(IconName::Info)
                                .size(px(16.0))
                                .text_color(cx.theme().muted_foreground),
                        )
                        .child(
                            div()
                                .min_w_0()
                                .text_sm()
                                .child(management_locale_text(
                                    "This Agent manages its credentials outside Vibex, so they cannot be replaced here. Follow the method's own instructions on the external CLI.",
                                    "此 Agent 的凭证在 Vibex 之外管理，无法在此重新认证。请按下面各方式自身的说明在外部 CLI 中配置。",
                                    "此 Agent 的憑證在 Vibex 之外管理，無法在此重新驗證。請依下列各方式自身的說明在外部 CLI 中設定。",
                                )),
                        ),
                );
            }
            for method in methods {
                let method_authenticated = native_authenticated
                    && authenticated_method_id.as_deref() == Some(method.id.as_str());
                let method_locked =
                    native_authenticated && !reauthenticating && !method_authenticated;
                let method_operation = active_auth_operation
                    .as_ref()
                    .filter(|operation| operation.method_id == method.id)
                    .cloned();
                let terminal_method_running = self.agent_auth_terminal_state
                    == Some(AgentAuthTerminalState::Running)
                    && self
                        .agent_auth_terminal
                        .as_ref()
                        .is_some_and(|terminal| terminal.id == method.id);
                // A method the client cannot drive would run a no-op
                // `authenticate` and still report success, so it is not offered
                // as an action at all.
                let method_drivable = agent_auth_method_is_drivable(
                    &catalog_agent_id,
                    catalog_supports_logout,
                    &method,
                );
                let submit_disabled =
                    pending || !method_drivable || (native_authenticated && !reauthenticating);
                let submit_method_id = method.id.clone();
                let action_button_id =
                    SharedString::from(format!("agent-auth-submit-{}", method.id));
                let (action_button, action_label) = if let Some(operation) = method_operation {
                    let cancelling = operation.phase == AgentAuthOperationPhase::Cancelling;
                    let stop_agent_id = operation.scope.0;
                    let stop_operation_id = operation.operation_id;
                    (
                        Button::new(action_button_id)
                            .small()
                            .danger()
                            .icon(IconName::Close)
                            .loading(cancelling)
                            .disabled(cancelling)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.cancel_agent_authentication(
                                    stop_agent_id.clone(),
                                    stop_operation_id.clone(),
                                    cx,
                                )
                            })),
                        if cancelling {
                            management_locale_text(
                                "Stopping sign-in",
                                "正在终止登录",
                                "正在終止登入",
                            )
                        } else {
                            management_locale_text("Stop sign-in", "终止登录", "終止登入")
                        },
                    )
                } else if terminal_method_running {
                    (
                        Button::new(action_button_id)
                            .small()
                            .danger()
                            .icon(IconName::Close)
                            .on_click(
                                cx.listener(|this, _, _, cx| this.close_agent_auth_terminal(cx)),
                            ),
                        management_locale_text("Stop sign-in", "终止登录", "終止登入"),
                    )
                } else if method_authenticated && !reauthenticating {
                    (
                        Button::new(action_button_id)
                            .small()
                            .secondary()
                            .icon(IconName::CircleCheck)
                            .disabled(true),
                        management_locale_text(
                            "Signed in with this method",
                            "已通过此方式登录",
                            "已透過此方式登入",
                        ),
                    )
                } else {
                    let action_label = if reauthenticating {
                        if method_authenticated {
                            management_locale_text("Re-authenticate", "重新认证", "重新驗證")
                        } else {
                            management_locale_text(
                                "Switch and re-authenticate",
                                "切换并重新认证",
                                "切換並重新驗證",
                            )
                        }
                    } else {
                        match method.kind {
                            AgentAuthMethodKind::Agent => {
                                management_locale_text("Sign in", "登录", "登入")
                            }
                            AgentAuthMethodKind::Environment => management_locale_text(
                                "Save and sign in",
                                "保存并登录",
                                "儲存並登入",
                            ),
                            AgentAuthMethodKind::Terminal => management_locale_text(
                                "Open sign-in terminal",
                                "打开登录终端",
                                "開啟登入終端",
                            ),
                        }
                    };
                    let action_icon = match method.kind {
                        AgentAuthMethodKind::Agent => {
                            Icon::default().path("icons/vibex/file-key.svg")
                        }
                        AgentAuthMethodKind::Environment => {
                            Icon::default().path("icons/vibex/file-lock.svg")
                        }
                        AgentAuthMethodKind::Terminal => {
                            Icon::default().path("icons/vibex/file-terminal.svg")
                        }
                    };
                    (
                        Button::new(action_button_id)
                            .small()
                            .primary()
                            .icon(action_icon)
                            .disabled(submit_disabled)
                            .on_click(cx.listener(move |this, _, _, cx| {
                                this.authenticate_agent(submit_method_id.clone(), cx)
                            })),
                        action_label,
                    )
                };
                let mut method_content = v_flex()
                    .w_full()
                    .min_w_0()
                    .gap_3()
                    .border_t_1()
                    .border_color(if method_authenticated {
                        cx.theme().success.opacity(0.55)
                    } else {
                        cx.theme().border.opacity(0.75)
                    })
                    .pt_3()
                    .pb_1()
                    .when(method_locked, |method| method.opacity(0.55))
                    .child(
                        h_flex()
                            .w_full()
                            .min_w_0()
                            .items_start()
                            .justify_between()
                            .gap_3()
                            .child(
                                v_flex()
                                    .min_w_0()
                                    .flex_1()
                                    .gap_1()
                                    .child(
                                        h_flex()
                                            .min_w_0()
                                            .gap_2()
                                            .when(method_authenticated, |row| {
                                                row.child(
                                                    Icon::new(IconName::CircleCheck)
                                                        .size(px(16.0))
                                                        .text_color(cx.theme().success),
                                                )
                                            })
                                            .child(
                                                div()
                                                    .text_sm()
                                                    .font_semibold()
                                                    .when(method_authenticated, |name| {
                                                        name.text_color(cx.theme().success)
                                                    })
                                                    .child(method.name),
                                            ),
                                    )
                                    .when_some(method.description, |title, description| {
                                        title.child(
                                            div()
                                                .text_xs()
                                                .text_color(cx.theme().muted_foreground)
                                                .child(description),
                                        )
                                    }),
                            )
                            .child(management_detail_icon_action(action_button, action_label)),
                    );

                if method_authenticated {
                    method_content = method_content.child(
                        h_flex()
                            .w_full()
                            .items_center()
                            .gap_2()
                            .text_xs()
                            .font_medium()
                            .text_color(cx.theme().success)
                            .child(Icon::new(IconName::CircleCheck).size(px(14.0)))
                            .child(management_locale_text(
                                "Authenticated through this native credential method",
                                "已通过此原生凭证方式完成登录",
                                "已透過此原生憑證方式完成登入",
                            )),
                    );
                } else if method_locked {
                    method_content = method_content.child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(management_locale_text(
                                "Re-authentication is required to switch to this method",
                                "切换到此方式需要重新认证",
                                "切換到此方式需要重新驗證",
                            )),
                    );
                }

                for variable in method.environment {
                    let key = agent_auth_input_key(&method.id, &variable.name);
                    let Some(input) = self.agent_auth_inputs.get(&key) else {
                        continue;
                    };
                    let label = variable
                        .label
                        .as_deref()
                        .map(|label| format!("{label} · {}", variable.name))
                        .unwrap_or_else(|| variable.name.clone());
                    let input_element = if variable.secret {
                        Input::new(input)
                            .small()
                            .w_full()
                            .mask_toggle()
                            .into_any_element()
                    } else {
                        Input::new(input).small().w_full().into_any_element()
                    };
                    let clear_key = key.clone();
                    let clearing = self.agent_auth_clear_values.contains(&key);
                    let clear_label = if clearing {
                        management_locale_text("Keep saved value", "保留已保存值", "保留已儲存值")
                    } else {
                        management_locale_text("Clear saved value", "清除已保存值", "清除已儲存值")
                    };
                    method_content = method_content.child(
                        v_flex()
                            .w_full()
                            .gap_1()
                            .child(
                                h_flex()
                                    .w_full()
                                    .min_w_0()
                                    .items_center()
                                    .justify_between()
                                    .gap_2()
                                    .child(
                                        h_flex()
                                            .min_w_0()
                                            .flex_1()
                                            .gap_2()
                                            .child(
                                                div()
                                                    .truncate()
                                                    .text_xs()
                                                    .font_medium()
                                                    .text_color(cx.theme().muted_foreground)
                                                    .child(label),
                                            )
                                            .when(variable.optional, |row| {
                                                row.child(management_status_badge(
                                                    management_locale_text(
                                                        "Optional", "可选", "選填",
                                                    )
                                                    .to_string(),
                                                    cx,
                                                ))
                                            })
                                            .when(variable.configured && !clearing, |row| {
                                                row.child(management_status_badge(
                                                    management_locale_text(
                                                        "Configured",
                                                        "已配置",
                                                        "已設定",
                                                    )
                                                    .to_string(),
                                                    cx,
                                                ))
                                            }),
                                    )
                                    .when(variable.configured, |row| {
                                        row.child(management_detail_icon_action(
                                            Button::new(SharedString::from(format!(
                                                "agent-auth-clear-{key}"
                                            )))
                                            .small()
                                            .outline()
                                            .icon(if clearing {
                                                Icon::new(IconName::Undo2)
                                            } else {
                                                Icon::default().path("icons/vibex/trash-2.svg")
                                            })
                                            .disabled(pending)
                                            .on_click(cx.listener(move |this, _, _, cx| {
                                                this.toggle_agent_auth_clear(clear_key.clone(), cx)
                                            })),
                                            clear_label,
                                        ))
                                    }),
                            )
                            .child(input_element),
                    );
                }

                if let Some(link) = method.credential_link {
                    let open_link = link.clone();
                    method_content = method_content.child(
                        h_flex()
                            .w_full()
                            .justify_end()
                            .child(management_detail_icon_action(
                                Button::new(SharedString::from(format!(
                                    "agent-auth-credential-link-{}",
                                    method.id
                                )))
                                .small()
                                .link()
                                .icon(IconName::ExternalLink)
                                .on_click(cx.listener(
                                    move |this, _, _, cx| {
                                        this.open_agent_auth_link(open_link.clone(), cx)
                                    },
                                )),
                                management_locale_text("Get credentials", "获取凭据", "取得憑證"),
                            )),
                    );
                }
                content = content.child(method_content);
            }
        }

        if let Some((_, terminal)) = self.agent_auth_terminal_surface.as_ref() {
            let terminal_status = match self.agent_auth_terminal_state {
                Some(AgentAuthTerminalState::Running) => {
                    management_locale_text("Sign-in in progress", "正在登录", "正在登入")
                }
                Some(AgentAuthTerminalState::Succeeded) => {
                    management_locale_text("Sign-in completed", "登录已完成", "登入已完成")
                }
                Some(AgentAuthTerminalState::Failed) => {
                    management_locale_text("Sign-in failed", "登录失败", "登入失敗")
                }
                None => management_locale_text("Sign-in terminal", "登录终端", "登入終端"),
            };
            content =
                content
                    .child(
                        h_flex()
                            .w_full()
                            .items_center()
                            .justify_between()
                            .gap_2()
                            .child(management_status_badge(terminal_status.to_string(), cx))
                            .child(management_detail_icon_action(
                                Button::new("agent-auth-terminal-close")
                                    .xsmall()
                                    .ghost()
                                    .icon(IconName::Close)
                                    .on_click(cx.listener(|this, _, _, cx| {
                                        this.close_agent_auth_terminal(cx)
                                    })),
                                management_locale_text(
                                    "Close sign-in terminal",
                                    "关闭登录终端",
                                    "關閉登入終端",
                                ),
                            )),
                    )
                    .child(
                        div()
                            .text_xs()
                            .text_color(cx.theme().muted_foreground)
                            .child(management_locale_text(
                                "Agent CLI authentication session",
                                "Agent CLI 认证会话",
                                "Agent CLI 驗證工作階段",
                            )),
                    )
                    .child(
                        div()
                            .w_full()
                            .h(px(320.0))
                            .min_h(px(220.0))
                            .overflow_hidden()
                            .rounded(px(8.0))
                            .border_1()
                            .border_color(cx.theme().border)
                            .child(terminal.clone()),
                    );
        }

        management_card_with_icon(
            management_locale_text("Native credentials", "原生凭证", "原生憑證"),
            management_locale_text(
                "Sign in with authentication methods reported by this Agent",
                "使用此 Agent 探测并上报的认证方式登录",
                "使用此 Agent 探測並回報的驗證方式登入",
            ),
            "icons/vibex/shield-alert.svg",
            content.into_any_element(),
            cx,
        )
    }

    fn render_agent_install_loading(
        &self,
        _agent: &AgentSnapshotEntry,
        upgrading: bool,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let title = if upgrading {
            management_locale_text("Upgrading Agent", "正在升级 Agent", "正在升級 Agent")
        } else {
            management_locale_text("Downloading Agent", "正在下载 Agent", "正在下載 Agent")
        };
        let description = if upgrading {
            management_locale_text(
                "The verified runtime is being prepared before the new version is enabled.",
                "正在校验并准备新运行时，完成后才会启用新版本。",
                "正在驗證並準備新執行環境，完成後才會啟用新版本。",
            )
        } else {
            management_locale_text(
                "The Agent is downloaded and verified before it becomes available.",
                "Agent 会先下载并校验，完成后才会正式可用。",
                "Agent 會先下載並驗證，完成後才會正式可用。",
            )
        };
        management_card_with_icon(
            title,
            management_locale_text(
                "Verified ACP Registry runtime",
                "ACP Registry 托管运行时",
                "ACP Registry 託管執行環境",
            ),
            "icons/vibex/download.svg",
            v_flex()
                .w_full()
                .items_center()
                .justify_center()
                .gap_3()
                .py(px(44.0))
                .child(
                    Button::new("management-agent-install-loading")
                        .large()
                        .ghost()
                        .loading(true)
                        .disabled(true)
                        .label(title),
                )
                .child(
                    div()
                        .max_w(px(460.0))
                        .text_sm()
                        .text_color(cx.theme().muted_foreground)
                        .text_center()
                        .child(description),
                )
                .into_any_element(),
            cx,
        )
    }

    fn render_agent_installation_card(
        &mut self,
        agent: &AgentSnapshotEntry,
        _window: &mut Window,
        cx: &mut Context<Self>,
    ) -> AnyElement {
        let state = &agent.managed_install;
        if !state.managed {
            let content = v_flex()
                .w_full()
                .gap_2()
                .child(
                    h_flex()
                        .w_full()
                        .items_center()
                        .justify_between()
                        .gap_2()
                        .child(div().text_sm().font_medium().child(management_locale_text(
                            "External CLI",
                            "外部 CLI",
                            "外部 CLI",
                        )))
                        .child(management_status_badge(
                            management_locale_text("Managed by user", "由用户管理", "由使用者管理")
                                .to_string(),
                            cx,
                        )),
                )
                .child(
                    div()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(management_locale_text(
                            "Vibex uses the CLI already available on PATH for this Agent.",
                            "Vibex 使用此 Agent 在 PATH 中已有的 CLI。",
                            "Vibex 使用此 Agent 在 PATH 中已有的 CLI。",
                        )),
                );
            return management_card_with_icon(
                management_locale_text("Agent installation", "Agent 安装", "Agent 安裝"),
                management_locale_text(
                    "This Agent is not distributed through the verified ACP Registry.",
                    "此 Agent 暂未提供可校验的 ACP Registry 分发包。",
                    "此 Agent 暫未提供可驗證的 ACP Registry 分發包。",
                ),
                "icons/vibex/download.svg",
                content.into_any_element(),
                cx,
            );
        }

        let id = agent.id.as_str().to_string();
        let mutation = self.agent_mutations.get(&id);
        let healthy_installation = state.has_usable_installation();
        let needs_install = !healthy_installation
            && matches!(
                state.status,
                vibex_core::AgentManagedInstallStatus::NotInstalled
                    | vibex_core::AgentManagedInstallStatus::Failed
            );
        let checking = healthy_installation
            && matches!(
                mutation,
                Some(ManagementMutation::AgentUpdateCheck(active_id)) if active_id == &id
            );
        let upgrading = matches!(
            mutation,
            Some(ManagementMutation::AgentInstall(active_id)) if active_id == &id
        );
        let rolling_back = matches!(
            mutation,
            Some(ManagementMutation::AgentRollback(active_id)) if active_id == &id
        );
        let uninstalling = matches!(
            mutation,
            Some(ManagementMutation::AgentUninstall(active_id)) if active_id == &id
        );
        let update_available =
            state.status == vibex_core::AgentManagedInstallStatus::UpdateAvailable;
        // Vibex's own catalog pin, offered only where this installation can
        // actually be moved to it.
        let rollback_version = state.rollback_version(&agent.id);
        let mut content = v_flex().w_full().gap_2();
        let available_version = state
            .available_version
            .as_deref()
            .filter(|version| state.installed_version.as_deref() != Some(*version))
            .map(str::to_string);
        content = content.child(
            h_flex()
                .w_full()
                .items_center()
                .justify_between()
                .gap_2()
                .child(management_status_badge(
                    management_managed_install_status_label(state).to_string(),
                    cx,
                ))
                .child(
                    h_flex()
                        .flex_none()
                        .items_center()
                        .gap_2()
                        .when_some(state.installed_version.clone(), |row, version| {
                            row.child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(format!("v{version}")),
                            )
                        })
                        .when_some(available_version.clone(), |row, version| {
                            row.child(div().text_xs().text_color(cx.theme().success).child(
                                format!(
                                    "{}: v{version}",
                                    management_locale_text("Available", "可用版本", "可用版本")
                                ),
                            ))
                        })
                        .when_some(rollback_version, |row, version| {
                            row.child(
                                div()
                                    .text_xs()
                                    .text_color(cx.theme().muted_foreground)
                                    .child(format!(
                                        "{}: v{version}",
                                        management_locale_text("Verified", "验证版本", "驗證版本")
                                    )),
                            )
                        }),
                ),
        );
        if let Some(error) = state.last_error_message.as_deref() {
            content = content.child(
                div()
                    .text_xs()
                    .text_color(cx.theme().danger)
                    .child(error.to_string()),
            );
        }
        let pending = mutation.is_some();
        let mut actions = h_flex().w_full().justify_end().gap_2();
        if needs_install {
            actions = actions.child(management_detail_icon_action(
                Button::new(SharedString::from(format!("management-agent-install-{id}")))
                    .small()
                    .primary()
                    .icon(IconName::ArrowDown)
                    .loading(upgrading)
                    .disabled(pending)
                    .on_click(cx.listener({
                        let id = id.clone();
                        move |this, _, _, cx| this.install_managed_agent(id.clone(), false, cx)
                    })),
                management_locale_text("Install", "安装", "安裝"),
            ));
        } else if healthy_installation {
            actions = actions.child(management_detail_icon_action(
                Button::new(SharedString::from(format!("management-agent-check-{id}")))
                    .small()
                    .outline()
                    .icon(IconName::Search)
                    .loading(checking)
                    .disabled(pending)
                    .on_click(cx.listener({
                        let id = id.clone();
                        move |this, _, _, cx| this.check_managed_agent_update(id.clone(), cx)
                    })),
                management_locale_text("Check for updates", "检查更新", "檢查更新"),
            ));
        }
        if update_available && healthy_installation {
            actions = actions.child(management_detail_icon_action(
                Button::new(SharedString::from(format!("management-agent-upgrade-{id}")))
                    .small()
                    .primary()
                    .icon(IconName::ArrowUp)
                    .loading(upgrading)
                    .disabled(pending)
                    .on_click(cx.listener({
                        let id = id.clone();
                        move |this, _, _, cx| this.install_managed_agent(id.clone(), true, cx)
                    })),
                management_locale_text("Upgrade", "升级", "升級"),
            ));
        }
        if rollback_version.is_some() {
            actions = actions.child(management_detail_icon_action(
                Button::new(SharedString::from(format!(
                    "management-agent-rollback-{id}"
                )))
                .small()
                .outline()
                .icon(IconName::Undo2)
                .loading(rolling_back)
                .disabled(pending)
                .on_click(cx.listener({
                    let id = id.clone();
                    move |this, _, _, cx| this.rollback_managed_agent(id.clone(), cx)
                })),
                management_locale_text(
                    "Roll back to the Vibex-verified version",
                    "回滚到 Vibex 验证版本",
                    "回滾到 Vibex 驗證版本",
                ),
            ));
        }
        if agent.added || state.installed_version.is_some() {
            let uninstall_label = agent.label.clone();
            actions = actions.child(management_detail_icon_action(
                Button::new(SharedString::from(format!(
                    "management-agent-uninstall-{id}"
                )))
                .small()
                .danger()
                .icon(Icon::default().path("icons/vibex/trash-2.svg"))
                .loading(uninstalling)
                .disabled(pending)
                .on_click(cx.listener({
                    let id = id.clone();
                    move |this, _, window, cx| {
                        this.confirm_managed_delete(
                            ManagedDeleteTarget::Agent {
                                id: id.clone(),
                                label: uninstall_label.clone(),
                            },
                            window,
                            cx,
                        )
                    }
                })),
                management_locale_text("Uninstall", "卸载", "解除安裝"),
            ));
        }
        content = content.child(actions);
        management_card_with_icon(
            management_locale_text("Agent installation", "Agent 安装", "Agent 安裝"),
            management_locale_text(
                "Vibex-managed runtime",
                "Vibex 托管运行时",
                "Vibex 託管執行環境",
            ),
            "icons/vibex/download.svg",
            content.into_any_element(),
            cx,
        )
    }

