fn agent_provider_profile_states(
    agent_id: &str,
    profiles: impl IntoIterator<Item = vibex_core::ProviderProfile>,
    default_profile_id: Option<&vibex_core::ProviderProfileId>,
) -> Vec<AgentProviderProfileState> {
    profiles
        .into_iter()
        .map(|profile| AgentProviderProfileState {
            agent_id: agent_id.to_string(),
            profile_id: profile.id.as_str().to_string(),
            is_default: default_profile_id == Some(&profile.id),
        })
        .collect()
}

fn agent_auth_input_key(method_id: &str, variable_name: &str) -> String {
    format!("{}:{method_id}{variable_name}", method_id.len())
}

/// Whether "re-authenticate" can actually replace the shared credentials for
/// this catalog.
///
/// The rule lives on [`AgentAuthCatalog::supports_reauthentication`] so the
/// desktop, the TUI and any future client answer this the same way. Method kind
/// alone is not evidence: `Agent` kind only means the Agent handles
/// authentication itself, and several Agents answer `authenticate` with an empty
/// result and no side effect.
pub(crate) fn agent_auth_catalog_supports_reauthentication(catalog: &AgentAuthCatalog) -> bool {
    catalog.supports_reauthentication()
}

/// Whether one advertised method can carry a credential change the client can
/// drive. Thin wrapper over [`vibex_core::AgentAuthMethod::is_client_drivable`]
/// so this module keeps one spelling of the rule for its callers.
pub(crate) fn agent_auth_method_is_drivable(
    agent_id: &AgentId,
    supports_logout: bool,
    method: &vibex_core::AgentAuthMethod,
) -> bool {
    method.is_client_drivable(agent_id, supports_logout)
}

/// Whether an advertised method is one a client may act on at all — the shared
/// filter for which methods an Agent-account surface lists.
pub(crate) fn agent_auth_method_is_visible(method: &vibex_core::AgentAuthMethod) -> bool {
    method.is_visible()
}

/// Whether this Agent advertises sign-in methods but none the client can act
/// on, so its credentials live entirely outside Vibex.
///
/// This gates the explanation, not re-authentication: such an Agent still
/// deserves an honest statement rather than a button that cannot do anything.
fn agent_auth_catalog_is_externally_managed(catalog: &AgentAuthCatalog) -> bool {
    catalog.is_externally_managed()
}

fn agent_auth_scope_matches(
    current_generation: u64,
    current_scope: Option<&(String, Option<String>)>,
    expected_generation: u64,
    expected_scope: &(String, Option<String>),
) -> bool {
    current_generation == expected_generation && current_scope == Some(expected_scope)
}

/// Waits until the sign-in terminal leaves the running state.
///
/// The authority reports the terminal's status in its session, so the same
/// wait works for an in-process PTY and for one owned by a paired runtime. The
/// exit code stays with the authority; a failed sign-in still surfaces through
/// the authentication operation's own error code.
async fn await_agent_auth_terminal_exit(
    transport: &Arc<dyn TerminalTransport>,
    terminal_id: &vibex_core::TerminalId,
) -> Option<VibexError> {
    // A cursor beyond any frame keeps the wait read-only: the snapshot still
    // carries the authoritative session and no output is consumed.
    loop {
        match transport.poll_terminal(terminal_id, i64::MAX).await {
            Ok(snapshot) => match terminal_auth_status_error(snapshot.session.status) {
                // Still running: keep waiting for the interactive sign-in.
                None if snapshot.session.status == vibex_core::TerminalStatus::Running => {}
                outcome => return outcome,
            },
            // A terminal the authority no longer knows must not hang the
            // sign-in; the operation poll below decides the outcome.
            Err(_) => return None,
        }
        tokio::time::sleep(AGENT_AUTH_TERMINAL_POLL_INTERVAL).await;
    }
}

/// A sign-in terminal that was killed or lost can never complete the sign-in.
fn terminal_auth_status_error(status: vibex_core::TerminalStatus) -> Option<VibexError> {
    match status {
        vibex_core::TerminalStatus::Exited => None,
        vibex_core::TerminalStatus::Killed => Some(
            VibexError::process(
                "agent_terminal_auth_failed",
                "Interactive Agent authentication did not complete successfully",
            )
            .with_diagnostic("terminalStatus", "killed"),
        ),
        vibex_core::TerminalStatus::Stale => Some(
            VibexError::process(
                "agent_terminal_auth_failed",
                "Interactive Agent authentication did not complete successfully",
            )
            .with_diagnostic("terminalStatus", "stale"),
        ),
        vibex_core::TerminalStatus::Running => None,
    }
}

/// Polls the authority's authentication operation until it reaches a final
/// state and returns the refreshed context with its model catalogue.
async fn wait_for_agent_auth_completion(
    backend: &BackendFacade,
    operation_id: &AgentAuthenticationOperationId,
) -> VibexResult<AgentAuthContextMutationResult> {
    const MAX_POLLS: usize = 2_400;
    for _ in 0..MAX_POLLS {
        let operation = backend
            .agent()
            .get_agent_authentication_operation(operation_id.clone())
            .await
            .map_err(crate::app::remote_error_into_vibex)?;
        match operation.state {
            vibex_core::AgentAuthenticationOperationState::Succeeded => {
                // Verification commits the credential change, which advances the
                // context revision past the fence this operation was opened
                // against. Refresh against the *committed* revision: reusing the
                // operation's own revision makes the compare-and-set reject the
                // request as a stale-revision conflict, so a sign-in that
                // actually succeeded would surface as an error.
                let contexts = backend
                    .agent()
                    .list_agent_auth_contexts()
                    .await
                    .map_err(crate::app::remote_error_into_vibex)?;
                let request = agent_auth_refresh_request_after_sign_in(&operation, &contexts)?;
                return backend
                    .agent()
                    .refresh_agent_auth_models(MutationRequest::new(request))
                    .await
                    .map_err(crate::app::remote_error_into_vibex);
            }
            vibex_core::AgentAuthenticationOperationState::Failed => {
                return Err(VibexError::conflict(
                    operation
                        .error_code
                        .as_deref()
                        .unwrap_or("agent_authentication_verification_failed"),
                    "Interactive Agent authentication failed",
                ));
            }
            vibex_core::AgentAuthenticationOperationState::Cancelled => {
                return Err(VibexError::conflict(
                    "agent_authentication_cancelled",
                    "Interactive Agent authentication was cancelled",
                ));
            }
            _ => tokio::time::sleep(std::time::Duration::from_millis(50)).await,
        }
    }
    Err(VibexError::process(
        "agent_authentication_completion_timeout",
        "Interactive Agent authentication did not reach a final state",
    ))
}

/// Builds the post-sign-in model refresh request against the context revision
/// the authority actually committed.
///
/// The operation stores the revision it was opened against, and verification
/// advances that revision as part of committing the credential change. Reusing
/// the operation's revision therefore fails the compare-and-set fence with
/// `agent_auth_context_revision_conflict`, turning a successful sign-in into an
/// error. The freshly read context is authoritative.
fn agent_auth_refresh_request_after_sign_in(
    operation: &vibex_core::AgentAuthenticationOperation,
    contexts: &[AgentAuthContext],
) -> VibexResult<AgentAuthContextRefreshModelsRequest> {
    let context = contexts
        .iter()
        .find(|context| context.id == operation.auth_context_id)
        .ok_or_else(|| {
            VibexError::validation(
                "agent_auth_context_not_found",
                "Agent authentication context was not found after sign-in",
            )
        })?;
    Ok(AgentAuthContextRefreshModelsRequest {
        auth_context_id: context.id.clone(),
        expected_context_revision: context.revision,
    })
}

