/// Replaces one Prompt in place, or appends the new one.
///
/// The authority returns the record a mutation wrote, so the list can show it
/// before the next snapshot read reaches the view.
fn upsert_prompt(prompts: &mut Vec<vibex_core::Prompt>, prompt: &vibex_core::Prompt) {
    if let Some(existing) = prompts.iter_mut().find(|existing| existing.id == prompt.id) {
        *existing = prompt.clone();
    } else {
        prompts.push(prompt.clone());
    }
}

/// Replaces one shared Provider in place, or appends the new one.
fn upsert_shared_provider(
    providers: &mut Vec<vibex_core::ModelProviderProfile>,
    provider: vibex_core::ModelProviderProfile,
) {
    if let Some(existing) = providers
        .iter_mut()
        .find(|existing| existing.id == provider.id)
    {
        *existing = provider;
    } else {
        providers.push(provider);
    }
}

/// Groups shared Provider Profiles by identity and resolves the Agents that
/// bind each one.
///
/// A Profile appears once regardless of how many bindings reference it, which
/// is the property the Agent-scoped list lacked: it filtered by `agent_id`, so
/// one upstream showed up once per Agent.
fn shared_provider_rows(
    profiles: &[vibex_core::ModelProviderProfile],
    bindings: &[vibex_core::AgentModelProviderBinding],
) -> Vec<SharedProviderRow> {
    let mut rows = profiles
        .iter()
        .filter(|profile| profile.deleted_at_ms.is_none())
        .map(|profile| {
            let agents = bindings
                .iter()
                .filter(|binding| {
                    binding.model_provider_profile_id.as_ref() == Some(&profile.id)
                        && binding.deleted_at_ms.is_none()
                })
                .map(|binding| binding.agent_id.as_str().to_string())
                .collect::<BTreeSet<_>>();
            SharedProviderRow {
                profile: profile.clone(),
                agents,
            }
        })
        .collect::<Vec<_>>();
    rows.sort_by(|left, right| {
        left.profile
            .display_name
            .to_lowercase()
            .cmp(&right.profile.display_name.to_lowercase())
            .then(left.profile.id.as_str().cmp(right.profile.id.as_str()))
    });
    rows
}

/// The legacy Provider ids one Agent's bindings point at.
///
/// The Agent page used to derive its Provider rows by filtering the legacy
/// Profile list on `agent_id`. That is the shape the binding replaced: the same
/// upstream bound to three Agents is three legacy Profiles, and a binding is
/// what says which of them this Agent actually selected.
///
/// The ids rather than the records are returned because the page renders the
/// display-safe projection, which carries no Provider options or Secrets. The
/// binding decides *which* rows appear; the legacy id stays the handle every
/// control on the card addresses.
///
/// A binding whose legacy Profile is missing is skipped rather than
/// synthesised: a Profile the authority does not list is one this client cannot
/// edit, and a row that cannot be opened is a dead end.
fn agent_bound_profile_ids(
    agent_id: &vibex_core::AgentId,
    bindings: &[vibex_core::AgentModelProviderBinding],
) -> BTreeSet<String> {
    bindings
        .iter()
        .filter(|binding| binding.deleted_at_ms.is_none() && &binding.agent_id == agent_id)
        .filter_map(|binding| binding.legacy_provider_profile_id.as_ref())
        .map(|profile_id| profile_id.as_str().to_string())
        .collect()
}

/// Why a Key did not serve a reply, in words.
///
/// The stored kind is an enum id; a reader gets the human phrase. Nothing here
/// names a raw id like `failQuota`, because the detail view exists to explain a
/// decision to the person who paid for the Key.
fn gateway_failure_text(
    kind: vibex_core::GatewayFailureKind,
    locale: ResolvedLocale,
) -> &'static str {
    use vibex_core::GatewayFailureKind as Kind;
    match kind {
        Kind::Credit => management_locale_text_for(locale, "out of credit", "余额不足", "餘額不足"),
        Kind::Quota => management_locale_text_for(locale, "out of quota", "额度用尽", "額度用盡"),
        Kind::Rate => management_locale_text_for(locale, "rate limited", "被限流", "被限流"),
        Kind::Auth => management_locale_text_for(locale, "key rejected", "Key 失效", "Key 失效"),
        Kind::Proxy => {
            management_locale_text_for(locale, "proxy refused it", "代理不可用", "代理不可用")
        }
        Kind::Upstream => {
            management_locale_text_for(locale, "upstream unreachable", "无法连接", "無法連線")
        }
        Kind::Other => management_locale_text_for(locale, "unavailable", "暂不可用", "暫不可用"),
    }
}

/// The name a Key is shown under, including when it has been removed.
fn gateway_credential_name(
    name: Option<&str>,
    locale: ResolvedLocale,
) -> std::borrow::Cow<'_, str> {
    match name {
        Some(name) => std::borrow::Cow::Borrowed(name),
        None => std::borrow::Cow::Borrowed(management_locale_text_for(
            locale,
            "a removed key",
            "已删除的 Key",
            "已刪除的 Key",
        )),
    }
}

/// The gateway's own failure code for a request that produced no reply.
///
/// A failed row used to read as a bare "failed" with nothing to look up. The
/// code is what a reader can act on: `model_gateway_translation_failed` names
/// the gateway, `model_gateway_protocol_mismatch` names the endpoint's protocol
/// setting. Only a failed row has one — a successful request's trace is about
/// the route it walked, not about an error.
fn gateway_request_error_code(request: &vibex_core::GatewayRequestSummary) -> Option<String> {
    if matches!(request.outcome, vibex_core::GatewayRequestOutcome::Ok) {
        return None;
    }
    request
        .route
        .as_ref()
        .and_then(|route| route.error_code.clone())
}

/// The route one request took, as the lines the detail view shows.
///
/// The first line is always the chain; every later line is a reason the chain
/// is not simply "gateway, Provider, first Key". A single failover is folded
/// into the chain the way it reads aloud — the Key that answered, followed by
/// the Key that did not and why — while a chain with more than one dead Key
/// lists them, because the parenthesis stops being readable at that point.
fn gateway_route_lines(
    request: &vibex_core::GatewayRequestSummary,
    locale: ResolvedLocale,
) -> Vec<String> {
    let gateway = management_locale_text_for(locale, "Vibex gateway", "Vibex 网关", "Vibex 閘道");
    let serving = gateway_credential_name(request.credential_name.as_deref(), locale);
    let mut chain = format!("{gateway} → {} → {serving}", request.provider_name);
    let mut lines = Vec::new();
    let route = request.route.as_ref();
    if let Some(failure) = route.and_then(|route| {
        (route.failed_attempts.len() == 1).then(|| route.failed_attempts[0].clone())
    }) {
        let failed = gateway_credential_name(failure.credential_name.as_deref(), locale);
        chain.push_str(&format!(
            "（{failed} · {}）",
            gateway_failure_text(failure.failure, locale)
        ));
    }
    lines.push(chain);
    // Only the single-failure case is folded into the chain, so only that one
    // is skipped here; a longer list names every Key it stepped over.
    let failures = route
        .map(|route| route.failed_attempts.as_slice())
        .unwrap_or_default();
    let folded = failures.len() == 1;
    for (index, failure) in failures.iter().enumerate() {
        if folded && index == 0 {
            continue;
        }
        let failed = gateway_credential_name(failure.credential_name.as_deref(), locale);
        lines.push(format!(
            "{} · {}",
            failed,
            gateway_failure_text(failure.failure, locale)
        ));
    }
    if let Some(route) = route {
        if route.skipped_cooling > 0 {
            lines.push(match locale {
                ResolvedLocale::En => format!("skipped {} cooling keys", route.skipped_cooling),
                ResolvedLocale::ZhCn => format!("已跳过 {} 个冷却中的 Key", route.skipped_cooling),
                ResolvedLocale::ZhTw => format!("已跳過 {} 個冷卻中的 Key", route.skipped_cooling),
            });
        }
        if route.skipped_over_limit > 0 {
            lines.push(match locale {
                ResolvedLocale::En => {
                    format!(
                        "skipped {} keys over their token ceiling",
                        route.skipped_over_limit
                    )
                }
                ResolvedLocale::ZhCn => {
                    format!("已跳过 {} 个超出额度上限的 Key", route.skipped_over_limit)
                }
                ResolvedLocale::ZhTw => {
                    format!("已跳過 {} 個超出額度上限的 Key", route.skipped_over_limit)
                }
            });
        }
        // A cross-member failover is the one thing a Key-level trace cannot
        // express: it says a whole source was unavailable, not that a Key
        // cooled. Naming the Provider is what makes "why did this go to the
        // second one" answerable from the ledger.
        for member in &route.skipped_members {
            let provider = member
                .provider_name
                .clone()
                .unwrap_or_else(|| member.model_provider_profile_id.as_str().to_string());
            lines.push(match locale {
                ResolvedLocale::En => {
                    format!(
                        "skipped {provider} · {}",
                        gateway_failure_text(member.failure, locale)
                    )
                }
                ResolvedLocale::ZhCn => {
                    format!(
                        "已跳过 {provider} · {}",
                        gateway_failure_text(member.failure, locale)
                    )
                }
                ResolvedLocale::ZhTw => {
                    format!(
                        "已跳過 {provider} · {}",
                        gateway_failure_text(member.failure, locale)
                    )
                }
            });
        }
    }
    lines
}

/// The two limit fields for one Key.
struct GatewayLimitInputs {
    concurrency: Entity<InputState>,
    rpm: Entity<InputState>,
}

/// Reads one optional count from a limit field.
///
/// An empty field means "no limit", never zero: a zero limit would forbid every
/// request, which is not what clearing the box means.
fn parse_optional_u64(value: &str) -> Result<Option<u64>, &'static str> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    value
        .parse::<u64>()
        .map(Some)
        .map_err(|_| "must be a whole number")
}

fn parse_optional_limit(value: &str) -> Result<Option<u32>, &'static str> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    match value.parse::<u32>() {
        Ok(count) if count > 0 => Ok(Some(count)),
        Ok(_) => Err("must be greater than zero"),
        Err(_) => Err("must be a whole number"),
    }
}

