/// has to act on or at least know about, so it carries a colour.
fn gateway_status_badge(state: &vibex_core::ModelGatewayRuntimeState, _cx: &App) -> AnyElement {
    let (label, tag) = match state.status {
        vibex_core::ModelGatewayStatus::Running => (
            management_locale_text("Running", "运行中", "執行中"),
            Tag::color(ColorName::Green),
        ),
        vibex_core::ModelGatewayStatus::Starting => (
            management_locale_text("Starting", "启动中", "啟動中"),
            Tag::color(ColorName::Blue),
        ),
        vibex_core::ModelGatewayStatus::Unavailable => (
            management_locale_text("Not running", "未运行", "未執行"),
            Tag::color(ColorName::Amber),
        ),
        // A degraded gateway is not a stopped one: the port is still bound and
        // the groups that did not step aside keep serving. The counts that make
        // that legible live beside the badge, so the label only says so much.
        vibex_core::ModelGatewayStatus::Degraded => (
            management_locale_text("Degraded", "已降级", "已降級"),
            Tag::color(ColorName::Amber),
        ),
        vibex_core::ModelGatewayStatus::Disabled => (
            management_locale_text("Off", "已关闭", "已關閉"),
            Tag::color(ColorName::Neutral),
        ),
    };
    tag.xsmall().child(label).into_any_element()
}

/// A cooldown's remaining time, in the shape the rest of the app uses.
fn gateway_cooldown_label(until_ms: Option<i64>) -> String {
    let cooling = management_locale_text("Cooling down", "冷却中", "冷卻中");
    let Some(until_ms) = until_ms else {
        return cooling.to_string();
    };
    let remaining_ms = until_ms.saturating_sub(vibex_core::unix_timestamp_ms());
    if remaining_ms <= 0 {
        return cooling.to_string();
    }
    let minutes = remaining_ms.saturating_add(59_999) / 60_000;
    if minutes < 60 {
        format!(
            "{cooling} · {minutes}{}",
            management_locale_text("m", " 分钟", " 分鐘")
        )
    } else {
        let hours = minutes / 60;
        format!(
            "{cooling} · {hours}{}",
            management_locale_text("h", " 小时", " 小時")
        )
    }
}

/// The window a token ceiling is measured over, in interface language.
fn gateway_token_window_label(window: vibex_core::GatewayTokenWindow) -> &'static str {
    gateway_token_window_label_for(locale::current_locale(), window)
}

fn gateway_token_window_label_for(
    locale: ResolvedLocale,
    window: vibex_core::GatewayTokenWindow,
) -> &'static str {
    match window {
        vibex_core::GatewayTokenWindow::Day => {
            management_locale_text_for(locale, "day", "天", "天")
        }
        vibex_core::GatewayTokenWindow::Week => {
            management_locale_text_for(locale, "week", "周", "週")
        }
        vibex_core::GatewayTokenWindow::Month => {
            management_locale_text_for(locale, "month", "月", "月")
        }
    }
}

/// A token count with thousands separators.
///
/// A seven-digit ceiling is unreadable as `20000000`; grouping is what makes
/// the number confirmable at a glance.
fn gateway_token_count(tokens: u64) -> String {
    let digits = tokens.to_string();
    let mut grouped = String::with_capacity(digits.len() + digits.len() / 3);
    for (index, digit) in digits.chars().enumerate() {
        if index > 0 && (digits.len() - index).is_multiple_of(3) {
            grouped.push(',');
        }
        grouped.push(digit);
    }
    grouped
}

/// Reads the token ceiling draft.
///
/// Grouping separators are accepted because that is how the current limit is
/// displayed; removing them before parsing means "1,000,000" round-trips.
/// An empty field is an error here rather than "unlimited": the field only
/// exists next to a window, and removing the ceiling has its own control.
fn parse_gateway_token_limit(
    value: &str,
    window: vibex_core::GatewayTokenWindow,
) -> Result<vibex_core::GatewayTokenLimit, &'static str> {
    let value = value
        .chars()
        .filter(|character| !matches!(character, '_' | ',' | ' '))
        .collect::<String>();
    if value.is_empty() {
        return Err("enter a token count");
    }
    let tokens = value
        .parse::<u64>()
        .map_err(|_| "must be a whole number of tokens")?;
    let limit = vibex_core::GatewayTokenLimit { window, tokens };
    limit.validate().map_err(|_| "must be greater than zero")?;
    Ok(limit)
}

/// One line describing why the gateway is or is not serving.
fn gateway_runtime_text(state: &vibex_core::ModelGatewayRuntimeState) -> String {
    if let Some(notice) = state.notice.as_deref() {
        return notice.to_string();
    }
    match state.base_url() {
        Some(url) => format!(
            "{} {}",
            management_locale_text("Listening on", "正在监听", "正在監聽"),
            url
        ),
        None => management_locale_text(
            "The gateway is not serving requests; route groups cannot be used.",
            "网关当前未提供服务，路由组无法使用。",
            "閘道目前未提供服務，路由組無法使用。",
        )
        .to_string(),
    }
}

/// Reads the gateway's display-name draft.
///
/// Trimmed, because a name of spaces is empty; length is counted in characters
/// so a CJK name is measured the way the authority measures it.
/// The name a Gateway row shows.
///
/// The stored default is English so the database and the runtime do not depend
/// on the UI locale. The surface still translates that default: a Chinese
/// reader sees `Vibex 网关`, and a name the user typed is shown as typed.
fn gateway_display_name(settings: &vibex_core::ModelGatewaySettings) -> String {
    let default_name = vibex_core::ModelGatewaySettings::default().display_name;
    if settings.display_name == default_name {
        management_locale_text("Vibex Gateway", "Vibex 网关", "Vibex 閘道").to_string()
    } else {
        settings.display_name.clone()
    }
}

fn parse_gateway_display_name(value: &str) -> Result<String, &'static str> {
    let name = value.trim();
    if name.is_empty() {
        return Err("enter a name");
    }
    if name.chars().count() > vibex_core::ModelGatewaySettings::MAX_DISPLAY_NAME_LEN {
        return Err("the name is too long");
    }
    Ok(name.to_string())
}

/// The soonest future cooldown deadline across every upstream Key.
fn next_gateway_cooldown_expiry(
    snapshot: &vibex_core::GatewaySnapshot,
    now_ms: i64,
) -> Option<i64> {
    snapshot
        .upstreams
        .iter()
        .flat_map(|upstream| upstream.keys.iter())
        .filter_map(|key| match key.state {
            vibex_core::GatewayKeyState::Cooling { until_ms, .. } => until_ms,
            _ => None,
        })
        .filter(|until| *until > now_ms)
        .min()
}

/// One protocol direction the gateway may translate into.
///
/// These are switches rather than a free-form policy: a direction is either
/// allowed or refused, and refusing is the safe answer when a deployment is
/// known not to need it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum GatewayTranslation {
    ChatCompletions,
    Responses,
    AnthropicMessages,
    Gemini,
}

impl GatewayTranslation {
    const ALL: [Self; 4] = [
        Self::ChatCompletions,
        Self::Responses,
        Self::AnthropicMessages,
        Self::Gemini,
    ];

    const fn id(self) -> &'static str {
        match self {
            Self::ChatCompletions => "openai-chat",
            Self::Responses => "openai-responses",
            Self::AnthropicMessages => "anthropic-messages",
            Self::Gemini => "google-gemini",
        }
    }

    /// The protocol's name, which is a proper noun and reads the same in every
    /// locale.
    const fn label(self) -> &'static str {
        match self {
            Self::ChatCompletions => "OpenAI Chat Completions",
            Self::Responses => "OpenAI Responses",
            Self::AnthropicMessages => "Anthropic Messages",
            Self::Gemini => "Google Gemini",
        }
    }

    const fn allowed(self, policy: &vibex_core::GatewayTranslatePolicy) -> bool {
        match self {
            Self::ChatCompletions => policy.openai_chat_completions,
            Self::Responses => policy.openai_responses,
            Self::AnthropicMessages => policy.anthropic_messages,
            Self::Gemini => policy.google_generative_ai,
        }
    }

    fn set(self, policy: &mut vibex_core::GatewayTranslatePolicy, allowed: bool) {
        match self {
            Self::ChatCompletions => policy.openai_chat_completions = allowed,
            Self::Responses => policy.openai_responses = allowed,
            Self::AnthropicMessages => policy.anthropic_messages = allowed,
            Self::Gemini => policy.google_generative_ai = allowed,
        }
    }
}

/// The gateway's own row summary: every upstream Key in one line.
fn gateway_overall_key_summary(
    snapshot: &vibex_core::GatewaySnapshot,
    locale: ResolvedLocale,
) -> String {
    let soonest_recovery = snapshot
        .upstreams
        .iter()
        .flat_map(|upstream| upstream.keys.iter())
        .filter_map(|key| match key.state {
            vibex_core::GatewayKeyState::Cooling { until_ms, .. } => until_ms,
            _ => None,
        })
        .min();
    gateway_key_counts_text(
        snapshot
            .upstreams
            .iter()
            .map(|upstream| upstream.keys.len())
            .sum(),
        snapshot.cooling_key_count(),
        soonest_recovery,
        snapshot.invalid_key_count(),
        locale,
    )
}

/// Key counts and the two kinds of trouble, in the page's wording.
fn gateway_key_counts_text(
    total: usize,
    cooling: usize,
    soonest_recovery: Option<i64>,
    invalid: usize,
    locale: ResolvedLocale,
) -> String {
    let keys = match locale {
        ResolvedLocale::En => format!("{total} keys"),
        ResolvedLocale::ZhCn => format!("{total} 个 Key"),
        ResolvedLocale::ZhTw => format!("{total} 個 Key"),
    };
    let mut parts = vec![keys];
    if cooling > 0 {
        // Keep the count, and add the soonest deadline when one is known: the
        // reader needs both "how many" and "until when".
        let cooling_text = match locale {
            ResolvedLocale::En => format!("{cooling} cooling"),
            ResolvedLocale::ZhCn => format!("{cooling} 个冷却中"),
            ResolvedLocale::ZhTw => format!("{cooling} 個冷卻中"),
        };
        parts.push(
            match soonest_recovery.and_then(|until_ms| {
                let remaining = until_ms.saturating_sub(vibex_core::unix_timestamp_ms());
                (remaining > 0).then_some(remaining)
            }) {
                Some(remaining_ms) => format!(
                    "{cooling_text} · {}{}",
                    remaining_ms.saturating_add(59_999) / 60_000,
                    management_locale_text_for(locale, "m", " 分钟", " 分鐘")
                ),
                None => cooling_text,
            },
        );
    }
    if invalid > 0 {
        parts.push(match locale {
            ResolvedLocale::En => format!("{invalid} invalid"),
            ResolvedLocale::ZhCn => format!("{invalid} 个已失效"),
            ResolvedLocale::ZhTw => format!("{invalid} 個已失效"),
        });
    }
    parts.join(" · ")
}

/// The Key line on the global Providers list.
///
/// A Provider that is one of the gateway's upstreams borrows the gateway's
/// richer summary (cooling, invalid, soonest recovery); every other Provider
/// only knows how many Keys it has.
/// The one metadata line a Provider card carries: how many models it offers
/// and how many Keys it holds.
fn management_provider_card_summary(
    enabled_models: usize,
    keys: usize,
    locale: ResolvedLocale,
) -> String {
    match locale {
        ResolvedLocale::En => format!("{enabled_models} models · {keys} keys"),
        ResolvedLocale::ZhCn => format!("{enabled_models} 个模型 · {keys} 个 Key"),
        ResolvedLocale::ZhTw => format!("{enabled_models} 個模型 · {keys} 個 Key"),
    }
}

/// One Key's state, labelled so colour is never the only signal.
fn gateway_key_state_badge(key: &vibex_core::GatewayKeySummary, _cx: &App) -> AnyElement {
    match key.state {
        vibex_core::GatewayKeyState::Ready => Tag::color(ColorName::Green)
            .xsmall()
            .child(management_locale_text("Active", "正常", "正常"))
            .into_any_element(),
        // A cooldown is the one state with a deadline, so it says when the Key
        // comes back. "Cooling down" alone leaves the user unable to tell a
        // 30-second rate limit from an hour-long credit problem.
        vibex_core::GatewayKeyState::Cooling { until_ms, .. } => Tag::color(ColorName::Amber)
            .xsmall()
            .child(gateway_cooldown_label(until_ms))
            .into_any_element(),
        vibex_core::GatewayKeyState::Invalid => Tag::color(ColorName::Red)
            .xsmall()
            .child(management_locale_text("Invalid", "已失效", "已失效"))
            .into_any_element(),
        vibex_core::GatewayKeyState::Disabled => Tag::color(ColorName::Neutral)
            .xsmall()
            .child(management_locale_text("Off", "已停用", "已停用"))
            .into_any_element(),
    }
}

/// The credential state as interface language.
///
/// The projection reports an enum, and an enum name is not a sentence: it is
/// translated here so the badge never shows `NotApplicable` to a user.
/// Whether an authentication state is worth a badge beside a credential field.
///
/// A state that says "this is working" is the expected one, so it stays quiet;
/// only a state the user may have to act on earns the space and the color.
fn projection_auth_state_needs_attention(state: vibex_core::ProjectionAuthState) -> bool {
    use vibex_core::ProjectionAuthState as State;
    matches!(state, State::Missing | State::Unsupported | State::Unknown)
}

fn projection_auth_state_badge(state: vibex_core::ProjectionAuthState, _cx: &App) -> AnyElement {
    use vibex_core::ProjectionAuthState as State;
    let (label, tag) = match state {
        State::Ready => (
            management_locale_text("Ready", "已就绪", "已就緒"),
            Tag::color(ColorName::Green),
        ),
        State::Missing => (
            management_locale_text("Not configured", "未配置", "未設定"),
            Tag::color(ColorName::Amber),
        ),
        State::AgentManaged => (
            management_locale_text("Managed by Agent", "由 Agent 管理", "由 Agent 管理"),
            Tag::color(ColorName::Neutral),
        ),
        State::NotApplicable => (
            management_locale_text("Not required", "无需配置", "無需設定"),
            Tag::color(ColorName::Neutral),
        ),
        State::Unsupported => (
            management_locale_text("Unsupported", "暂不支持", "暫不支援"),
            Tag::color(ColorName::Amber),
        ),
        State::Unknown => (
            management_locale_text("Unknown", "未知", "未知"),
            Tag::color(ColorName::Neutral),
        ),
    };
    tag.xsmall().child(label).into_any_element()
}

