/// A wash that lifts a surface by a hair in either appearance.
///
/// Derived from the foreground instead of a fixed grey so it keeps the same
/// relationship to the dialog on every palette in the catalog: it lightens a
/// dark surface and darkens a light one, without assuming which of the two the
/// user picked.
fn management_surface_wash(cx: &App, strength: f32) -> Hsla {
    cx.theme().foreground.opacity(strength)
}

/// The caption strip that names a pane and holds the one command local to it.
///
/// The caption is the pane's own name and the value is what it is showing, so
/// the two panes read as a matched pair rather than as two unrelated columns.
fn profile_pane_header(
    caption: &'static str,
    value: Option<SharedString>,
    trailing: Option<AnyElement>,
    cx: &App,
) -> AnyElement {
    h_flex()
        .w_full()
        .min_w_0()
        .flex_none()
        .items_center()
        .gap_2()
        .px_3()
        .py_2()
        .bg(management_surface_wash(cx, MANAGEMENT_PANEL_STRIP_WASH))
        .border_b_1()
        .border_color(cx.theme().border)
        .child(
            div()
                .flex_none()
                .text_xs()
                .font_weight(FontWeight::SEMIBOLD)
                .text_color(cx.theme().muted_foreground)
                .child(caption),
        )
        .when_some(value, |header, value| {
            header.child(
                div()
                    .min_w_0()
                    .truncate()
                    .text_xs()
                    // The caption names the pane and stays muted; the value is
                    // what the pane is showing, so it carries full contrast.
                    .text_color(cx.theme().foreground)
                    .child(value),
            )
        })
        .child(div().min_w_0().flex_1())
        .children(trailing)
        .into_any_element()
}

/// One pane of the Model editor: a named, bordered surface whose body is the
/// only part that scrolls.
///
/// The two panes share the dialog's remaining height, so the picker keeps a
/// bounded well under its rows instead of trailing off into the dialog's own
/// background, and a long catalogue scrolls inside the panel rather than
/// pushing the dialog's actions out of reach.
fn profile_pane_shell(
    id: &'static str,
    bounded: bool,
    header: AnyElement,
    body: AnyElement,
    footer: Option<AnyElement>,
    cx: &App,
) -> AnyElement {
    let mut pane = v_flex()
        .debug_selector(move || id.to_string())
        .min_w_0()
        .min_h_0()
        .overflow_hidden()
        .rounded(cx.theme().radius)
        .border_1()
        .border_color(cx.theme().border)
        .child(header)
        .child(body)
        .children(footer);
    if bounded {
        // Side by side the two panes split the row and share its height.
        pane = pane.flex_1();
    } else {
        // Stacked, each pane owns a full row and sizes to its own content.
        pane = pane.w_full();
    }
    pane.into_any_element()
}

/// One option in a row of mutually exclusive choices.
///
/// A choice has to look like a control before it is clicked. At rest the chip
/// carries a boundary and a muted label; under the pointer it lifts; chosen, it
/// takes the primary tint, a primary boundary, and the heavier label weight, so
/// the answer is legible from shape and weight as well as from color.
///
/// What a market entry costs the machine it is installed on.
///
/// The registry's transport is the one classification that changes the
/// decision: a `stdio` server runs a process here, a remote one only opens a
/// connection. It is the single chip a card carries, so it says the
/// consequence rather than repeating the protocol's own name.
fn market_transport_label(transport: vibex_core::McpServerTransportKind) -> &'static str {
    match transport {
        vibex_core::McpServerTransportKind::Stdio => {
            management_locale_text("Local process", "本地进程", "本機程序")
        }
        vibex_core::McpServerTransportKind::Http | vibex_core::McpServerTransportKind::Sse => {
            management_locale_text("Remote service", "远程服务", "遠端服務")
        }
    }
}

/// The protocol behind the chip, for the tooltip and the detail panel.
fn market_transport_kind_label(transport: vibex_core::McpServerTransportKind) -> &'static str {
    match transport {
        vibex_core::McpServerTransportKind::Stdio => "stdio",
        vibex_core::McpServerTransportKind::Http => "http",
        vibex_core::McpServerTransportKind::Sse => "sse",
    }
}

/// One glyph per transport, so a card is identifiable before it is read.
fn market_transport_icon_path(transport: vibex_core::McpServerTransportKind) -> &'static str {
    match transport {
        vibex_core::McpServerTransportKind::Stdio => "icons/vibex/square-terminal.svg",
        _ => "icons/vibex/globe.svg",
    }
}

/// What a market grid can be narrowed to, in filter order.
///
/// The filter names the consequence rather than the protocol, so `http` and
/// `sse` share one answer: from a user's side both are a remote service, and
/// two chips with the same label would be a worse filter than one.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum MarketTransportFilter {
    Local,
    Remote,
}

const MARKET_TRANSPORT_FILTERS: [MarketTransportFilter; 2] =
    [MarketTransportFilter::Local, MarketTransportFilter::Remote];

impl MarketTransportFilter {
    fn label(&self) -> &'static str {
        match self {
            Self::Local => management_locale_text("Local process", "本地进程", "本機程序"),
            Self::Remote => management_locale_text("Remote service", "远程服务", "遠端服務"),
        }
    }

    /// The wire form the runtime filters the index by.
    ///
    /// The filter is applied there rather than here because the view only ever
    /// holds one page: filtering after the page was cut would leave holes in
    /// the list and a count that does not match what is on screen.
    fn request_filter(self) -> vibex_core::McpMarketTransportFilter {
        match self {
            Self::Local => vibex_core::McpMarketTransportFilter::Local,
            Self::Remote => vibex_core::McpMarketTransportFilter::Remote,
        }
    }
}

/// An install count, shortened the way a ranking number is read.
///
/// The index returns raw totals that reach into the millions; a card fitting
/// the figure beside a repository name does not need the last six digits to
/// make its point.
fn market_installs_label(installs: u64) -> String {
    let compact = match installs {
        0..=999 => installs.to_string(),
        1_000..=999_999 => format!("{:.1}k", installs as f64 / 1_000.0),
        _ => format!("{:.1}M", installs as f64 / 1_000_000.0),
    };
    match locale::current_locale() {
        ResolvedLocale::En => format!("{compact} installs"),
        ResolvedLocale::ZhCn => format!("{compact} 次安装"),
        ResolvedLocale::ZhTw => format!("{compact} 次安裝"),
    }
}

fn market_entry_command_line(entry: &vibex_core::McpMarketEntry) -> String {
    match entry.transport {
        vibex_core::McpServerTransportKind::Stdio => {
            let mut parts = Vec::new();
            if let Some(command) = &entry.command {
                parts.push(command.clone());
            }
            parts.extend(entry.args.clone());
            parts.join(" ")
        }
        _ => entry.url.clone().unwrap_or_default(),
    }
}

/// The date part of an RFC3339 timestamp, which is all a card needs.
///
/// The registry publishes timestamps with sub-second precision and a `Z`; a
/// market card only wants to say roughly how current an entry is, so anything
/// that is not plainly `YYYY-MM-DD` is dropped rather than shown raw.
fn market_timestamp_date(timestamp: &str) -> Option<String> {
    let date = timestamp.trim().get(..10)?;
    let bytes = date.as_bytes();
    let shaped = bytes[4] == b'-'
        && bytes[7] == b'-'
        && bytes
            .iter()
            .enumerate()
            .all(|(index, byte)| matches!(index, 4 | 7) || byte.is_ascii_digit());
    shaped.then(|| date.to_string())
}

/// The publisher and freshness line under an entry's name.
///
/// A registry name is reverse-DNS, so its first segment is the publisher, and
/// the registry's own `updatedAt` says whether the entry is maintained. Both
/// were being thrown away, which is most of why the cards read as bare.
fn market_entry_publisher_line(entry: &vibex_core::McpMarketEntry) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(author) = entry
        .author
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        parts.push(author.to_string());
    }
    if let Some(updated) = entry.updated_at.as_deref().and_then(market_timestamp_date) {
        parts.push(format!(
            "{} {updated}",
            management_locale_text("Updated", "更新于", "更新於")
        ));
    }
    (!parts.is_empty()).then(|| parts.join(" · "))
}

/// What the install form is going to ask for, said before the form does.
///
/// An entry with required credentials should not look like a one-click install
/// until the user is already in the form.
fn market_entry_env_summary(entry: &vibex_core::McpMarketEntry) -> Option<String> {
    let total = entry.env.len();
    if total == 0 {
        return None;
    }
    let required = entry
        .env
        .iter()
        .filter(|variable| variable.required)
        .count();
    Some(match (locale::current_locale(), required) {
        (ResolvedLocale::ZhCn, 0) => format!("{total} 个可选变量"),
        (ResolvedLocale::ZhCn, required) => format!("{total} 个变量，其中 {required} 个必填"),
        (ResolvedLocale::ZhTw, 0) => format!("{total} 個選用變數"),
        (ResolvedLocale::ZhTw, required) => format!("{total} 個變數，其中 {required} 個必填"),
        (ResolvedLocale::En, 0) => format!("{total} optional variables"),
        (ResolvedLocale::En, required) => format!("{required} of {total} variables required"),
    })
}

/// The one state a market card calls out, or `None` for a healthy entry.
///
/// The registry publishes several independent facts about an entry and the
/// card used to print all of them, which made every result look equally
/// urgent. Only a fact the user has to act on earns a tag, and only one of
/// them: the lifecycle a publisher declared outranks the local install,
/// because a deprecated server is exactly the case where "you already have
/// this" is the less important half of the sentence.
#[derive(Debug, Clone, PartialEq, Eq)]
enum MarketEntryState {
    Removed,
    Deprecated,
    Installed,
}

impl MarketEntryState {
    fn label(&self) -> &'static str {
        match self {
            Self::Removed => management_locale_text("Removed", "已下架", "已下架"),
            Self::Deprecated => management_locale_text("Deprecated", "已弃用", "已棄用"),
            Self::Installed => management_locale_text("Installed", "已安装", "已安裝"),
        }
    }
}

/// Classify an entry into the single state its card shows.
fn market_entry_state(
    entry: &vibex_core::McpMarketEntry,
    installed: bool,
) -> Option<MarketEntryState> {
    match entry
        .status
        .as_deref()
        .map(str::trim)
        .filter(|status| !status.is_empty() && *status != "active")
    {
        Some(status) if status.eq_ignore_ascii_case("deleted") => {
            return Some(MarketEntryState::Removed);
        }
        Some(_) => return Some(MarketEntryState::Deprecated),
        None => {}
    }
    installed.then_some(MarketEntryState::Installed)
}

/// The quiet facts about an entry, gathered into one line.
///
/// What published the launcher and which version it pins are how a person
/// tells two similarly named servers apart; they are metadata, not state, so
/// they read as muted text beside the transport chip instead of as more tags.
fn market_entry_meta_line(entry: &vibex_core::McpMarketEntry) -> Option<String> {
    let mut parts = Vec::new();
    if let Some(kind) = entry
        .package_kind
        .as_deref()
        .map(str::trim)
        .filter(|kind| !kind.is_empty() && !kind.eq_ignore_ascii_case("remote"))
    {
        parts.push(kind.to_string());
    }
    if let Some(version) = entry
        .version
        .as_deref()
        .map(str::trim)
        .filter(|version| !version.is_empty())
    {
        parts.push(version.to_string());
    }
    (!parts.is_empty()).then(|| parts.join(" · "))
}

/// Turn the entry the user was shown plus the form's answers into a create
/// request. Values the form supplied win over the catalog's defaults, because
/// the form is where a credential the catalog could not know about is entered.
fn market_entry_to_candidate(
    entry: &vibex_core::McpMarketEntry,
    env_values: &[vibex_core::McpServerEnvEntry],
) -> vibex_core::McpServerCreateRequest {
    let mut env = Vec::new();
    for requirement in &entry.env {
        let supplied = env_values
            .iter()
            .find(|value| value.name == requirement.name)
            .map(|value| value.value.clone())
            .filter(|value| !value.trim().is_empty());
        let resolved = supplied.or_else(|| requirement.default_value.clone());
        if let Some(value) = resolved {
            env.push(vibex_core::McpServerEnvEntry {
                name: requirement.name.clone(),
                value,
            });
        }
    }
    // Values for names the catalog did not declare are still carried: an entry
    // may need a variable the publisher did not annotate.
    for value in env_values {
        if !env.iter().any(|existing| existing.name == value.name)
            && !value.name.trim().is_empty()
            && !value.value.trim().is_empty()
        {
            env.push(value.clone());
        }
    }
    vibex_core::McpServerCreateRequest {
        display_name: entry.name.clone(),
        transport_kind: entry.transport,
        status: vibex_core::McpServerStatus::Enabled,
        scope_kind: vibex_core::McpServerScopeKind::User,
        project_id: None,
        workspace_id: None,
        command: entry.command.clone(),
        args: entry.args.clone(),
        env,
        url: entry.url.clone(),
        headers: Vec::new(),
        description: entry.description.clone(),
        tags: vec!["market".to_string()],
        secret_references: Vec::new(),
        provider_matrix: Vec::new(),
    }
}

/// The rounded plate an entry's transport glyph sits on.
fn management_market_glyph(icon_path: &str, cx: &App) -> AnyElement {
    h_flex()
        .size(px(34.0))
        .flex_none()
        .items_center()
        .justify_center()
        .rounded(cx.theme().radius)
        .border_1()
        .border_color(cx.theme().border.opacity(0.60))
        .bg(cx.theme().muted.opacity(0.30))
        .child(
            Icon::default()
                .path(icon_path)
                .size(px(16.0))
                .text_color(cx.theme().muted_foreground),
        )
        .into_any_element()
}

/// A classification chip: the transport an entry installs as.
///
/// Outline-only and muted on purpose. A card carries at most one of these, so
/// the tag that reports state is the only thing on it allowed to be loud.
fn management_market_chip(label: impl Into<SharedString>) -> AnyElement {
    Tag::color(ColorName::Neutral)
        .outline()
        .xsmall()
        .child(label.into())
        .into_any_element()
}

/// The state tag on a market card, in the one tone its meaning deserves.
fn management_market_state_tag(state: &MarketEntryState, _cx: &App) -> AnyElement {
    let tag = match state {
        // "You already have this" is information, not a warning, so it keeps
        // the quieter outline treatment.
        MarketEntryState::Installed => Tag::color(ColorName::Green).outline(),
        MarketEntryState::Deprecated => Tag::color(ColorName::Amber),
        MarketEntryState::Removed => Tag::color(ColorName::Red),
    };
    tag.xsmall().child(state.label()).into_any_element()
}

/// The launcher or address a market card puts under its title.
///
/// The glyph is the entry's transport, so the reader can tell an address from a
/// command before parsing the text, and it is one of the paths already bundled
/// with the app rather than a new asset.
struct MarketCardEndpoint {
    text: String,
    icon_path: &'static str,
}

/// One market result, as a card.
///
/// The card is a chooser, not a container. It answers one question — "is this
/// the server I want?" — so its reading order follows that question: identity
/// first, then what the entry does, then the facts that tell it apart from a
/// neighbour. Everything that did not answer the question was removed: the
/// transport glyph is drawn at its own size instead of on a plate, the address
/// is a line of text instead of a panel inside the panel, and the footer has no
/// rule of its own because the card's boundary already separates it from the
/// grid.
///
/// The card is also not a control. It used to blend its background under the
/// pointer while offering no click, which promised an action that did not
/// exist; the Install button is the card's only affordance and says so.
///
/// Every card in a row keeps the same height and puts its actions on the same
/// baseline: the description and metadata take the slack, and the footer is
/// pinned to the bottom, so a short entry does not leave its Install button
/// floating halfway up the row.
#[allow(clippy::too_many_arguments)]
fn management_market_card(
    id: String,
    glyph_path: &'static str,
    name: String,
    state: Option<MarketEntryState>,
    meta: Option<String>,
    description: Option<String>,
    chip: Option<String>,
    quiet_meta: Option<String>,
    caution: Option<String>,
    endpoint: Option<MarketCardEndpoint>,
    link: Option<(String, AnyElement)>,
    install: AnyElement,
    cx: &App,
) -> AnyElement {
    // Identity owns the strongest type on the card. The grid is a name picker,
    // so the name takes the step above the body text rather than sitting on it.
    let identity = div()
        .min_w_0()
        .flex_1()
        .truncate()
        .text_base()
        .font_semibold()
        .child(name);

    // Who published the entry, how current it is, and which package it pins are
    // one class of fact. They share a single muted line instead of claiming a
    // row each and pushing the description down the card.
    let facts_line = match (meta, quiet_meta) {
        (Some(meta), Some(quiet)) => Some(format!("{meta} · {quiet}")),
        (meta, quiet) => meta.or(quiet),
    };

    let mut body = v_flex()
        .min_w_0()
        .flex_1()
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(
                    Icon::default()
                        .path(glyph_path)
                        .size(px(16.0))
                        .flex_none()
                        .text_color(cx.theme().muted_foreground),
                )
                .child(identity)
                .children(
                    state
                        .as_ref()
                        .map(|state| management_market_state_tag(state, cx)),
                ),
        )
        .children(facts_line.map(|facts| {
            div()
                .w_full()
                .min_w_0()
                .truncate()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(facts)
        }))
        // What the server does is what decides the click, so it is read before
        // the address it happens to run on.
        .children(description.map(|description| {
            div()
                .w_full()
                .text_sm()
                // `line_clamp` on its own clips the last line at the wrap point,
                // so a long description ended mid-word with no mark that
                // anything was missing. The ellipsis is what makes the clamp
                // read as a summary rather than as a broken string.
                .line_clamp(2)
                .text_ellipsis()
                .text_color(cx.theme().muted_foreground)
                .child(description)
        }));

    // The transport and the address are one line: the chip classifies the entry
    // and the monospace value identifies it. The leading glyph is what makes the
    // value read as an address rather than as another line of metadata.
    if chip.is_some() || endpoint.is_some() {
        let mut endpoint_row = h_flex().w_full().min_w_0().items_center().gap_2();
        if let Some(chip) = chip {
            endpoint_row = endpoint_row.child(management_market_chip(chip));
        }
        if let Some(endpoint) = endpoint {
            endpoint_row = endpoint_row
                .child(
                    Icon::default()
                        .path(endpoint.icon_path)
                        .size(px(12.0))
                        .flex_none()
                        .text_color(cx.theme().muted_foreground),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .truncate()
                        .font_family(cx.theme().mono_font_family.clone())
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(endpoint.text),
                );
        }
        body = body.child(endpoint_row);
    }

    if let Some(caution) = caution {
        // A server that needs a credential before it runs is not a one-click
        // install, and saying so on the card is fairer than saying it only once
        // the form is open.
        body = body.child(
            h_flex()
                .w_full()
                .min_w_0()
                .gap_1p5()
                .text_xs()
                .text_color(cx.theme().warning)
                .child(Icon::new(IconName::TriangleAlert).size(px(12.0)))
                .child(div().min_w_0().child(caution)),
        );
    }

    let mut footer = h_flex().w_full().min_w_0().items_center().gap_2();
    match link {
        Some((_, element)) => footer = footer.child(element),
        None => footer = footer.child(div()),
    }
    footer = footer.child(div().flex_1()).child(install);
    body = body
        // Absorbs whatever height the tallest card in the row adds, so the
        // footer lands on the bottom edge instead of floating mid-card. The gap
        // is what separates it from the content; a rule here would repeat the
        // card's own boundary one line above itself.
        .child(div().flex_1())
        .child(footer.pt_2());

    v_flex()
        .id(SharedString::from(format!("management-market-entry-{id}")))
        .min_w(px(MANAGEMENT_MARKET_CARD_MIN_WIDTH))
        .flex_1()
        .min_h(px(MANAGEMENT_MARKET_CARD_MIN_HEIGHT))
        .rounded(cx.theme().radius_lg)
        .border_1()
        .border_color(cx.theme().border.opacity(0.80))
        .bg(theme::semantic_color("card", cx.theme().is_dark()).opacity(0.72))
        .p_3()
        .child(body)
        .into_any_element()
}

/// Turn a market failure into something a person can act on.
///
/// The registry is slow and sometimes unreachable, and the raw transport error
/// for both reads the same — "error sending request" — which tells a user
/// nothing about whether to wait or check their network.
fn management_market_error_text(code: &str, message: &str) -> String {
    let hint = match code {
        "market_unreachable" => Some(management_locale_text(
            "The registry could not be reached. It is slow under load, so retrying often works; check the network if it keeps failing.",
            "无法连接注册表。注册表在负载高时响应较慢，重试通常可以成功；若持续失败请检查网络。",
            "無法連線登錄表。登錄表在負載高時回應較慢，重試通常可以成功；若持續失敗請檢查網路。",
        )),
        "market_rejected" => Some(management_locale_text(
            "The registry refused the request. It may be rate limiting; try again shortly.",
            "注册表拒绝了请求，可能正在限流，请稍后重试。",
            "登錄表拒絕了請求，可能正在限流，請稍後重試。",
        )),
        "market_response_too_large" | "market_malformed" => Some(management_locale_text(
            "The registry returned something this build cannot read.",
            "注册表返回了当前版本无法解析的内容。",
            "登錄表傳回了目前版本無法解析的內容。",
        )),
        _ => None,
    };
    match hint {
        Some(hint) => format!("{hint} ({code})"),
        None => format!("{code}: {message}"),
    }
}

/// A market failure, said in the kit's own alert rather than a hand-rolled box.
///
/// The banner is dismissible so a stale failure does not sit over a grid that
/// has since loaded, and it keeps the registry's own code in the title where a
/// bug report can quote it.
fn management_market_banner(id: &'static str, message: String) -> AnyElement {
    Alert::error(id, message)
        .small()
        // The banner is part of the same column as the grid, so it stops where
        // the cards stop rather than running under the scrollbar's lane.
        .pr(SCROLLBAR_GUTTER)
        .icon(IconName::TriangleAlert)
        .title(management_locale_text(
            "The market could not be read",
            "无法读取市场",
            "無法讀取市場",
        ))
        .into_any_element()
}

/// The placeholders a market grid shows on its first load.
///
/// Cards, not rows: the placeholder has to occupy the same grid the results
/// will, or the pane resizes the moment they land.
fn management_market_placeholders(count: usize, cx: &App) -> Vec<AnyElement> {
    (0..count)
        .map(|index| {
            v_flex()
                .id(("management-market-placeholder", index))
                .min_w(px(MANAGEMENT_MARKET_CARD_MIN_WIDTH))
                .flex_1()
                .min_h(px(MANAGEMENT_MARKET_CARD_MIN_HEIGHT))
                .gap_3()
                .rounded(cx.theme().radius_lg)
                .border_1()
                .border_color(cx.theme().border.opacity(0.70))
                .p_3()
                .child(
                    h_flex()
                        .w_full()
                        .items_start()
                        .gap_2p5()
                        .child(skeleton::skeleton_bar(34.0, 0.11, cx))
                        .child(
                            v_flex()
                                .min_w_0()
                                .flex_1()
                                .gap_2()
                                .child(skeleton::skeleton_bar(12.0, 0.55, cx))
                                .child(skeleton::skeleton_bar(10.0, 0.38, cx))
                                .child(skeleton::skeleton_bar(10.0, 0.92, cx)),
                        ),
                )
                .child(
                    v_flex()
                        .w_full()
                        .gap_2()
                        .child(skeleton::skeleton_bar(10.0, 0.30, cx))
                        .child(
                            h_flex()
                                .w_full()
                                .justify_between()
                                .child(skeleton::skeleton_bar(12.0, 0.18, cx))
                                .child(skeleton::skeleton_bar(12.0, 0.20, cx)),
                        ),
                )
                .into_any_element()
        })
        .collect()
}

/// A one-line progress row for a view that has no grid to stand in for.
