/// Entries a market grid shows on one page.
///
/// The MCP market asks the runtime for exactly one page: its index holds the
/// whole registry, and the reader only ever looks at one screen, so the page is
/// addressed by offset rather than shipped whole. The Skill index ignores the
/// offset outright, so that market fetches one window and pages it locally.
const MARKET_PAGE_SIZE: usize = 20;

/// Entries the Skill market fetches in one go.
///
/// This is one page of the registry's catalog, and the registry caps a page
/// below it: the runtime clamps the request to what the registry will serve, so
/// asking for more would only misreport what arrived. The grid pages through
/// what it holds locally, and the rest of the catalog is reached by following
/// the cursor the registry hands back with each page.
const SKILL_MARKET_FETCH_LIMIT: u32 = 60;

/// The width a market card refuses to go under.
///
/// The pane is whatever the sidebar leaves, so the grid has to fit two cards at
/// a common window width and three at a wide one; a card narrower than this
/// cannot hold its glyph, its address and its action on one line.
const MANAGEMENT_MARKET_CARD_MIN_WIDTH: f32 = 260.0;

/// The height a market card keeps even when an entry has little to say.
///
/// Cards in a row stretch to the tallest one, so this is only a floor: it stops
/// a row of one-line entries from collapsing into a strip. The body's trailing
/// spacer is what actually pins the footer once a taller neighbour sets the
/// height.
const MANAGEMENT_MARKET_CARD_MIN_HEIGHT: f32 = 150.0;

/// How long the MCP market waits before asking again for a wider index.
///
/// The runtime indexes the registry a page at a time in the background, and a
/// page takes a few seconds to land. Polling slower than that keeps the view
/// filling without spinning, and the poll stops as soon as the registry is
/// exhausted or the view closes.
const MCP_MARKET_INDEX_POLL_INTERVAL: Duration = Duration::from_millis(2500);

/// Pages a fetched window divides into.
///
/// An empty window still reports one page so the control has a stable value
/// instead of collapsing.
fn market_page_count(entries: usize) -> usize {
    entries.div_ceil(MARKET_PAGE_SIZE).max(1)
}

/// The page a view should show, clamped to the window it is paging through.
///
/// A search that shrinks the results, or a window that closes under the pager,
/// cannot leave the view pointing past the last page.
fn market_page(page: usize, total: usize) -> usize {
    page.clamp(1, market_page_count(total))
}

/// The slice of a fetched window that one page shows.
fn market_page_slice<T>(entries: &[T], page: usize) -> &[T] {
    let start = page.saturating_sub(1).saturating_mul(MARKET_PAGE_SIZE);
    let end = start.saturating_add(MARKET_PAGE_SIZE).min(entries.len());
    entries.get(start..end).unwrap_or_default()
}

/// The count line above a market grid.
fn management_market_result_count(shown: usize, total: usize) -> String {
    match locale::current_locale() {
        ResolvedLocale::En => format!("Showing {shown} of {total}"),
        ResolvedLocale::ZhCn => format!("已显示 {shown} / {total}"),
        ResolvedLocale::ZhTw => format!("已顯示 {shown} / {total}"),
    }
}

/// The pager strip along the bottom of a market pane.
///
/// The strip owns the whole footer: it spans the pane's width with the grid's
/// own top border, and the control sits centered in it, so the results above
/// are the only thing competing for the reader's attention.
fn management_market_pager(
    id: &'static str,
    page: usize,
    total: usize,
    on_page: impl Fn(&usize, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    h_flex()
        .w_full()
        .min_w_0()
        .flex_none()
        .items_center()
        .border_t_1()
        .border_color(cx.theme().border.opacity(0.70))
        .pt_2p5()
        .child(
            Pagination::new(id)
                .small()
                // The strip already supplies the separation from the grid.
                .py_0()
                .w_full()
                .justify_center()
                .current_page(page)
                .total_pages(market_page_count(total))
                .visible_pages(5)
                .on_click(on_page),
        )
        .into_any_element()
}

/// The exact launcher the install would save, shown before it is saved.
///
/// Monospace, on a recessed surface, with the copy affordance attached to the
/// value rather than to the section: the command is the one thing on this pane
/// a user may need to paste somewhere else.
fn management_market_command_preview(command: &str, cx: &App) -> AnyElement {
    h_flex()
        .w_full()
        .min_w_0()
        .flex_none()
        .items_start()
        .gap_2()
        .rounded(cx.theme().radius)
        .border_1()
        .border_color(cx.theme().border)
        .bg(cx.theme().muted.opacity(0.25))
        .py_2()
        .pl_3()
        .pr_1()
        .child(
            div()
                .min_w_0()
                .flex_1()
                .font_family(cx.theme().mono_font_family.clone())
                .font_weight(code_font_weight(cx))
                .text_xs()
                .text_color(cx.theme().foreground.opacity(0.85))
                .child(command.to_string()),
        )
        .child(
            Clipboard::new("management-market-command-copy")
                .value(command.to_string())
                .tooltip(management_locale_text(
                    "Copy command",
                    "复制命令",
                    "複製命令",
                )),
        )
        .into_any_element()
}

/// A section heading inside the market's detail panel.
///
/// `actions` are shortcuts that answer the whole section at once — they sit on
/// the heading's trailing edge rather than under the list, because they act on
/// the section as a whole and the list is what deserves the vertical space.
/// What a Skill bundle carries beside its manifest.
///
/// The files are part of the Skill — its references, scripts and templates —
/// so they are listed by path and size rather than summarised as a count. A
/// file the host refused is listed too, with the reason, because a Skill whose
/// scripts quietly did not arrive is not the Skill that was described.
fn management_skill_bundle_section(
    document: &vibex_core::SkillMarketDocument,
    cx: &App,
) -> AnyElement {
    let mut list = v_flex().w_full().min_w_0().gap_1();
    for file in &document.files {
        list = list.child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(
                    Icon::new(IconName::File)
                        .size(px(14.0))
                        .text_color(cx.theme().muted_foreground),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .truncate()
                        .text_xs()
                        .child(file.path.clone()),
                )
                .child(
                    div()
                        .flex_none()
                        .text_xs()
                        .text_color(cx.theme().muted_foreground)
                        .child(management_byte_size(file.bytes)),
                ),
        );
    }
    for skipped in &document.skipped_files {
        list = list.child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_start()
                .gap_2()
                .child(
                    Icon::new(IconName::TriangleAlert)
                        .size(px(14.0))
                        .text_color(cx.theme().warning),
                )
                .child(
                    div()
                        .min_w_0()
                        .flex_1()
                        .text_xs()
                        .text_color(cx.theme().warning)
                        .child(skipped.clone()),
                ),
        );
    }

    let count = document.files.len();
    management_market_section(
        management_locale_text("Bundled files", "附带文件", "附帶檔案"),
        Some(management_locale_text(
            "These files are written beside SKILL.md.",
            "这些文件会随 SKILL.md 一起写入。",
            "這些檔案會隨 SKILL.md 一起寫入。",
        )),
        Some(
            div()
                .flex_none()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(format!(
                    "{count} · {}",
                    management_byte_size(document.bundle_bytes)
                ))
                .into_any_element(),
        ),
        list.into_any_element(),
        cx,
    )
}

/// A byte count as a short human-readable size.
fn management_byte_size(bytes: u64) -> String {
    const KIB: u64 = 1024;
    const MIB: u64 = 1024 * KIB;
    match bytes {
        bytes if bytes >= MIB => format!("{:.1} MB", bytes as f64 / MIB as f64),
        bytes if bytes >= KIB => format!("{:.1} KB", bytes as f64 / KIB as f64),
        bytes => format!("{bytes} B"),
    }
}

fn management_market_section(
    title: &'static str,
    description: Option<&'static str>,
    actions: Option<AnyElement>,
    content: AnyElement,
    cx: &App,
) -> AnyElement {
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_start()
                .gap_2()
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap(px(2.0))
                        .child(div().text_sm().font_semibold().child(title))
                        .children(description.map(|description| {
                            div()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(description)
                        })),
                )
                .children(actions),
        )
        .child(content)
        .into_any_element()
}

/// The enable-for section both market install forms share.
///
/// The rows are the ones the resource's own detail panel draws — the Agent's
/// glyph, its label, its id, and a switch — so a scope chosen during install
/// reads exactly like the one edited afterwards. The two shortcuts on the
/// heading are the whole answer in one click, which is what most installs want.
fn management_market_enablement_section(
    id_prefix: &'static str,
    agents: Vec<AgentSnapshotEntry>,
    selected: &BTreeSet<String>,
    pending: bool,
    on_toggle: impl Fn(&mut ManagementCenter, &str, bool, &mut Window, &mut Context<ManagementCenter>)
    + Clone
    + 'static,
    on_set_all: impl Fn(&mut ManagementCenter, bool, &mut Window, &mut Context<ManagementCenter>)
    + Clone
    + 'static,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let mut rows = v_flex().w_full().gap_1();
    let mut any_agent = false;
    for agent in agents.into_iter().filter(|agent| agent.added) {
        any_agent = true;
        let agent_id = agent.id.as_str().to_string();
        let checked = selected.contains(&agent_id);
        let toggle = on_toggle.clone();
        let toggle_id = agent_id.clone();
        rows = rows.child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .rounded(px(6.0))
                .border_1()
                .border_color(cx.theme().border.opacity(0.60))
                .px_2()
                .py_2()
                .child(management_agent_glyph(
                    agent.id.as_str(),
                    &agent.label,
                    false,
                    cx,
                ))
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap_1()
                        .child(
                            div()
                                .truncate()
                                .text_sm()
                                .font_medium()
                                .child(agent.label.clone()),
                        )
                        .child(
                            div()
                                .truncate()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                // A scope chosen here is the user's own answer,
                                // which is the same thing the detail panel calls
                                // `manual` once it is saved.
                                .child(format!("{} · manual", agent.id)),
                        ),
                )
                .child(
                    Switch::new(SharedString::from(format!("{id_prefix}-agent-{agent_id}")))
                        .small()
                        .checked(checked)
                        .disabled(pending)
                        .on_click(cx.listener(move |this, checked, window, cx| {
                            toggle(this, &toggle_id, *checked, window, cx);
                        })),
                ),
        );
    }

    let enable_all = on_set_all.clone();
    let disable_all = on_set_all;
    let actions = h_flex()
        .flex_none()
        .items_center()
        .gap_1()
        .child(
            Button::new(SharedString::from(format!("{id_prefix}-enable-all")))
                .xsmall()
                .ghost()
                .label(management_locale_text("Enable all", "全部启用", "全部啟用"))
                .disabled(pending)
                .on_click(
                    cx.listener(move |this, _, window, cx| enable_all(this, true, window, cx)),
                ),
        )
        .child(
            Button::new(SharedString::from(format!("{id_prefix}-disable-all")))
                .xsmall()
                .ghost()
                .label(management_locale_text(
                    "Disable all",
                    "全部取消",
                    "全部取消",
                ))
                .disabled(pending)
                .on_click(
                    cx.listener(move |this, _, window, cx| disable_all(this, false, window, cx)),
                ),
        );

    management_market_section(
        management_locale_text("Enable for", "启用范围", "啟用範圍"),
        Some(management_locale_text(
            "The Agents that may use this once it is saved.",
            "保存后可以使用该资源的 Agent。",
            "儲存後可以使用該資源的 Agent。",
        )),
        Some(actions.into_any_element()),
        if any_agent {
            rows.into_any_element()
        } else {
            div()
                .w_full()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child(management_locale_text(
                    "No Agent has been added yet, so this will be saved without one.",
                    "尚未添加任何 Agent，该资源将不带启用范围保存。",
                    "尚未新增任何 Agent，該資源將不帶啟用範圍儲存。",
                ))
                .into_any_element()
        },
        cx,
    )
}

/// The identity band at the top of a market detail panel.
///
/// The link to the entry's own page rides on the title row rather than under
/// the description: it belongs to the entry's identity, and putting it there
/// keeps the description free to be read on its own.
#[allow(clippy::too_many_arguments)]
fn management_market_detail_header(
    glyph: AnyElement,
    name: String,
    state: Option<MarketEntryState>,
    meta: Option<String>,
    description: Option<String>,
    link: Option<AnyElement>,
    cx: &App,
) -> AnyElement {
    let identity = div()
        .min_w_0()
        .flex_1()
        .truncate()
        .text_lg()
        .font_semibold()
        .child(name);
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_start()
                .gap_3()
                .child(glyph)
                .child(
                    v_flex()
                        .min_w_0()
                        .flex_1()
                        .gap(px(2.0))
                        .child(
                            h_flex()
                                .w_full()
                                .min_w_0()
                                .gap_2()
                                .child(identity)
                                .children(
                                    state
                                        .as_ref()
                                        .map(|state| management_market_state_tag(state, cx)),
                                ),
                        )
                        .children(meta.map(|meta| {
                            div()
                                .w_full()
                                .min_w_0()
                                .truncate()
                                .text_xs()
                                .text_color(cx.theme().muted_foreground)
                                .child(meta)
                        })),
                )
                .children(link),
        )
        .children(description.map(|description| {
            div()
                .w_full()
                .text_sm()
                .text_color(cx.theme().muted_foreground)
                .child(description)
        }))
        .into_any_element()
}

/// The toolbar above a market grid: a query field, the one command that re-runs
/// the search, and the filters that narrow the result underneath.
///
/// The filters sit on their own line rather than beside the field: they narrow
/// the answer the query already produced, so they read as a second, quieter
/// decision under the search instead of competing with it for the same row.
fn management_market_toolbar(
    search_id: &'static str,
    query_input: &Entity<InputState>,
    loading: bool,
    disabled: bool,
    on_search: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    filters: Option<AnyElement>,
    cx: &App,
) -> AnyElement {
    v_flex()
        .w_full()
        .min_w_0()
        .flex_none()
        // The grid below reserves the overlay scrollbar's lane, so this row
        // reserves the same one: the search field and the cards share a right
        // edge instead of ending 12px apart.
        .pr(SCROLLBAR_GUTTER)
        .gap_2()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(div().min_w(px(220.0)).flex_1().child(
                    Input::new(query_input).w_full().cleanable(true).prefix(
                        Icon::new(IconName::Search).text_color(cx.theme().muted_foreground),
                    ),
                ))
                .child(
                    Button::new(search_id)
                        // The icon slot is what shows the button's progress: while
                        // the request is in flight the spinner takes the place of
                        // the glyph, so the search says it is working in the same
                        // place the user pressed.
                        .small()
                        .outline()
                        .h(MANAGEMENT_SIDEBAR_CONTROL_HEIGHT)
                        .px_4()
                        .icon(IconName::Search)
                        .label(management_locale_text("Search", "搜索", "搜尋"))
                        .loading(loading)
                        .disabled(disabled)
                        .on_click(on_search),
                ),
        )
        .children(filters)
        .into_any_element()
}

/// The transport filter as a row of mutually exclusive chips.
///
/// "All" is a chip of its own rather than an absence of selection, so the
/// current narrowing is always visible and always reversible from the same
/// place it was applied.
fn management_market_transport_filters(
    id_prefix: &'static str,
    selected: Option<MarketTransportFilter>,
    disabled: bool,
    on_select: impl Fn(&Option<MarketTransportFilter>, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    let on_select = std::rc::Rc::new(on_select);
    let mut row = h_flex()
        .min_w_0()
        .flex_none()
        .gap_1()
        .child(management_option_chip(
            SharedString::from(format!("{id_prefix}-all")),
            SharedString::from(management_locale_text("All", "全部", "全部")),
            selected.is_none(),
            disabled,
            None,
            {
                let on_select = on_select.clone();
                move |_, window, cx| on_select(&None, window, cx)
            },
            cx,
        ));
    for filter in MARKET_TRANSPORT_FILTERS {
        let checked = selected == Some(filter);
        row = row.child(management_option_chip(
            SharedString::from(format!("{id_prefix}-{filter:?}")),
            SharedString::from(filter.label()),
            checked,
            disabled,
            None,
            {
                let on_select = on_select.clone();
                move |_, window, cx| on_select(&Some(filter), window, cx)
            },
            cx,
        ));
    }
    row.into_any_element()
}

/// The Skill market's ranking as a row of mutually exclusive chips.
///
/// The registry ranks its own catalog, so the ranking is part of the request
/// rather than a sort applied to the page already in hand: switching it asks
/// again from the first page. Only the browse list offers it — a ranked search
/// is the registry's own relevance order and has nothing to re-rank.
fn management_market_sort_filters(
    id_prefix: &'static str,
    selected: vibex_core::SkillMarketSort,
    disabled: bool,
    on_select: impl Fn(&vibex_core::SkillMarketSort, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    let on_select = std::rc::Rc::new(on_select);
    let mut row = h_flex().min_w_0().flex_none().gap_1();
    for sort in MARKET_SKILL_SORTS {
        let checked = selected == sort;
        row = row.child(management_option_chip(
            SharedString::from(format!("{id_prefix}-{sort:?}")),
            SharedString::from(management_skill_sort_label(sort)),
            checked,
            disabled,
            None,
            {
                let on_select = on_select.clone();
                move |_, window, cx| on_select(&sort, window, cx)
            },
            cx,
        ));
    }
    row.into_any_element()
}

/// The ways the Skill market lets a browse list be ordered.
const MARKET_SKILL_SORTS: [vibex_core::SkillMarketSort; 6] = [
    vibex_core::SkillMarketSort::Recommended,
    vibex_core::SkillMarketSort::Installs,
    vibex_core::SkillMarketSort::Downloads,
    vibex_core::SkillMarketSort::Stars,
    vibex_core::SkillMarketSort::Trending,
    vibex_core::SkillMarketSort::Newest,
];

fn management_skill_sort_label(sort: vibex_core::SkillMarketSort) -> &'static str {
    use vibex_core::SkillMarketSort as Sort;
    match sort {
        Sort::Recommended => management_locale_text("Recommended", "推荐", "推薦"),
        Sort::Installs => management_locale_text("Installs", "安装量", "安裝量"),
        Sort::Downloads => management_locale_text("Downloads", "下载量", "下載量"),
        Sort::Stars => management_locale_text("Stars", "收藏", "收藏"),
        Sort::Trending => management_locale_text("Trending", "趋势", "趨勢"),
        Sort::Newest => management_locale_text("Newest", "最新", "最新"),
        // The registry also ranks by update time; the browse chips above cover
        // the orderings a user picks between, so this one is reachable only by
        // a caller that asks for it directly.
        Sort::Updated => management_locale_text("Updated", "更新时间", "更新時間"),
    }
}

/// The way back out of a market view.
///
/// The market replaces the section body, so it owns the affordance that
/// returns to whatever the sidebar had selected rather than leaving the
/// sidebar buttons as the only exit.
fn management_market_back_button(
    id: &'static str,
    label: &'static str,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
) -> AnyElement {
    Button::new(id)
        .small()
        .ghost()
        .icon(IconName::ArrowLeft)
        .label(label)
        .on_click(on_click)
        .into_any_element()
}
fn management_option_chip(
    id: SharedString,
    label: SharedString,
    checked: bool,
    disabled: bool,
    tooltip: Option<SharedString>,
    on_click: impl Fn(&bool, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    let foreground = if checked {
        cx.theme().foreground
    } else {
        cx.theme().muted_foreground
    };
    Toggle::new(id)
        .xsmall()
        .checked(checked)
        .disabled(disabled)
        .border_1()
        // An unavailable chip keeps saying which answer is current and only
        // steps back, so a disabled group is still readable as a group.
        .border_color(match (checked, disabled) {
            (true, _) => cx.theme().primary.opacity(0.55),
            (false, true) => cx.theme().border.opacity(0.55),
            (false, false) => cx.theme().border,
        })
        .bg(if checked {
            cx.theme().primary.opacity(0.14)
        } else {
            cx.theme().transparent
        })
        .text_color(if disabled {
            foreground.opacity(0.55)
        } else {
            foreground
        })
        .when(checked, |chip| chip.font_weight(FontWeight::MEDIUM))
        .when_some(tooltip, |chip, tooltip| chip.tooltip(tooltip))
        .label(label)
        .on_click(on_click)
        .into_any_element()
}

/// The caption over a row of choices inside the Model editor.
///
/// Smaller and quieter than a field label, because it names a group of controls
/// rather than one value, and the chips under it carry their own labels.
fn management_choice_group_label(label: &'static str, cx: &App) -> AnyElement {
    div()
        .w_full()
        .text_xs()
        .font_weight(FontWeight::MEDIUM)
        .text_color(cx.theme().muted_foreground)
        .child(label)
        .into_any_element()
}

/// The context-window sizes the Model editor offers as one click.
const MANAGEMENT_CONTEXT_TOKEN_PRESETS: [u64; 5] = [128_000, 200_000, 256_000, 512_000, 1_000_000];
/// The max-output sizes the Model editor offers as one click.
const MANAGEMENT_OUTPUT_TOKEN_PRESETS: [u64; 6] = [4_000, 8_000, 16_000, 32_000, 64_000, 128_000];

/// The count a quick-value chip is labelled with: `128k`, `1M`, or the number.
fn management_token_count_label(tokens: u64) -> String {
    if tokens >= 1_000_000 && tokens.is_multiple_of(1_000_000) {
        format!("{}M", tokens / 1_000_000)
    } else if tokens >= 1_000 && tokens.is_multiple_of(1_000) {
        format!("{}k", tokens / 1_000)
    } else {
        tokens.to_string()
    }
}

/// The count a token field currently holds, when it holds one.
fn current_token_field(state: &Entity<InputState>, cx: &App) -> Option<u64> {
    state.read(cx).value().trim().parse::<u64>().ok()
}

/// A token-count field with the quick values the user can click instead.
///
/// The chips sit between the label and the input because they are shortcuts to
/// the value the field holds rather than a second answer: the label names what is
/// being chosen, the chips are the common counts, and the field stays the place
/// any other count is typed.
fn management_token_field(
    label: impl Into<SharedString>,
    state: &Entity<InputState>,
    error: Option<&str>,
    presets: &'static [u64],
    id_prefix: String,
    pending: bool,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let mut input = Input::new(state).small().w_full();
    if error.is_some() {
        input = input.border_color(cx.theme().danger);
    }
    let current = current_token_field(state, cx);
    v_flex()
        .w_full()
        .min_w_0()
        .gap_1()
        .child(
            Form::new().child(
                Field::new().label(label).child(
                    v_flex()
                        .w_full()
                        .gap_1p5()
                        .child(management_token_preset_row(
                            &id_prefix, presets, current, pending, state, cx,
                        ))
                        .child(input),
                ),
            ),
        )
        .children(error.map(|message| management_field_error(message.to_string(), cx)))
        .into_any_element()
}

/// A row of quick counts for a token field.
///
/// Clicking a chip writes its count into the field below, which stays the place
/// any other count is typed; clicking the chip that is already current clears
/// the field again, so "not declared" is reachable without the keyboard. The
/// field is the answer either way — the chip is a shortcut, not a second value.
fn management_token_preset_row(
    id_prefix: &str,
    presets: &[u64],
    current: Option<u64>,
    pending: bool,
    input: &Entity<InputState>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let mut row = h_flex().w_full().flex_wrap().gap_1p5();
    for preset in presets {
        let preset = *preset;
        let selected = current == Some(preset);
        let input = input.clone();
        row = row.child(management_option_chip(
            SharedString::from(format!("{id_prefix}-{preset}")),
            SharedString::from(management_token_count_label(preset)),
            selected,
            pending,
            // Only the current chip has something extra to say; the rest are
            // named by the counts they write.
            selected.then(|| {
                SharedString::from(management_locale_text(
                    "Click again to clear",
                    "再次点击清除",
                    "再次點擊清除",
                ))
            }),
            cx.listener(move |this, _, window, cx| {
                let value = if selected {
                    String::new()
                } else {
                    preset.to_string()
                };
                input.update(cx, |state, cx| state.set_value(value, window, cx));
                this.apply_profile_model_edit(cx);
            }),
            cx,
        ));
    }
    row.into_any_element()
}

/// One entry of the declared-levels field.
///
/// The chips read levels out of the field and write them back, so an entry the
/// vocabulary does not name is kept as the text the user wrote rather than being
/// dropped by the next click, and a level's wire spelling survives a toggle.
#[derive(Debug, Clone, PartialEq, Eq)]
enum ReasoningLevelEntry {
    Level {
        level: vibex_core::ProviderReasoningEffortLevel,
        wire: Option<String>,
    },
    Raw(String),
}

impl ReasoningLevelEntry {
    fn level(&self) -> Option<vibex_core::ProviderReasoningEffortLevel> {
        self.level_and_wire().map(|(level, _)| level)
    }

    fn level_and_wire(&self) -> Option<(vibex_core::ProviderReasoningEffortLevel, Option<String>)> {
        match self {
            Self::Level { level, wire } => Some((*level, wire.clone())),
            Self::Raw(_) => None,
        }
    }

    /// The entry as the field spells it: `level`, `level=wire`, or the raw text.
    fn declaration(&self) -> String {
        match self {
            Self::Level { level, wire } => match wire {
                Some(wire) if wire != level.as_str() => format!("{level}={wire}"),
                _ => level.as_str().to_string(),
            },
            Self::Raw(text) => text.clone(),
        }
    }
}

/// Splits the declared-levels field into the entries the chips read.
fn reasoning_level_entries(text: &str) -> Vec<ReasoningLevelEntry> {
    text.split(',')
        .map(str::trim)
        .filter(|entry| !entry.is_empty())
        .map(|entry| {
            let (name, wire) = match entry.split_once('=') {
                Some((name, wire)) => (name.trim(), Some(wire.trim().to_string())),
                None => (entry, None),
            };
            match vibex_core::ProviderReasoningEffortLevel::parse(name) {
                Some(level) => ReasoningLevelEntry::Level { level, wire },
                None => ReasoningLevelEntry::Raw(entry.to_string()),
            }
        })
        .collect()
}

/// Adds a level to the declaration, or takes it back out when it is there.
///
/// Levels keep escalation order, which is the order the declaration is stored
/// and shown in, and each keeps the wire spelling it was written with. An entry
/// the vocabulary does not name keeps its own text and its own place, and an
/// emptied declaration is the "follow the Agent default" answer.
fn toggled_reasoning_levels(text: &str, level: vibex_core::ProviderReasoningEffortLevel) -> String {
    let entries = reasoning_level_entries(text);
    let mut levels = entries
        .iter()
        .filter_map(ReasoningLevelEntry::level_and_wire)
        .collect::<Vec<_>>();
    match levels.iter().position(|(current, _)| *current == level) {
        Some(index) => {
            levels.remove(index);
        }
        None => levels.push((level, None)),
    }
    levels.sort_by_key(|(level, _)| *level);

    // The levels take the slots the declared ones held, so raw entries stay
    // where the user wrote them; a level that was just added has no slot and
    // lands after them.
    let mut remaining = levels.into_iter();
    let mut ordered = Vec::with_capacity(entries.len() + 1);
    for entry in entries {
        match entry {
            ReasoningLevelEntry::Level { .. } => {
                if let Some((level, wire)) = remaining.next() {
                    ordered.push(ReasoningLevelEntry::Level { level, wire });
                }
            }
            raw => ordered.push(raw),
        }
    }
    ordered.extend(remaining.map(|(level, wire)| ReasoningLevelEntry::Level { level, wire }));
    ordered
        .iter()
        .map(ReasoningLevelEntry::declaration)
        .collect::<Vec<_>>()
        .join(", ")
}

/// A disclosure header: a quiet caption row that opens the content below it.
///
/// Collapsed by default so a rarely used group does not push the frequent
/// fields off the dialog's first screen.
fn profile_editor_disclosure(
    id: &'static str,
    label: SharedString,
    open: bool,
    trailing: Option<AnyElement>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let icon = if open {
        IconName::ChevronDown
    } else {
        IconName::ChevronRight
    };
    h_flex()
        .id(id)
        .w_full()
        .min_w_0()
        .items_center()
        .gap_2()
        .child(
            Button::new(SharedString::from(format!("{id}-toggle")))
                .xsmall()
                .ghost()
                .compact()
                .icon(Icon::new(icon).size_3p5())
                .label(label)
                .on_click(
                    cx.listener(move |this, _, _, cx| {
                        this.toggle_profile_editor_disclosure(id, cx)
                    }),
                ),
        )
        .children(trailing)
        .into_any_element()
}

fn provider_wire_api_label(wire_api: vibex_core::ProviderModelWireApi) -> &'static str {
    match wire_api {
        vibex_core::ProviderModelWireApi::OpenaiResponses => "OpenAI Responses",
        vibex_core::ProviderModelWireApi::OpenaiChatCompletions => "Chat Completions",
        vibex_core::ProviderModelWireApi::AnthropicMessages => "Anthropic Messages",
        vibex_core::ProviderModelWireApi::MistralConversations => "Mistral Conversations",
        vibex_core::ProviderModelWireApi::GoogleGenerativeAi => "Google Generative AI",
        vibex_core::ProviderModelWireApi::GoogleVertex => "Google Vertex AI",
        vibex_core::ProviderModelWireApi::AwsBedrockConverse => "AWS Bedrock Converse",
    }
}

fn provider_interface_integration_label(
    kind: vibex_core::AgentModelInterfaceIntegrationKind,
) -> &'static str {
    match kind {
        vibex_core::AgentModelInterfaceIntegrationKind::Direct => {
            management_locale_text("Direct", "直接支持", "直接支援")
        }
        vibex_core::AgentModelInterfaceIntegrationKind::Bridged => {
            management_locale_text("Bridged", "协议桥接", "協定橋接")
        }
    }
}

fn provider_protocol_url_override_label(wire_api: vibex_core::ProviderModelWireApi) -> String {
    let protocol = provider_wire_api_label(wire_api);
    match locale::current_locale() {
        ResolvedLocale::En => format!("{protocol} URL override"),
        ResolvedLocale::ZhCn => format!("{protocol} URL 覆盖"),
        ResolvedLocale::ZhTw => format!("{protocol} URL 覆寫"),
    }
}

/// The lines a management sidebar row says about its resource.
struct ManagementResourceRowText {
    /// The resource's own name.
    title: String,
    /// Where it came from, how it connects, or what it contains.
    subtitle: String,
    /// An optional trailing fact on the same line. MCP servers and Skills
    /// count the Agents that enabled them; a Prompt has no such number.
    meta: Option<String>,
}

/// One installed resource in a management sidebar.
///
/// It is the card the Agent sidebar draws — 8px radius, hairline border, a
/// leading glyph, a title line, and one muted line under it — so the three
/// sidebars read as one list instead of three separate designs. Selection is a
/// tinted surface rather than an outline box, which keeps the eye on one spine
/// down the rows.
fn management_resource_row(
    id: SharedString,
    glyph_path: &'static str,
    text: ManagementResourceRowText,
    enabled: bool,
    selected: bool,
    on_activate: impl Fn(&mut ManagementCenter, &mut Window, &mut Context<ManagementCenter>)
    + Clone
    + 'static,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let ManagementResourceRowText {
        title,
        subtitle,
        meta,
    } = text;
    // "Enabled" is the expected state, so it stays quiet; only a resource that
    // cannot be used says so. The label is localized: the row used to print the
    // projection's own `enabled`/`disabled` key.
    let status_tag = (!enabled).then(|| {
        Tag::color(ColorName::Amber)
            .xsmall()
            .child(management_locale_text("Disabled", "已停用", "已停用"))
    });
    let status_label = if enabled {
        management_locale_text("Enabled", "已启用", "已啟用")
    } else {
        management_locale_text("Disabled", "已停用", "已停用")
    };
    let accessible_label = match &meta {
        Some(meta) => format!("{title}, {status_label}, {subtitle}, {meta}"),
        None => format!("{title}, {status_label}, {subtitle}"),
    };

    let click = on_activate.clone();
    let keyboard = on_activate;
    v_flex()
        .id(id)
        .role(Role::Button)
        .aria_label(accessible_label)
        .focusable()
        .tab_index(0)
        .cursor_pointer()
        .relative()
        .w_full()
        .min_w_0()
        .gap_1()
        .overflow_hidden()
        .rounded(px(8.0))
        .border_1()
        // One selected treatment for the whole sidebar: the market entry button
        // and a chosen resource row both answer "which view is the body on", so
        // they take the same primary boundary and wash. The row used to drop its
        // border when chosen, which made the current row look less defined than
        // the ones around it.
        .border_color(if selected {
            cx.theme().primary.opacity(0.45)
        } else {
            cx.theme().border.opacity(0.65)
        })
        // Selection takes the solid accent plate and hover the light primary
        // wash, the same pairing every list in this column uses.
        .bg(if selected {
            cx.theme().accent
        } else {
            cx.theme().background.opacity(0.70)
        })
        .px_2()
        .py_2()
        .hover(|style| {
            style.bg(if selected {
                cx.theme().accent
            } else {
                cx.theme().primary.opacity(0.08)
            })
        })
        .on_click(cx.listener(move |this, _, window, cx| click(this, window, cx)))
        .on_key_down(cx.listener(move |this, event: &KeyDownEvent, window, cx| {
            if event.keystroke.key == "enter" || event.keystroke.key == "space" {
                keyboard(this, window, cx);
                cx.stop_propagation();
            }
        }))
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_1()
                .child(management_resource_sidebar_glyph(glyph_path, selected, cx))
                .child(
                    h_flex()
                        .flex_1()
                        .min_w_0()
                        .h(px(28.0))
                        .px_1()
                        .child(
                            div()
                                .min_w_0()
                                .truncate()
                                .text_sm()
                                .font_medium()
                                .child(title),
                        )
                        .children(status_tag)
                        .child(div().flex_1()),
                ),
        )
        .child(
            div()
                .pl(px(40.0))
                .truncate()
                .text_xs()
                .text_color(cx.theme().muted_foreground)
                .child(match meta {
                    Some(meta) => format!("{subtitle} · {meta}"),
                    None => subtitle,
                }),
        )
        .into_any_element()
}

/// The header of a management sidebar: the resource name and the commands that
/// add one.
///
/// The commands are labelled buttons rather than icon-only controls: creating
/// and importing are the two ways a resource enters the list, and a glyph alone
/// does not say which is which. The count that used to sit beside the title is
/// gone — the list under it already answers how many there are.
fn management_resource_sidebar_actions(
    title: &'static str,
    actions: Vec<AnyElement>,
    cx: &App,
) -> AnyElement {
    h_flex()
        .w_full()
        .min_w_0()
        .items_center()
        .gap_2()
        .child(
            div()
                .min_w_0()
                .flex_1()
                .truncate()
                // The section name sits on the same 14px scale as the commands
                // beside it and the search field under it; at 12px it read as a
                // caption for the row rather than the name of the list.
                .text_sm()
                .font_semibold()
                .text_color(cx.theme().muted_foreground)
                .child(title),
        )
        .children(actions)
        .into_any_element()
}

/// A sidebar command: an icon and the verb it performs, sized to the control
/// band it sits in rather than to the toolbar scale.
///
/// The visible label is the short verb; the tooltip and the accessible name
/// carry the full object, because "New" in a sidebar says which sidebar and
/// "New MCP server" says what is about to be created.
fn management_sidebar_action(
    id: &'static str,
    icon: Icon,
    label: &'static str,
    accessible_label: &'static str,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
) -> AnyElement {
    let accessible_label = SharedString::from(accessible_label);
    button_with_aria_label(
        Button::new(id)
            .small()
            .outline()
            .h(MANAGEMENT_SIDEBAR_CONTROL_HEIGHT)
            .px_3()
            // The glyph is drawn as content rather than through `icon()`: the
            // kit derives that slot from the button size, which would pin it to
            // the small 14px while the label already owns that scale.
            .child(
                h_flex()
                    .items_center()
                    .gap_1p5()
                    .child(icon.size(px(16.0)))
                    .child(div().text_sm().child(label)),
            )
            .tooltip(accessible_label.clone())
            .on_click(on_click),
        accessible_label,
    )
    .into_any_element()
}

/// The one button that opens a market from its sidebar.
///
/// It stays visibly engaged while the market is showing, so the sidebar always
/// answers which view the section body is on.
fn management_market_entry_button(
    id: &'static str,
    label: &'static str,
    open: bool,
    on_click: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    cx: &App,
) -> AnyElement {
    Button::new(id)
        // The same control band as the New and Import commands above it and the
        // search field below: one height, one type scale.
        .small()
        .w_full()
        .h(MANAGEMENT_SIDEBAR_CONTROL_HEIGHT)
        .px_3()
        .child(
            // The button's own content row centers what it is given, so the
            // left alignment has to be claimed by a full-width child rather
            // than by `justify_start` on the button itself.
            h_flex()
                .w_full()
                .items_center()
                .gap_1p5()
                .child(
                    Icon::default()
                        .path("icons/vibex/package.svg")
                        .size(px(16.0)),
                )
                .child(div().text_sm().child(label)),
        )
        .when(open, |button| {
            button
                .border_1()
                .border_color(cx.theme().primary.opacity(0.45))
                .bg(cx.theme().primary.opacity(0.12))
        })
        .on_click(on_click)
        .into_any_element()
}

fn management_resource_sidebar_glyph(path: &'static str, selected: bool, cx: &App) -> AnyElement {
    let (surface, foreground) = if selected {
        (
            cx.theme().primary.opacity(0.16),
            cx.theme().foreground.opacity(0.92),
        )
    } else {
        (cx.theme().muted.opacity(0.30), cx.theme().muted_foreground)
    };
    div()
        // The same 36px plate the Agent cards lead with, so the glyphs of all
        // three sidebars land on one vertical line.
        .size(px(36.0))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .rounded(cx.theme().radius)
        .bg(surface)
        .child(
            Icon::default()
                .path(path)
                .size(px(16.0))
                .text_color(foreground),
        )
        .into_any_element()
}

fn management_resource_discovery_status_label(
    status: vibex_core::ResourceDiscoveryStatus,
) -> &'static str {
    match status {
        vibex_core::ResourceDiscoveryStatus::Importable => {
            management_locale_text("Importable", "可导入", "可匯入")
        }
        vibex_core::ResourceDiscoveryStatus::AlreadyImported => {
            management_locale_text("Already imported", "已导入", "已匯入")
        }
        vibex_core::ResourceDiscoveryStatus::Unsupported => {
            management_locale_text("Unsupported", "不支持", "不支援")
        }
        vibex_core::ResourceDiscoveryStatus::Error => {
            management_locale_text("Error", "错误", "錯誤")
        }
    }
}

/// The search field for a toolbar band, sized to the controls beside it.
///
/// The standalone [`management_search_input`] stays a size larger because a
/// sidebar's search field is that column's primary control; inside a toolbar it
/// has to match the menu buttons it shares the row with.
fn management_search_input_compact(
    state: &Entity<InputState>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    Input::new(state)
        .small()
        .w_full()
        .cleanable(true)
        .prefix(Icon::new(IconName::Search).text_color(cx.theme().muted_foreground))
        .into_any_element()
}

fn management_search_input(
    state: &Entity<InputState>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    // `Input` owns its border, background and focus ring; the search field only
    // adds the leading glyph and a clear affordance. It keeps the kit's medium
    // size rather than the compact one: a search field is the primary control in
    // these sidebars, and `Input::h` is a multi-line-only setter, so the size is
    // the only honest way to make it taller than a toolbar strip.
    Input::new(state)
        .w_full()
        .cleanable(true)
        .prefix(Icon::new(IconName::Search).text_color(cx.theme().muted_foreground))
        .into_any_element()
}

fn management_input_field(
    label: impl Into<SharedString>,
    state: &Entity<InputState>,
    masked: bool,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    management_input_field_with_error(label, state, masked, None, cx)
}

/// A labeled field that also reports its own problem.
///
/// The message sits directly under the control it belongs to, so a rejected
/// value is visible without scrolling back to a status line at the end of the
/// dialog.
fn management_input_field_with_error(
    label: impl Into<SharedString>,
    state: &Entity<InputState>,
    masked: bool,
    error: Option<&str>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let mut input = Input::new(state).small().w_full();
    if masked {
        input = input.mask_toggle();
    }
    if error.is_some() {
        input = input.border_color(cx.theme().danger);
    }
    v_flex()
        .w_full()
        .min_w_0()
        .gap_1()
        .child(Form::new().child(Field::new().label(label).child(input)))
        .children(error.map(|message| management_field_error(message.to_string(), cx)))
        .into_any_element()
}

/// The badge a field wears while it still holds the value its preset supplied.
///
/// It is only ever a reading of the draft: the caller compares the current
/// value with the preset's before asking for it, so the marker disappears the
/// moment the user changes the field and comes back if the value is restored.
fn provider_preset_filled_marker(filled: bool) -> Option<&'static str> {
    filled.then(|| management_locale_text("✓ from preset", "✓ 预设已填", "✓ 預設已填"))
}

/// A labeled field that also carries its own problem and a preset marker.
///
/// The marker sits in the label row, where it reads as a property of the field
/// rather than of the value underneath it.
fn management_input_field_marked(
    label: impl Into<SharedString>,
    marker: Option<&'static str>,
    state: &Entity<InputState>,
    masked: bool,
    error: Option<&str>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let marker_color = cx.theme().success;
    let mut input = Input::new(state).small().w_full();
    if masked {
        input = input.mask_toggle();
    }
    if error.is_some() {
        input = input.border_color(cx.theme().danger);
    }
    let field = Form::new().child(match marker {
        Some(marker) => Field::new()
            .label_fn(move |_, _| {
                h_flex()
                    .items_center()
                    .gap_1p5()
                    .child(div().child(label.clone()))
                    .child(
                        div()
                            .text_xs()
                            .text_color(marker_color)
                            .child(SharedString::from(marker)),
                    )
            })
            .child(input),
        None => Field::new().label(label).child(input),
    });
    v_flex()
        .w_full()
        .min_w_0()
        .gap_1()
        .child(field)
        .children(error.map(|message| management_field_error(message.to_string(), cx)))
        .into_any_element()
}

/// The sentence a preset caveat shows, in the active locale.
///
/// The preset data carries the kind of caveat, not the sentence: the same
/// limitation has to read in every locale the app serves.
fn provider_preset_caveat_text(caveat: vibex_core::ProviderPresetCaveat) -> &'static str {
    use vibex_core::ProviderPresetCaveat::{
        FreeTierNeedsClient, ModelListExcludesPlan, ProtocolPerModel,
    };
    match caveat {
        FreeTierNeedsClient => management_locale_text(
            "Free models only work inside the vendor's own client; only paid models are listed here.",
            "免费模型只能在厂商自己的客户端里使用，这里只列出付费模型。",
            "免費模型只能在廠商自己的用戶端裡使用，這裡只列出付費模型。",
        ),
        ModelListExcludesPlan => management_locale_text(
            "Plan models are not in the vendor's model list; these come from the plan description.",
            "套餐内的模型不在厂商的模型列表里，以下来自套餐说明。",
            "套餐內的模型不在廠商的模型清單裡，以下來自套餐說明。",
        ),
        ProtocolPerModel => management_locale_text(
            "Claude models use the Anthropic API; other models use the OpenAI APIs.",
            "Claude 模型使用 Anthropic 接口，其他模型使用 OpenAI 系接口。",
            "Claude 模型使用 Anthropic 介面，其他模型使用 OpenAI 系介面。",
        ),
    }
}

/// One preset as the picker lists it.
#[derive(Debug, Clone, PartialEq, Eq)]
#[cfg(test)]
struct ProviderPresetRow {
    id: String,
    display_name: String,
    /// The line under the name: where the vendor answers, or why it needs no
    /// Key at all.
    detail: String,
    /// The plan's own price description. Vendor copy, not a computed amount.
    plan_note: Option<String>,
    /// Whether choosing this puts a caveat above the model list.
    has_caveat: bool,
}

/// One titled block of the picker.
#[derive(Debug, Clone, PartialEq, Eq)]
#[cfg(test)]
struct ProviderPresetGroup {
    title: &'static str,
    rows: Vec<ProviderPresetRow>,
}

/// Whether a preset answers to a filter term.
///
/// The term is matched against the three things a user remembers about a
/// vendor — the id, the name, and where it answers — so "deepseek",
/// "DeepSeek" and "deepseek.com" all find the same row.
fn provider_preset_matches(preset: &vibex_core::ProviderPreset, query: &str) -> bool {
    let query = query.trim().to_lowercase();
    if query.is_empty() {
        return true;
    }
    let mut haystacks = vec![preset.id.to_lowercase(), preset.display_name.to_lowercase()];
    if let Some(website) = preset.website.as_deref() {
        haystacks.push(website.to_lowercase());
        haystacks.push(provider_preset_host(website));
    }
    if let Some(plan_note) = preset.plan_note.as_deref() {
        haystacks.push(plan_note.to_lowercase());
    }
    haystacks.extend(preset.endpoints.values().map(|url| url.to_lowercase()));
    haystacks.iter().any(|haystack| haystack.contains(&query))
}

/// The host of an address, for the picker's second line.
fn provider_preset_host(url: &str) -> String {
    url.split_once("://")
        .map(|(_, rest)| rest)
        .unwrap_or(url)
        .split('/')
        .next()
        .unwrap_or(url)
        .to_string()
}

fn provider_preset_category(preset: &vibex_core::ProviderPreset) -> ProviderPresetCategory {
    let local = preset.no_key
        || preset.id.contains("ollama")
        || preset.id.contains("lmstudio")
        || preset.endpoints.values().any(|url| {
            url.contains("127.0.0.1") || url.contains("localhost") || url.contains("[::1]")
        });
    if local {
        return ProviderPresetCategory::Local;
    }
    if matches!(
        preset.id.as_str(),
        "openrouter"
            | "opencode-go"
            | "clinepass"
            | "commandcode"
            | "requesty"
            | "portkey"
            | "aihubmix"
            | "vercel-gateway"
            | "helicone"
    ) {
        return ProviderPresetCategory::Relay;
    }
    ProviderPresetCategory::Vendor
}

fn provider_preset_tiles(
    presets: Vec<vibex_core::ProviderPreset>,
    query: &str,
    categories: &BTreeSet<ProviderPresetCategory>,
) -> Vec<vibex_core::ProviderPreset> {
    presets
        .into_iter()
        .filter(|preset| provider_preset_matches(preset, query))
        .filter(|preset| categories.contains(&provider_preset_category(preset)))
        .collect()
}

fn provider_preset_icon_path(preset: &vibex_core::ProviderPreset) -> Option<&'static str> {
    match preset.id.as_str() {
        "openai" => Some("icons/openai.svg"),
        "anthropic" => Some("icons/claude.svg"),
        "google-gemini" => Some("icons/gemini.svg"),
        "qwen" => Some("icons/qwen.svg"),
        _ => None,
    }
}

fn provider_preset_logo(
    preset: &vibex_core::ProviderPreset,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let path = provider_preset_icon_path(preset);
    if let Some(path) = path {
        return div()
            .flex_none()
            .size(px(30.0))
            .flex()
            .items_center()
            .justify_center()
            .rounded(px(8.0))
            .bg(cx.theme().muted.opacity(0.45))
            .child(
                Icon::default()
                    .path(path)
                    .size(px(22.0))
                    .text_color(cx.theme().foreground),
            )
            .into_any_element();
    }
    let initial = preset
        .display_name
        .chars()
        .next()
        .map(|character| character.to_uppercase().to_string())
        .unwrap_or_else(|| "?".to_string());
    div()
        .flex_none()
        .size(px(30.0))
        .flex()
        .items_center()
        .justify_center()
        .rounded(px(8.0))
        .bg(cx.theme().muted.opacity(0.45))
        .text_sm()
        .font_semibold()
        .text_color(cx.theme().muted_foreground)
        .child(initial)
        .into_any_element()
}

/// What the picker shows for one preset, after the filter.
///
/// Vendors come first because that is what most Providers are; local servers
/// are their own group because "no Key" is their defining difference; plans are
/// last because their limits are the thing a user has to read before choosing.
#[cfg(test)]
fn provider_preset_picker_groups(
    presets: Vec<vibex_core::ProviderPreset>,
    query: &str,
) -> Vec<ProviderPresetGroup> {
    let mut vendors = Vec::new();
    let mut local = Vec::new();
    let mut plans = Vec::new();
    for preset in presets {
        if !provider_preset_matches(&preset, query) {
            continue;
        }
        let is_plan = preset.plan_note.is_some() || preset.only.is_some();
        let detail = if preset.no_key {
            management_locale_text(
                "Runs on this machine · no key needed",
                "本机运行 · 无需 Key",
                "本機執行 · 無需 Key",
            )
            .to_string()
        } else if let Some(plan_note) = preset.plan_note.as_deref() {
            plan_note.to_string()
        } else if let Some(website) = preset.website.as_deref() {
            provider_preset_host(website)
        } else {
            preset
                .endpoints
                .values()
                .next()
                .map(|url| provider_preset_host(url))
                .unwrap_or_default()
        };
        let row = ProviderPresetRow {
            id: preset.id.clone(),
            display_name: preset.display_name.clone(),
            detail,
            plan_note: preset.plan_note.clone(),
            has_caveat: !preset.caveats.is_empty(),
        };
        if is_plan {
            plans.push(row);
        } else if preset.no_key {
            local.push(row);
        } else {
            vendors.push(row);
        }
    }
    [
        (management_locale_text("Vendors", "厂商", "廠商"), vendors),
        (
            management_locale_text("Local services", "本地服务", "本機服務"),
            local,
        ),
        (
            management_locale_text("Third-party plans", "第三方套餐", "第三方套餐"),
            plans,
        ),
    ]
    .into_iter()
    .filter(|(_, rows)| !rows.is_empty())
    .map(|(title, rows)| ProviderPresetGroup { title, rows })
    .collect()
}

/// The Model entries a preset wants for one fetched catalogue.
///
/// `offered_models` decides which ids belong to the plan and supplies the plan
/// list when the vendor's answer cannot; the protocol comes from the preset so
/// a Claude-only preset's models are stored with the Anthropic protocol rather
/// than inferred when they are called. An empty `fetched` list therefore means
/// "the vendor could not answer", which is exactly the fallback case.
fn configured_models_from_preset(
    preset: &vibex_core::ProviderPreset,
    fetched: &[String],
) -> Vec<vibex_core::ProviderConfiguredModel> {
    preset
        .offered_models(fetched)
        .into_iter()
        .map(|id| vibex_core::ProviderConfiguredModel {
            id,
            display_name: None,
            enabled: true,
            wire_api: preset.default_wire_api(),
            capabilities: Default::default(),
        })
        .collect()
}

/// A labeled read-only field for a value the Agent owns. It mirrors
/// `management_input_field`'s shape so the form keeps its rhythm, renders the
/// value in a muted box instead of an editable input, and carries a Help
/// affordance explaining why the value cannot be changed.
fn management_locked_field(
    label: impl Into<SharedString>,
    value: impl Into<SharedString>,
    help: impl Into<SharedString>,
    cx: &mut Context<ManagementCenter>,
) -> AnyElement {
    let label: SharedString = label.into();
    let value: SharedString = value.into();
    let help: SharedString = help.into();
    Form::new()
        .child(
            Field::new().label(label).child(
                h_flex()
                    .w_full()
                    .min_w_0()
                    .items_center()
                    .gap_1p5()
                    .child(
                        div()
                            .flex_1()
                            .min_w_0()
                            .h_6()
                            .px_2()
                            .flex()
                            .items_center()
                            .overflow_hidden()
                            .rounded(cx.theme().radius)
                            .border_1()
                            .border_color(cx.theme().border)
                            .bg(cx.theme().muted.opacity(0.3))
                            .text_sm()
                            .text_color(cx.theme().muted_foreground)
                            .child(value),
                    )
                    .child(
                        div()
                            .id("management-locked-field-help")
                            .flex_none()
                            .p_1()
                            .cursor_default()
                            .focusable()
                            .tab_stop(true)
                            .role(Role::Button)
                            .aria_label(help.clone())
                            .child(
                                Icon::new(IconName::Info)
                                    .size_3p5()
                                    .text_color(cx.theme().muted_foreground),
                            )
                            .tooltip(move |window, cx| {
                                Tooltip::new(help.clone()).build(window, cx)
                            }),
                    ),
            ),
        )
        .into_any_element()
}

/// A labeled editor section: a muted section caption over a hairline rule,
/// followed by the section content. Keeps long dialog forms scannable.
fn profile_editor_section(
    label: &'static str,
    trailing: Option<AnyElement>,
    content: AnyElement,
    cx: &App,
) -> AnyElement {
    v_flex()
        .w_full()
        .min_w_0()
        .gap_2p5()
        .child(
            h_flex()
                .w_full()
                .min_w_0()
                .items_center()
                .gap_2()
                .child(
                    div()
                        .flex_none()
                        .text_xs()
                        .font_weight(FontWeight::SEMIBOLD)
                        // Brighter than a hint but quieter than a field label:
                        // the caption names a region, it does not label a value.
                        .text_color(cx.theme().foreground.opacity(0.85))
                        .child(label),
                )
                .child(
                    div()
                        .flex_1()
                        .h(px(1.0))
                        .rounded_full()
                        .bg(cx.theme().border),
                )
                .children(trailing),
        )
        .child(content)
        .into_any_element()
}

