/// How a route picks among its members, in the reader's terms.
fn management_catalog_age_label(fetched_at_ms: i64) -> String {
    let age = vibex_core::unix_timestamp_ms().saturating_sub(fetched_at_ms);
    let minutes = age / 60_000;
    if minutes < 1 {
        management_locale_text("just now", "刚刚", "剛剛").to_string()
    } else if minutes < 60 {
        match locale::current_locale() {
            ResolvedLocale::En => format!("{minutes}m ago"),
            ResolvedLocale::ZhCn => format!("{minutes} 分钟前"),
            ResolvedLocale::ZhTw => format!("{minutes} 分鐘前"),
        }
    } else if minutes < 24 * 60 {
        let hours = minutes / 60;
        match locale::current_locale() {
            ResolvedLocale::En => format!("{hours}h ago"),
            ResolvedLocale::ZhCn => format!("{hours} 小时前"),
            ResolvedLocale::ZhTw => format!("{hours} 小時前"),
        }
    } else {
        let days = minutes / (24 * 60);
        match locale::current_locale() {
            ResolvedLocale::En => format!("{days}d ago"),
            ResolvedLocale::ZhCn => format!("{days} 天前"),
            ResolvedLocale::ZhTw => format!("{days} 天前"),
        }
    }
}

fn management_percentile(mut values: Vec<i64>, percentile: f64) -> Option<i64> {
    if values.is_empty() {
        return None;
    }
    values.sort_unstable();
    let index = ((values.len() as f64 - 1.0) * percentile).round() as usize;
    values.get(index).copied()
}

fn management_model_limits_label(capabilities: &vibex_core::ProviderModelCapabilities) -> String {
    let mut parts = Vec::new();
    if let Some(context) = capabilities.context_tokens {
        parts.push(format!("ctx {context}"));
    }
    if let Some(output) = capabilities.output_tokens {
        parts.push(format!("out {output}"));
    }
    if capabilities.image_input == Some(true) {
        parts.push(management_locale_text("image", "图片", "圖片").to_string());
    }
    if capabilities.pdf_input == Some(true) {
        parts.push(management_locale_text("PDF", "PDF", "PDF").to_string());
    }
    if parts.is_empty() {
        management_locale_text("No declarations", "未声明", "未宣告").to_string()
    } else {
        parts.join(" · ")
    }
}

