    /// A mutation response is a complete record, so the list can show it
    /// immediately instead of waiting for the next snapshot.
    #[test]
    fn a_mutation_result_is_upserted_into_the_visible_list() {
        let mut prompts = Vec::new();
        let mut prompt = vibex_core::Prompt {
            id: vibex_core::PromptId::parse("prompt_upsert_probe").expect("fixture id"),
            display_name: "Reusable prompt".into(),
            kind: vibex_core::PromptKind::ReusablePrompt,
            status: vibex_core::PromptStatus::Enabled,
            scope_kind: vibex_core::PromptScopeKind::User,
            project_id: None,
            workspace_id: None,
            body: "Review this workspace.".into(),
            description: None,
            tags: Vec::new(),
            created_at_ms: 0,
            updated_at_ms: 0,
            deleted_at_ms: None,
        };
        upsert_prompt(&mut prompts, &prompt);
        prompt.display_name = "Edited prompt".into();
        upsert_prompt(&mut prompts, &prompt);
        assert_eq!(prompts.len(), 1, "the same record must not be duplicated");
        assert_eq!(prompts[0].display_name, "Edited prompt");

        let mut providers = Vec::new();
        let provider = vibex_core::ModelProviderProfile {
            display_name: "DeepSeek".into(),
            ..Default::default()
        };
        upsert_shared_provider(&mut providers, provider.clone());
        upsert_shared_provider(&mut providers, provider);
        assert_eq!(providers.len(), 1, "the Provider is replaced in place");
        assert_eq!(providers[0].display_name, "DeepSeek");
    }

    /// A mutation refresh must not sit behind the version probe that the first
    /// load runs. Once the content is on screen, the fast stage is enough.
    #[test]
    fn a_config_center_refresh_preempts_the_authoritative_probe() {
        let source = include_str!("management.rs");
        let refresh = source
            .split_once("    pub fn refresh(")
            .and_then(|(_, tail)| tail.split_once("    /// Reports that this authority"))
            .map(|(body, _)| body)
            .expect("Config Center refresh should remain inspectable");
        assert!(refresh.contains("if self.details_ready"));
        assert!(refresh.contains("ManagementRefreshStage::Authoritative"));
        assert!(refresh.contains("self.start_fast_snapshot(cx)"));
        assert!(refresh.contains("self.refresh_pending = true"));

        let content = source
            .split_once("    fn start_fast_snapshot(")
            .and_then(|(_, tail)| tail.split_once("    fn start_full_refresh("))
            .map(|(body, _)| body)
            .expect("the content stage should remain inspectable");
        assert!(content.contains("this.refresh(cx)"));
        assert!(content.contains("this.start_full_refresh(cx)"));
        assert!(content.contains("refresh_full_after_content"));
    }

    /// Saving a Prompt has to leave its tab clean, so the editor compares the
    /// form with the record it belongs to instead of latching a flag the save
    /// path can forget to clear.
    #[test]
    fn prompt_draft_is_measured_against_the_record_it_edits() {
        let saved = vibex_core::Prompt {
            id: vibex_core::PromptId::parse("prompt_draft_probe").expect("fixture id"),
            // The defaults `Save` fills blank fields with, so the blank form
            // asserted below is this record rather than a change to it.
            display_name: "Reusable prompt".into(),
            kind: vibex_core::PromptKind::ReusablePrompt,
            status: vibex_core::PromptStatus::Enabled,
            scope_kind: vibex_core::PromptScopeKind::User,
            project_id: None,
            workspace_id: None,
            body: "Review this workspace.".into(),
            description: None,
            tags: Vec::new(),
            created_at_ms: 0,
            updated_at_ms: 0,
            deleted_at_ms: None,
        };
        let locale = ResolvedLocale::En;

        // The form the save just submitted: the same text, so nothing is left
        // unsaved and switching tabs must not ask to discard it.
        assert!(!prompt_draft_differs_from(
            Some(&saved),
            "Reusable prompt",
            "Review this workspace.",
            locale
        ));
        // `Save` trims, and fills blank fields with the record's defaults, so
        // neither counts as a change the user still has to store.
        assert!(!prompt_draft_differs_from(
            Some(&saved),
            "  Reusable prompt  ",
            "Review this workspace.\n",
            locale
        ));
        assert!(!prompt_draft_differs_from(Some(&saved), "", "", locale));
        // An edited body or name is still a draft.
        assert!(prompt_draft_differs_from(
            Some(&saved),
            "Reusable prompt",
            "Review this workspace twice.",
            locale
        ));
        assert!(prompt_draft_differs_from(
            Some(&saved),
            "Reference",
            "Review this workspace.",
            locale
        ));
        // A Prompt that has not been created yet holds a draft as soon as it
        // has any text, and none while its fields are still blank.
        assert!(!prompt_draft_differs_from(None, "  ", "", locale));
        assert!(prompt_draft_differs_from(None, "", "Check this.", locale));
    }

    /// Quick phrases are a composer concept, so the Prompt tab owns the editor
    /// that writes them while Hooks stay behind in Advanced.
    #[test]
    fn prompts_tab_owns_the_prompt_card_and_advanced_keeps_hooks() {
        let source = include_str!("management.rs");
        let production = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .expect("management tests should remain inspectable");
        let content = production
            .split_once("    fn render_content(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_context_sidebar("))
            .map(|(body, _)| body)
            .expect("management content router should remain inspectable");
        assert!(content.contains("ManagementSection::PromptsHooks => self.render_prompts(cx)"));

        let advanced = production
            .split_once("    fn render_advanced(")
            .and_then(|(_, tail)| tail.split_once("\n    fn clear_scheduled_editor("))
            .map(|(body, _)| body)
            .expect("advanced renderer should remain inspectable");
        assert!(advanced.contains("self.render_hooks_card(cx)"));
        assert!(!advanced.contains("self.render_prompts(cx)"));
    }

    /// Prompts are listed the way MCP servers and Skills are: one card per
    /// record in the sidebar, and the body for the record it selects.
    #[test]
    fn prompt_sidebar_lists_prompts_like_every_other_resource() {
        let source = include_str!("management.rs");
        let production = source
            .split_once("\n#[cfg(test)]\nmod tests {")
            .map(|(production, _)| production)
            .expect("management tests should remain inspectable");
        let sidebar = production
            .split_once("    fn render_prompts_sidebar(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_hooks_card("))
            .map(|(body, _)| body)
            .expect("the prompts sidebar should remain inspectable");
        assert!(sidebar.contains("management_resource_row("));
        assert!(sidebar.contains("management_search_input(&self.prompt_search, cx)"));
        assert!(sidebar.contains("this.begin_new_prompt(window, cx)"));

        let editor = production
            .split_once("    fn render_prompts(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_prompts_sidebar("))
            .map(|(body, _)| body)
            .expect("the prompt editor should remain inspectable");
        assert!(editor.contains("this.save_prompt(cx)"));
        // A Prompt body is prose, so it is written in the kit's multi-line
        // textarea rather than the single-line input the name field uses.
        assert!(editor.contains("management_textarea_field("));
        // The sidebar owns the list, so the body must not draw a second copy.
        assert!(!editor.contains("management_resource_row("));
    }

