    #[test]
    fn management_primary_navigation_keeps_each_tab_caption_visible() {
        let source = include_str!("management.rs");
        let renderer = source
            .split_once("    fn render_nav(")
            .and_then(|(_, tail)| tail.split_once("\n    fn shared_providers("))
            .map(|(body, _)| body)
            .expect("management primary navigation should remain inspectable");

        // `Tab` renders `icon` *instead of* `label` when both are set, which
        // silently dropped these captions once. The caption has to stay in the
        // children slot (with `aria_label` carrying the accessible name) and the
        // tabs have to keep `flex_1()` so the pills stay equal width and the bar
        // still fills its width.
        assert!(renderer.contains(".aria_label(label)"));
        assert!(renderer.contains(".child(label)"));
        assert!(!renderer.contains(".label(label)"));
        assert!(renderer.contains("Tab::new().flex_1()"));
    }

    #[gpui::test]
    fn management_primary_navigation_paints_pill_tabs(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_component::init);
        let (_, cx) = cx.add_window_view(ManagementCenter::new);
        cx.update(|window, cx| {
            let _ = window.draw(cx);
        });
        let scale = cx.update(|window, _| window.scale_factor());
        let (primary, track) = cx.update(|_, cx| {
            (
                cx.theme().primary,
                gpui::Background::from(cx.theme().tokens.tab_bar_segmented),
            )
        });
        let quads = cx.update(|window, _| window.painted_quads());

        // The primary navigation is the first row of the wide-layout sidebar
        // (the test window is maximized), so only quads in that band matter.
        let band = quads
            .iter()
            .filter(|quad| {
                let top = quad.bounds.origin.y.as_f32() / scale;
                let left = quad.bounds.origin.x.as_f32() / scale;
                (12.0..54.0).contains(&top) && left < MANAGEMENT_SIDEBAR_WIDTH
            })
            .collect::<Vec<_>>();

        // Pill tabs paint no track, and only the active section is a filled
        // capsule; the other three stay transparent.
        let pills = band
            .iter()
            .filter(|quad| quad.background.as_solid() == Some(primary))
            .map(|quad| {
                (
                    quad.bounds.origin.x.as_f32() / scale,
                    quad.bounds.size.width.as_f32() / scale,
                    quad.bounds.size.height.as_f32() / scale,
                    quad.corner_radii.top_left.as_f32() / scale,
                )
            })
            .collect::<Vec<_>>();
        assert_eq!(
            pills.len(),
            1,
            "one filled pill for the active tab: {pills:?}"
        );
        let (left, width, height, radius) = pills[0];
        assert!(
            (left - 12.0).abs() < 0.5,
            "pill starts at the sidebar padding: {left}"
        );
        assert!((height - 32.0).abs() < 0.5, "pill height: {height}");
        assert!(
            (radius - height / 2.0).abs() < 0.5,
            "the pill is fully rounded rather than a rectangle: {radius}"
        );
        // Four equal tabs and three 4px gaps fill the 368px sidebar inside its
        // 12px padding. The bar rounds each pill outward, so the tolerance has
        // to admit one pixel of distribution.
        let expected_width = (MANAGEMENT_SIDEBAR_WIDTH - 24.0 - 12.0) / 4.0;
        assert!(
            (width - expected_width).abs() <= 1.5,
            "pill width {width} should be a quarter of the bar ({expected_width})"
        );
        assert!(
            !band.iter().any(|quad| quad.background == track),
            "pill tabs paint no segmented track"
        );
    }

    /// A pane that scrolls a body which scrolls itself would take that body's
    /// own footer off the bottom of the window: the outer container hands its
    /// child an auto height, so the view grows past the pane and the pager —
    /// or the import view's Detect command — goes with it.
    #[test]
    fn section_bodies_that_scroll_their_own_list_keep_the_pane_still() {
        assert!(management_section_body_scrolls_itself(true, false, false));
        assert!(management_section_body_scrolls_itself(false, false, true));
        assert!(management_section_body_scrolls_itself(true, false, true));
        // The install form replaces the grid and is a long form: the pane has
        // to scroll it, or it would be clipped.
        assert!(!management_section_body_scrolls_itself(true, true, false));
        // Nothing that owns its own scrolling is open.
        assert!(!management_section_body_scrolls_itself(false, false, false));
    }

    /// The pane has to bring its own full size on the branch that does not
    /// scroll. The scroll wrapper used to supply it, and `h_flex` centers a
    /// child that has no height — so a content-sized pane is centered in the
    /// window and the list inside it, which is the flex remainder, collapses
    /// to nothing.
    #[test]
    fn the_pane_that_does_not_scroll_still_fills_the_window() {
        let source = include_str!("management.rs");
        let pane = source
            .split_once("let pane = div()")
            .and_then(|(_, tail)| tail.split_once(".child(content);"))
            .map(|(body, _)| body)
            .expect("the management pane should remain inspectable");
        assert!(pane.contains("flex_1()"), "the pane should take the width");
        assert!(
            pane.contains("size_full()"),
            "the pane should take the window's height too, or the row centers it"
        );
    }

