    #[test]
    fn model_discovery_fills_the_picker_without_configuring_anything() {
        let source = include_str!("management.rs");
        let apply = source
            .split_once("    fn apply_fetched_models(")
            .and_then(|(_, tail)| tail.split_once("\n    fn fetch_provider_models("))
            .map(|(body, _)| body)
            .expect("The catalogue applier should remain inspectable");
        let profile_fetch = source
            .split_once("    fn fetch_provider_models(")
            .and_then(|(_, tail)| {
                tail.split_once(
                    "\n    /// Fetches the catalogue of the endpoint the editor is drafting.",
                )
            })
            .map(|(body, _)| body)
            .expect("Saved-Profile discovery should remain inspectable");
        let draft_fetch = source
            .split_once("    fn fetch_provider_draft_models(")
            .and_then(|(_, tail)| {
                tail.split_once("\n    /// The Provider options a draft fetch honors")
            })
            .map(|(body, _)| body)
            .expect("Draft discovery should remain inspectable");

        // Discovery writes the catalogue the picker reads, and never the Models
        // the user has chosen.
        assert!(apply.contains("&mut self.profile_available_models,"));
        assert!(
            !apply.contains("profile_configured_models"),
            "a fetch must not configure Models the user has not chosen"
        );
        for fetch in [profile_fetch, draft_fetch] {
            assert!(
                !fetch.contains("profile_configured_models ="),
                "a fetch must not configure Models the user has not chosen"
            );
        }
    }

    #[test]
    fn provider_editor_pairs_a_model_picker_with_its_settings() {
        let source = include_str!("management.rs");
        let dialog = source
            .split_once("    fn render_profile_editor_dialog(")
            .and_then(|(_, tail)| tail.split_once("\n    /// Identity: name, note, and website."))
            .map(|(body, _)| body)
            .expect("Provider dialog renderer should remain inspectable");
        let picker = source
            .split_once("    fn render_profile_candidates_pane(")
            .and_then(|(_, tail)| tail.split_once("    fn render_profile_candidate_row("))
            .map(|(body, _)| body)
            .expect("Model picker should remain inspectable");
        let settings = source
            .split_once("    fn render_profile_settings_pane(")
            .and_then(|(_, tail)| tail.split_once("    fn render_profile_model_editor("))
            .map(|(body, _)| body)
            .expect("Model settings pane should remain inspectable");
        let editor = source
            .split_once("    fn render_profile_model_editor(")
            .and_then(|(_, tail)| tail.split_once("\n    fn render_capability_suggestions("))
            .map(|(body, _)| body)
            .expect("Model editor should remain inspectable");

        assert!(dialog.contains("self.render_profile_candidates_pane("));
        assert!(dialog.contains("self.render_profile_settings_pane("));
        assert!(dialog.contains("MANAGEMENT_PROFILE_PANES_MIN_WIDTH"));
        // The catalogue is a checked list, and the custom id field adds to it.
        assert!(picker.contains("Checkbox::new("));
        assert!(picker.contains("provider-candidates-select-all"));
        assert!(picker.contains("set_visible_profile_candidates_selected"));
        assert!(picker.contains("provider-model-add"));
        // Both panes are panels: a named header over a body that scrolls, not
        // two columns of loose text sharing the dialog's own background.
        assert!(picker.contains("profile_pane_header("));
        assert!(picker.contains("profile_pane_shell("));
        assert!(settings.contains("profile_pane_header("));
        assert!(settings.contains("profile_pane_shell("));
        // The settings pane edits the selected Model, and offers to add it when
        // the Provider does not offer it yet.
        assert!(settings.contains("self.render_profile_model_editor("));
        assert!(settings.contains("provider-model-add-selected"));
        assert!(settings.contains("selected_profile_model_index()"));
        // Every group of mutually exclusive choices draws its options as chips,
        // so a choice never renders as a run of body text.
        assert!(editor.contains("management_option_chip("));
        for group in [
            "provider-model-catalog-",
            "provider-model-wire-",
            "provider-model-reasoning-",
            "provider-model-efforts-level-",
            "provider-model-capability-",
        ] {
            assert!(
                editor.contains(group),
                "the editor must keep its {group} choices"
            );
        }
        assert_eq!(
            editor.matches("management_option_chip(").count(),
            5,
            "each choice group draws its options through the shared chip"
        );
        // The token limits are quick values over a field, not a choice group, so
        // they draw through the same chip from their own helper.
        assert!(editor.contains("management_token_field("));
        assert!(editor.contains("MANAGEMENT_CONTEXT_TOKEN_PRESETS"));
        assert!(editor.contains("MANAGEMENT_OUTPUT_TOKEN_PRESETS"));
    }

    #[gpui::test]
    fn selecting_a_picker_row_loads_that_models_settings(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_component::init);
        let (center, cx) = cx.add_window_view(ManagementCenter::new);
        cx.update(|window, cx| {
            center.update(cx, |center, cx| {
                center.profile_available_models = vec![
                    test_provider_model("gpt-5", Some("GPT-5")),
                    test_provider_model("gpt-5-mini", None),
                ];
                let mut chosen = test_provider_model("gpt-5", None);
                chosen.capabilities.context_tokens = Some(128_000);
                center.profile_configured_models = vec![chosen];

                // A configured Model opens its own settings.
                center.select_profile_model("gpt-5".to_string(), window, cx);
                assert_eq!(center.selected_profile_model_index(), Some(0));
                assert_eq!(center.profile_model_edit_id.read(cx).value(), "gpt-5");
                assert_eq!(
                    center.profile_model_edit_context_tokens.read(cx).value(),
                    "128000"
                );

                // One the Provider does not offer yet has no settings to load.
                center.select_profile_model("gpt-5-mini".to_string(), window, cx);
                assert_eq!(center.selected_profile_model_index(), None);
                assert_eq!(
                    center.profile_model_selection.as_deref(),
                    Some("gpt-5-mini")
                );

                // Adding it from the settings pane opens its editor.
                center.add_selected_profile_model(window, cx);
                assert_eq!(center.profile_configured_models.len(), 2);
                assert_eq!(center.selected_profile_model_index(), Some(1));
            });
        });
    }

    /// The panes are built from live state, so drawing them is the only check
    /// that the picker and the settings survive a frame together.
    struct ProfileDialogHarness {
        dialog: Entity<ManagementProfileDialog>,
    }

    impl Render for ProfileDialogHarness {
        fn render(&mut self, _: &mut Window, _: &mut Context<Self>) -> impl IntoElement {
            self.dialog.clone()
        }
    }

    #[gpui::test]
    fn provider_editor_draws_its_model_panes(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_component::init);
        let (center, cx) = cx.add_window_view(ManagementCenter::new);
        center.update(cx, |center, _| {
            center.profile_editor_open = true;
            center
                .projection_editor
                .replace_capability(projection_capability_with_models());
            center.profile_available_models = vec![
                test_provider_model("gpt-5", Some("GPT-5")),
                test_provider_model("gpt-5-mini", None),
            ];
            let mut chosen = test_provider_model("gpt-5", None);
            chosen.capabilities.context_tokens = Some(128_000);
            center.profile_configured_models = vec![chosen];
            // The settings pane always shows one Model, which is the tallest
            // the right column ever gets.
            center.profile_model_selection = Some("gpt-5".to_string());
        });

        let dialog = cx.new(|cx| ManagementProfileDialog::new(center.clone(), cx));
        let (_, cx) = cx.add_window_view(move |_, _| ProfileDialogHarness {
            dialog: dialog.clone(),
        });

        // Wide: the picker and the settings split the width.
        let handle = cx.windows().pop().expect("test window");
        cx.simulate_window_resize(handle, gpui::size(px(1080.0), px(720.0)));
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        let band = cx
            .debug_bounds("provider-form-band")
            .expect("the wide layout must draw the identity and connection band");
        let picker = cx
            .debug_bounds("provider-candidates-pane")
            .expect("the wide layout must draw the picker");
        let settings = cx
            .debug_bounds("provider-chosen-pane")
            .expect("the wide layout must draw the settings");
        // The band's height is its content's, not its maximum: a scroll wrapper
        // that sizes to the parent would pin it to the cap and leave the panes
        // short of room they should have.
        assert!(band.size.height > px(0.0));
        assert!(
            band.size.height < px(MANAGEMENT_PROFILE_FORM_BAND_MAX_HEIGHT),
            "the band must not stretch to its maximum"
        );
        assert!(
            picker.origin.y >= band.bottom(),
            "the panes begin after the band ends"
        );
        assert!(
            picker.origin.y < band.bottom() + px(32.0),
            "the panes stay in the band's own reading order instead of drifting"
        );
        assert!(picker.size.width > px(0.0) && picker.size.height > px(0.0));
        assert!(settings.size.width > px(0.0) && settings.size.height > px(0.0));
        assert!(
            picker.origin.x < settings.origin.x,
            "the picker reads first"
        );
        assert_eq!(
            picker.origin.y, settings.origin.y,
            "the two panes share a row"
        );
        // The two panels are peers: one row, one height, one trailing edge.
        assert_eq!(
            picker.size.height, settings.size.height,
            "the two panes share a height"
        );
        assert_eq!(
            picker.bottom(),
            settings.bottom(),
            "the two panes share a baseline"
        );
        // A row keeps its own geometry inside the picker's bounded well.
        let row = cx
            .debug_bounds("provider-candidate-row-gpt-5")
            .expect("the wide layout must lay the picker rows out");
        assert!(
            row.origin.x > picker.origin.x && row.right() < picker.right(),
            "the row is inset inside the pane it belongs to"
        );
        assert!(
            row.origin.y > picker.origin.y,
            "the row sits below the pane's own header"
        );

        // Narrow: they stack, and the picker still lays its rows out.
        cx.simulate_window_resize(handle, gpui::size(px(720.0), px(720.0)));
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        let picker = cx
            .debug_bounds("provider-candidates-pane")
            .expect("the stacked layout must draw the picker");
        let settings = cx
            .debug_bounds("provider-chosen-pane")
            .expect("the stacked layout must draw the settings");
        assert!(
            picker.origin.y < settings.origin.y,
            "the settings follow the picker"
        );
        let row = cx
            .debug_bounds("provider-candidate-row-gpt-5")
            .expect("the picker must lay its rows out");
        assert!(row.size.width > px(0.0) && row.size.height > px(0.0));
    }

    /// A row click offers the Model and opens its settings, while the checkbox
    /// stays the only control that can release an offered Model.
    #[gpui::test]
    fn clicking_the_edge_of_a_picker_row_offers_that_model(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_component::init);
        let (center, cx) = cx.add_window_view(ManagementCenter::new);
        center.update(cx, |center, _| {
            center.profile_editor_open = true;
            center
                .projection_editor
                .replace_capability(projection_capability_with_models());
            center.profile_available_models = vec![
                test_provider_model("gpt-5", Some("GPT-5")),
                test_provider_model("gpt-5-mini", None),
            ];
            center.profile_configured_models = vec![test_provider_model("gpt-5", None)];
            center.profile_model_selection = Some("gpt-5".to_string());
        });

        let dialog = cx.new(|cx| ManagementProfileDialog::new(center.clone(), cx));
        let (_, cx) = cx.add_window_view(move |_, _| ProfileDialogHarness {
            dialog: dialog.clone(),
        });
        let handle = cx.windows().pop().expect("test window");
        cx.simulate_window_resize(handle, gpui::size(px(1080.0), px(720.0)));
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });

        // The leading edge is padding, not the checkbox: a click there has to
        // reach the row it belongs to instead of falling between the two
        // controls.
        let row = cx
            .debug_bounds("provider-candidate-row-gpt-5-mini")
            .expect("the picker must lay its rows out");
        cx.simulate_click(
            gpui::point(row.origin.x + px(2.0), row.center().y),
            gpui::Modifiers::none(),
        );
        cx.run_until_parked();
        assert_eq!(
            center.read_with(cx, |center, _| center.profile_configured_models.len()),
            2,
            "a click on the row is a click on its checkbox"
        );
        assert!(
            center.read_with(cx, |center, _| center
                .profile_configured_models
                .iter()
                .any(|model| model.id == "gpt-5-mini")),
            "the row the click names is the Model it offers"
        );
        // The pane follows the click, so the settings it shows are the ones the
        // declaration just created, never the previous Model's.
        assert_eq!(
            center.read_with(cx, |center, _| center.profile_model_selection.clone()),
            Some("gpt-5-mini".to_string())
        );
        assert_eq!(
            center.read_with(cx, |center, cx| center
                .profile_model_edit_id
                .read(cx)
                .value()
                .to_string()),
            "gpt-5-mini"
        );

        // Clicking the row again only re-opens it: an offered Model keeps its
        // declaration, because releasing one is the checkbox's own command
        // rather than something a click on the strip can do by accident.
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        let row = cx
            .debug_bounds("provider-candidate-row-gpt-5-mini")
            .expect("the offered row must stay listed");
        cx.simulate_click(
            gpui::point(row.origin.x + px(2.0), row.center().y),
            gpui::Modifiers::none(),
        );
        cx.run_until_parked();
        assert_eq!(
            center.read_with(cx, |center, _| center.profile_configured_models.len()),
            2,
            "a second click on the row must not release the Model it offered"
        );
        assert_eq!(
            center.read_with(cx, |center, _| center.profile_model_selection.clone()),
            Some("gpt-5-mini".to_string()),
            "the row the click names stays the one the settings pane shows"
        );

        // The checkbox is the control that unchecks, so clicking the indicator
        // itself still releases the Model.
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        let check = cx
            .debug_bounds("provider-candidate-check-gpt-5-mini")
            .expect("the picker must lay the checkbox out");
        cx.simulate_click(check.center(), gpui::Modifiers::none());
        cx.run_until_parked();
        assert_eq!(
            center.read_with(cx, |center, _| center.profile_configured_models.len()),
            1,
            "a click on the checkbox releases the Model it offered"
        );
        assert!(
            center.read_with(cx, |center, _| !center
                .profile_configured_models
                .iter()
                .any(|model| model.id == "gpt-5-mini")),
            "the released Model leaves the draft"
        );
    }

    /// The fetch command exists for an unsaved Provider as soon as the editor
    /// holds the two things a fetch reads — a request URL and a key — instead of
    /// waiting for the Provider to be saved first.
    #[gpui::test]
    fn provider_draft_fetch_waits_for_a_request_url_and_a_key(cx: &mut gpui::TestAppContext) {
        cx.update(gpui_component::init);
        let (center, cx) = cx.add_window_view(ManagementCenter::new);
        center.update(cx, |center, _| {
            center.profile_editor_open = true;
            // A draft fetch belongs to an Agent: the protocol an endpoint is
            // asked in comes from the Agent's own interfaces.
            center.selected_agent_id = Some("codex".to_string());
            center
                .projection_editor
                .replace_capability(projection_capability_with_models());
        });

        let dialog = cx.new(|cx| ManagementProfileDialog::new(center.clone(), cx));
        let (_, cx) = cx.add_window_view(move |_, _| ProfileDialogHarness {
            dialog: dialog.clone(),
        });
        let handle = cx.windows().pop().expect("test window");
        cx.simulate_window_resize(handle, gpui::size(px(1080.0), px(720.0)));
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        assert!(
            cx.debug_bounds("provider-candidates-fetch").is_none(),
            "an empty draft has nothing to fetch from"
        );

        // The address alone is not enough: an endpoint without a credential
        // cannot list anything either.
        let _ = cx.update_window(handle, |_, window, cx| {
            center.update(cx, |center, cx| {
                center.profile_base_url.update(cx, |state, cx| {
                    state.set_value("https://api.example.com", window, cx)
                });
            });
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        assert!(
            cx.debug_bounds("provider-candidates-fetch").is_none(),
            "a request URL without a key is not a fetchable draft"
        );

        let _ = cx.update_window(handle, |_, window, cx| {
            center.update(cx, |center, cx| {
                center
                    .profile_api_key
                    .update(cx, |state, cx| state.set_value("sk-draft-key", window, cx));
            });
        });
        cx.run_until_parked();
        cx.update(|window, cx| {
            window.draw(cx).clear(cx);
        });
        assert!(
            cx.debug_bounds("provider-candidates-fetch").is_some(),
            "a typed address and key make the draft fetchable"
        );
    }

    #[test]
    fn model_capabilities_survive_normalization_merge_and_catalogue_refresh() {
        let mut declared = vibex_core::ProviderModelReasoningEfforts::new();
        declared.insert(vibex_core::ProviderReasoningEffortLevel::Off, None);
        declared.insert(
            vibex_core::ProviderReasoningEffortLevel::High,
            Some("HIGH".into()),
        );
        let capabilities = vibex_core::ProviderModelCapabilities {
            reasoning: Some(true),
            reasoning_efforts: Some(declared),
            context_tokens: Some(1_000_000),
            output_tokens: Some(128_000),
            ..Default::default()
        };
        let declared_model = vibex_core::ProviderConfiguredModel {
            id: "model-a".into(),
            display_name: None,
            enabled: true,
            wire_api: None,
            capabilities: capabilities.clone(),
        };
        let mut models = vec![declared_model.clone()];

        // Saving the profile normalizes the draft; a declaration is user data
        // and must come out unchanged, or the projection would fall back to the
        // Agent default the user just overrode.
        let normalized = normalized_provider_models(&models);
        assert_eq!(normalized[0].capabilities, capabilities);

        // "Fetch models" merges new ids and refreshes metadata, but a Model that
        // survives keeps what it declared.
        merge_provider_models(
            &mut models,
            vec![vibex_core::ProviderConfiguredModel {
                id: "model-a".into(),
                display_name: Some("Model A".into()),
                enabled: true,
                wire_api: Some(vibex_core::ProviderModelWireApi::OpenaiChatCompletions),
                capabilities: Default::default(),
            }],
        );
        assert_eq!(models[0].capabilities, capabilities);
        assert_eq!(models[0].display_name.as_deref(), Some("Model A"));

        // An authoritative Agent catalogue replaces the draft; a Model the
        // catalogue still advertises keeps its declaration, a dropped one goes
        // with the rest of the draft.
        replace_provider_models_keeping_capabilities(
            &mut models,
            vec![
                vibex_core::ProviderConfiguredModel {
                    id: "model-a".into(),
                    display_name: None,
                    enabled: true,
                    wire_api: Some(vibex_core::ProviderModelWireApi::OpenaiChatCompletions),
                    capabilities: Default::default(),
                },
                vibex_core::ProviderConfiguredModel {
                    id: "model-b".into(),
                    display_name: None,
                    enabled: true,
                    wire_api: None,
                    capabilities: Default::default(),
                },
            ],
        );
        assert_eq!(models.len(), 2);
        assert_eq!(models[0].capabilities, capabilities);
        assert_eq!(models[1].capabilities, Default::default());
    }

    #[test]
    fn declared_token_limits_accept_only_positive_whole_numbers() {
        // An empty field is "not declared", which is what every projection
        // needs to keep the Agent's own default.
        assert_eq!(declared_token_limits("", ""), Ok((None, None)));
        assert_eq!(
            declared_token_limits(" 1000000 ", "128000"),
            Ok((Some(1_000_000), Some(128_000)))
        );
        // One declared side does not require the other; OpenCode ignores a
        // half-declared pair while ZCode and the Harness still write theirs.
        assert_eq!(
            declared_token_limits("262144", ""),
            Ok((Some(262_144), None))
        );

        // A zero window is not a window, and a rejected field is named so the
        // error points at the input the user has to correct.
        let zero = declared_token_limits("0", "128000").unwrap_err();
        assert!(
            zero.starts_with("agent_model_context_tokens_invalid:"),
            "{zero}"
        );
        assert_eq!(
            declared_token_limits("1000000", "0").unwrap_err(),
            "agent_model_output_tokens_invalid: must be greater than zero"
        );
        assert_eq!(
            declared_token_limits("abc", "").unwrap_err(),
            "agent_model_context_tokens_invalid: must be a whole number of tokens"
        );
        assert_eq!(
            declared_token_limits("1.5", "").unwrap_err(),
            "agent_model_context_tokens_invalid: must be a whole number of tokens"
        );
        assert_eq!(
            declared_token_limits("", "-1").unwrap_err(),
            "agent_model_output_tokens_invalid: must be a whole number of tokens"
        );
        // Beyond u32 is not a declaration either; it is a typo, and it says so
        // instead of claiming a whole number was not whole.
        assert_eq!(
            declared_token_limits("4294967296", "").unwrap_err(),
            "agent_model_context_tokens_invalid: is larger than a token limit can be"
        );
    }

