    /// A terminal sign-in commits a credential change, and verification
    /// advances the context revision as it does so. The follow-up model refresh
    /// must use the committed revision; reusing the operation's own revision
    /// trips the compare-and-set fence and reports a successful sign-in as
    /// `agent_auth_context_revision_conflict`. This surfaced as soon as
    /// OpenCode's login stopped being a silent `Agent` no-op and actually
    /// opened a terminal.
    #[test]
    fn post_sign_in_refresh_uses_the_committed_context_revision() {
        let operation = vibex_core::AgentAuthenticationOperation {
            operation_id: AgentAuthenticationOperationId::new(),
            auth_context_id: vibex_core::AgentAuthContextId::new(),
            // The revision the operation was opened against, before verification
            // committed the change.
            expected_context_revision: 4,
            method_id: "opencode-login".to_string(),
            state: vibex_core::AgentAuthenticationOperationState::Succeeded,
            error_code: None,
            created_at_ms: 0,
            updated_at_ms: 1,
        };
        let context = |revision| AgentAuthContext {
            id: operation.auth_context_id.clone(),
            agent_id: AgentId::parse("opencode").expect("valid Agent id"),
            status: AgentAuthContextStatus::Authenticated,
            account_hint: None,
            authenticated_via_method: Some("opencode-login".to_string()),
            revision,
            last_verified_at_ms: Some(2),
            created_at_ms: 0,
            updated_at_ms: 2,
        };

        let request =
            agent_auth_refresh_request_after_sign_in(&operation, &[context(5)]).expect("context");
        assert_eq!(request.auth_context_id, operation.auth_context_id);
        assert_eq!(
            request.expected_context_revision, 5,
            "the refresh must fence on the committed revision, not the operation's stale one"
        );
        assert_ne!(
            request.expected_context_revision, operation.expected_context_revision,
            "the stale operation revision is exactly what the fence rejected"
        );

        let missing = agent_auth_refresh_request_after_sign_in(&operation, &[]).unwrap_err();
        assert_eq!(missing.code, "agent_auth_context_not_found");
    }

    /// Re-authentication is offered only when the client can actually replace
    /// the credentials. Method kind alone is not evidence: `glm-acp-agent`
    /// advertises an `Agent` method and answers `authenticate` with an empty
    /// result, so the old "anything but Environment" rule offered a button that
    /// ran a no-op and reported success.
    #[test]
    fn agent_reauthentication_requires_a_drivable_method() {
        let method = |kind, effect| vibex_core::AgentAuthMethod {
            id: "sign-in".to_string(),
            name: "Sign in".to_string(),
            description: None,
            kind,
            effect,
            environment: Vec::new(),
            credential_link: None,
        };
        let mut catalog = AgentAuthCatalog {
            agent_id: AgentId::parse("glm-acp-agent").expect("valid Agent id"),
            methods: Vec::new(),
            supports_logout: false,
            status: AgentAuthStatus::Authenticated,
            refreshed_at_ms: 0,
        };

        assert!(!agent_auth_catalog_supports_reauthentication(&catalog));

        catalog.methods = vec![method(
            AgentAuthMethodKind::Environment,
            AgentAuthMethodEffect::WritesAgentStateHome,
        )];
        assert!(!agent_auth_catalog_supports_reauthentication(&catalog));

        catalog.methods = vec![method(
            AgentAuthMethodKind::Agent,
            AgentAuthMethodEffect::RequiresProviderProfile,
        )];
        assert!(!agent_auth_catalog_supports_reauthentication(&catalog));

        // glm-acp-agent: an `Agent` method with no terminal descriptor and no
        // logout capability. Nothing the client can drive, so no offer.
        catalog.methods = vec![method(
            AgentAuthMethodKind::Agent,
            AgentAuthMethodEffect::WritesAgentStateHome,
        )];
        assert!(
            !agent_auth_catalog_supports_reauthentication(&catalog),
            "an undrivable Agent method must not offer re-authentication"
        );
        assert!(
            agent_auth_catalog_is_externally_managed(&catalog),
            "and it must be explained as externally managed instead"
        );

        // codex: also an `Agent` method, but the Agent advertises a credential
        // store it can rewrite, and its adapter drives the browser itself.
        catalog.supports_logout = true;
        assert!(
            agent_auth_catalog_supports_reauthentication(&catalog),
            "an Agent that owns a rewritable credential store is drivable"
        );
        assert!(!agent_auth_catalog_is_externally_managed(&catalog));

        // opencode / auggie / deepseek: a real terminal login command.
        catalog.supports_logout = false;
        catalog.methods = vec![method(
            AgentAuthMethodKind::Terminal,
            AgentAuthMethodEffect::AgentManagedExternal,
        )];
        assert!(agent_auth_catalog_supports_reauthentication(&catalog));
        assert!(!agent_auth_catalog_is_externally_managed(&catalog));
    }

    /// A verified browser flow is a sign-in even without an advertised logout.
    ///
    /// Cursor, Grok's `grok.com`, Gemini's `oauth-personal`, Cline, CodeBuddy
    /// and Antigravity's OAuth methods answer `authenticate` by opening a
    /// browser, so gating them on `supports_logout` hid a working sign-in and
    /// claimed the credential was managed outside Vibex. The distinction is per
    /// method, not per Agent: the same Agent's API-key methods still fail
    /// closed.
    #[test]
    fn verified_browser_methods_are_offered_without_logout() {
        let method = |id: &str| vibex_core::AgentAuthMethod {
            id: id.to_string(),
            name: id.to_string(),
            description: None,
            kind: AgentAuthMethodKind::Agent,
            effect: AgentAuthMethodEffect::WritesAgentStateHome,
            environment: Vec::new(),
            credential_link: None,
        };
        let mut catalog = AgentAuthCatalog {
            agent_id: AgentId::parse("cursor").expect("valid Agent id"),
            methods: vec![method("cursor_login")],
            supports_logout: false,
            status: AgentAuthStatus::Authenticated,
            refreshed_at_ms: 0,
        };

        assert!(
            agent_auth_catalog_supports_reauthentication(&catalog),
            "cursor_login opens a browser, so re-authentication is drivable"
        );
        assert!(!agent_auth_catalog_is_externally_managed(&catalog));

        // The same Agent's API-key method does not open anything.
        catalog.methods = vec![method("cursor_api_key")];
        assert!(!agent_auth_catalog_supports_reauthentication(&catalog));

        // zcode advertises a method its bridge does not implement.
        catalog.agent_id = AgentId::parse("zcode").expect("valid Agent id");
        catalog.methods = vec![method("zcode-credentials")];
        assert!(!agent_auth_catalog_supports_reauthentication(&catalog));
        assert!(agent_auth_catalog_is_externally_managed(&catalog));
    }

    /// The explanation must not appear for an Agent whose methods are simply
    /// absent, and it must not survive once a drivable method exists.
    #[test]
    fn externally_managed_explanation_is_limited_to_undrivable_methods() {
        let agent_method = vibex_core::AgentAuthMethod {
            id: "z-ai-api-key".to_string(),
            name: "Z.AI API key".to_string(),
            description: Some("Set Z_AI_API_KEY in the environment".to_string()),
            kind: AgentAuthMethodKind::Agent,
            effect: AgentAuthMethodEffect::WritesAgentStateHome,
            environment: Vec::new(),
            credential_link: None,
        };
        let base = AgentAuthCatalog {
            agent_id: AgentId::parse("glm-acp-agent").expect("valid Agent id"),
            methods: Vec::new(),
            supports_logout: false,
            status: AgentAuthStatus::Unknown,
            refreshed_at_ms: 0,
        };

        assert!(
            !agent_auth_catalog_is_externally_managed(&base),
            "no methods at all is not the externally-managed case"
        );

        let managed = AgentAuthCatalog {
            methods: vec![agent_method.clone()],
            ..base.clone()
        };
        assert!(agent_auth_catalog_is_externally_managed(&managed));

        let drivable = AgentAuthCatalog {
            methods: vec![
                agent_method,
                vibex_core::AgentAuthMethod {
                    id: "setup".to_string(),
                    name: "Interactive setup".to_string(),
                    description: None,
                    kind: AgentAuthMethodKind::Terminal,
                    effect: AgentAuthMethodEffect::AgentManagedExternal,
                    environment: Vec::new(),
                    credential_link: None,
                },
            ],
            ..base
        };
        assert!(
            !agent_auth_catalog_is_externally_managed(&drivable),
            "one drivable method means the Agent is not externally managed"
        );
    }

